  lotterySecureRandomIndex(maxExclusive) {
    const max =
      Math.floor(
        Number(maxExclusive || 0)
      );

    if (max <= 1) {
      return 0;
    }

    const range = 0x100000000;
    const limit =
      Math.floor(range / max) * max;

    const buffer =
      new Uint32Array(1);

    let value = 0;

    do {
      crypto.getRandomValues(buffer);
      value = buffer[0];
    } while (value >= limit);

    return value % max;
  }

  shuffleLotteryRegistrations(items) {
    const result =
      Array.isArray(items)
        ? [...items]
        : [];

    for (
      let i = result.length - 1;
      i > 0;
      i--
    ) {
      const j =
        this.lotterySecureRandomIndex(
          i + 1
        );

      [result[i], result[j]] =
        [result[j], result[i]];
    }

    return result;
  }

