const ADMIN_NEZHA_DISPLAY_NAME =
  "哪吒👺賽事分析";

const ADMIN_XINYAO_DISPLAY_NAME =
  "芯瑤💕🎱539🎰電子";

let ADMIN_FIXED_CHAT_NAME =
  ADMIN_NEZHA_DISPLAY_NAME;

function formatClientAdminChatName(
  identityOrName,
  role = ""
) {
  const source =
    identityOrName &&
    typeof identityOrName ===
      "object"
      ? identityOrName
      : null;

  const adminRole =
    String(
      role ||
      source?.role ||
      ""
    );

  const raw =
    String(
      source?.name ||
      source?.adminName ||
      identityOrName ||
      ""
    )
      .normalize("NFKC")
      .trim();

  if (
    raw.includes("芯瑤") ||
    raw.includes("芯瑶") ||
    raw === "xinyao"
  ) {
    return ADMIN_XINYAO_DISPLAY_NAME;
  }

  if (
    raw.includes("哪吒") ||
    raw === "nezha"
  ) {
    return ADMIN_NEZHA_DISPLAY_NAME;
  }

  if (
    adminRole === "owner" ||
    raw === "主管理員" ||
    raw === "主管理员" ||
    !raw
  ) {
    return ADMIN_NEZHA_DISPLAY_NAME;
  }

  return raw.slice(0, 20);
}


