/*
  第60項：
  管理員 Pages 外層有時會被 PWA / Service Worker 快取成一般首頁，
  造成 iframe 實際進到 Worker "/"，原本只看 pathname 就會誤判成一般會員頁。

  現在除了 Worker 自己的 pathname，也會檢查：
  1. ?admin=1
  2. 父層 Pages 的 referrer 是否是 /admin
  這樣即使外層被快取，/admin/ 仍會顯示正確管理員登入畫面。
*/
let adminReferrerDetected = false;

try {
  if (document.referrer) {
    const referrerUrl =
      new URL(document.referrer);

    adminReferrerDetected =
      referrerUrl.pathname === "/admin" ||
      referrerUrl.pathname === "/admin/";
  }
} catch {}

const isAdminPage = (
  location.pathname === "/admin" ||
  location.pathname === "/admin/" ||
  new URLSearchParams(location.search).get("admin") === "1" ||
  adminReferrerDetected
);

const params = new URLSearchParams(location.search);
const room = params.get("room") || "main";

/*
  管理員頁防呆：若外層有明確 admin=1，可保留於後續 fallback / reconnect。
*/
if (
  isAdminPage &&
  params.get("admin") !== "1" &&
  location.pathname !== "/admin" &&
  location.pathname !== "/admin/"
) {
  try {
    window.history.replaceState(
      null,
      "",
      location.pathname +
      location.search +
      (
        location.search
          ? "&admin=1"
          : "?admin=1"
      ) +
      location.hash
    );
  } catch {}
}

/* =====================================================
   ㉝ 刷新自動回群：直接從 iframe URL fragment 恢復
   -----------------------------------------------------
   hd888.pages.dev 會把已保存的 visitorId / 暱稱 / joinGrant
   放在 iframe 的 #fragment 中。
   fragment 不會送到伺服器，所以可以避開 Safari iframe
   Storage / referrer / postMessage 時序問題。
===================================================== */

function readFirstPartyResumeState() {
  if (isAdminPage) {
    return {
      visitorId: "",
      name: "",
      grant: ""
    };
  }

  try {
    const hash =
      String(
        location.hash || ""
      ).replace(/^#/, "");

    if (!hash) {
      return {
        visitorId: "",
        name: "",
        grant: ""
      };
    }

    const state =
      new URLSearchParams(hash);

    return {
      visitorId:
        String(
          state.get(
            "hd888Visitor"
          ) || ""
        ).slice(0, 100),

      name:
        String(
          state.get(
            "hd888Name"
          ) || ""
        )
          .trim()
          .slice(0, 20),

      grant:
        String(
          state.get(
            "hd888Grant"
          ) || ""
        )
          .trim()
          .slice(0, 4096)
    };

  } catch {
    return {
      visitorId: "",
      name: "",
      grant: ""
    };
  }
}

const firstPartyResumeState =
  readFirstPartyResumeState();

