function selectAdminPersona(
  persona
) {
  const value =
    persona === "xinyao"
      ? "xinyao"
      : "nezha";

  selectedAdminPersona =
    value;

  document
    .querySelectorAll(
      ".admin-persona-choice"
    )
    .forEach(
      function(button) {
        button.classList.toggle(
          "selected",
          button.dataset.persona ===
            value
        );
      }
    );

  const selected =
    document.getElementById(
      "adminPersonaSelected"
    );

  if (selected) {
    selected.textContent =
      "將顯示為：" +
      adminPersonaDisplayName(
        value
      );
  }

  const fixedName =
    document.getElementById(
      "adminFixedNicknameValue"
    );

  if (fixedName) {
    fixedName.textContent =
      adminPersonaDisplayName(
        value
      );
  }

  try {
    sessionStorage.setItem(
      "nezhaSelectedAdminPersona",
      value
    );
  } catch {}
}

function restoreAdminPersonaChoice() {
  let saved = "";

  try {
    saved =
      sessionStorage.getItem(
        "nezhaSelectedAdminPersona"
      ) || "";
  } catch {}

  if (
    saved === "nezha" ||
    saved === "xinyao"
  ) {
    selectAdminPersona(
      saved
    );
  }
}

