/* =====================================================
   安全 Storage 包裝
   Pages iframe / 隱私模式若禁止 Storage，也不能讓整個聊天室 JS 中斷。
===================================================== */
function safeLocalGet(key) {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeLocalSet(key, value) {
  try {
    window.localStorage.setItem(key, String(value));
    return true;
  } catch {
    return false;
  }
}

function safeLocalRemove(key) {
  try {
    window.localStorage.removeItem(key);
  } catch {}
}

function safeSessionGet(key) {
  try {
    return window.sessionStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeSessionSet(key, value) {
  try {
    window.sessionStorage.setItem(key, String(value));
    return true;
  } catch {
    return false;
  }
}

function safeSessionRemove(key) {
  try {
    window.sessionStorage.removeItem(key);
  } catch {}
}

/* =====================================================
   管理員登入 Token 讀取
   -----------------------------------------------------
   之前管理員頁會呼叫 getAdminToken()，
   但這個函式實際上沒有宣告，造成 CLIENT_JS 在這裡直接中斷。
   後面的 Enter 送出、WebSocket 初始化、訊息顯示等程式都不會繼續執行。
===================================================== */
function getAdminToken() {
  return (
    safeSessionGet(
      "hd888AdminToken"
    ) || ""
  );
}

/* =====================================================
   ㊵ 客戶端自動更新
   -----------------------------------------------------
   目的：
   - 管理員部署新版後，客人不用自己按重新整理
   - WebSocket 重連時立即檢查
   - 回到聊天室 / 視窗重新取得焦點時檢查
   - 前景每 5 分鐘低頻備援檢查
   - 有未送出的文字會先暫存，刷新後自動還原
   - 正在選圖片 / 傳圖片時不強制刷新，避免圖片遺失
===================================================== */

let hd888VersionCheckBusy =
  false;

let hd888ReloadingForUpdate =
  false;

let hd888DelayedUpdateTimer =
  null;

const HD888_UPDATE_CHECK_INTERVAL =
  5 * 60 * 1000;

function hd888UpdateDraftKey() {
  return (
    "hd888UpdateDraft:" +
    room
  );
}

function restoreHd888UpdateDraft() {
  const draft =
    safeSessionGet(
      hd888UpdateDraftKey()
    );

  if (
    !draft ||
    !messageInput ||
    messageInput.value
  ) {
    return;
  }

  messageInput.value =
    draft;

  safeSessionRemove(
    hd888UpdateDraftKey()
  );

  try {
    messageInput.dispatchEvent(
      new Event(
        "input",
        {
          bubbles: true
        }
      )
    );
  } catch {}
}

function scheduleDelayedHd888UpdateCheck(
  delay = 30000
) {
  clearTimeout(
    hd888DelayedUpdateTimer
  );

  hd888DelayedUpdateTimer =
    setTimeout(
      function() {
        checkForHd888AppUpdate(
          "delayed"
        );
      },
      delay
    );
}

async function checkForHd888AppUpdate(
  reason = ""
) {
  if (
    hd888VersionCheckBusy ||
    hd888ReloadingForUpdate ||
    document.hidden
  ) {
    return false;
  }

  if (
    typeof HD888_LOADED_BUILD !==
      "string" ||
    !HD888_LOADED_BUILD
  ) {
    return false;
  }

  hd888VersionCheckBusy =
    true;

  try {
    const response =
      await fetch(
        "/api/version?_=" +
          Date.now(),
        {
          method: "GET",
          cache: "no-store",
          headers: {
            "Cache-Control":
              "no-cache"
          }
        }
      );

    if (!response.ok) {
      return false;
    }

    const data =
      await response.json();

    const serverBuild =
      String(
        data.build || ""
      );

    if (
      !serverBuild ||
      serverBuild ===
        HD888_LOADED_BUILD
    ) {
      return false;
    }

    /*
      圖片檔無法安全跨刷新保留。
      如果會員正在選圖 / 傳圖，延後自動更新。
    */
    if (
      imageSending ||
      (
        Array.isArray(
          pendingImageItems
        ) &&
        pendingImageItems.length > 0
      )
    ) {
      scheduleDelayedHd888UpdateCheck(
        30000
      );

      return true;
    }

    /*
      文字草稿可以先存 sessionStorage，
      新版重新載入後再自動放回輸入框。
    */
    const draft =
      String(
        messageInput?.value ||
        ""
      );

    if (draft) {
      safeSessionSet(
        hd888UpdateDraftKey(),
        draft
      );
    }

    hd888ReloadingForUpdate =
      true;

    /*
      避免剛好在觸控 / click handler 中立刻 reload。
    */
    setTimeout(
      function() {
        location.reload();
      },
      250
    );

    return true;

  } catch {
    return false;

  } finally {
    hd888VersionCheckBusy =
      false;
  }
}

function startHd888AutoUpdateWatch() {
  /*
    頁面載入後先還原「更新前未送出的文字」。
  */
  restoreHd888UpdateDraft();

  /*
    客人切回 Safari / PWA 時立刻確認。
  */
  document.addEventListener(
    "visibilitychange",
    function() {
      if (!document.hidden) {
        checkForHd888AppUpdate(
          "visible"
        );
      }
    }
  );

  window.addEventListener(
    "focus",
    function() {
      checkForHd888AppUpdate(
        "focus"
      );
    }
  );

  /*
    低頻備援。
    只在畫面可見時才會真的發 request，
    不在背景一直輪詢。
  */
  setInterval(
    function() {
      if (!document.hidden) {
        checkForHd888AppUpdate(
          "interval"
        );
      }
    },
    HD888_UPDATE_CHECK_INTERVAL
  );
}

startHd888AutoUpdateWatch();

/* =====================================================
   ㊻ 加入前「加到手機桌面」
   -----------------------------------------------------
   真正安裝動作由 hd888.pages.dev 外層頁面處理。
   - Android/Chrome：有 beforeinstallprompt 就直接叫系統安裝
   - iPhone/Safari：顯示「分享 → 加入主畫面」教學
   - 已從桌面模式開啟：按鈕顯示已加入
===================================================== */

let hd888InstallGuideOverlay =
  null;

function ensureHd888InstallGuide() {
  if (hd888InstallGuideOverlay) {
    return;
  }

  hd888InstallGuideOverlay =
    document.createElement(
      "div"
    );

  hd888InstallGuideOverlay.className =
    "install-guide-overlay";

  hd888InstallGuideOverlay.innerHTML =
    '<div class="install-guide-card">' +
      '<div class="install-guide-head">' +
        '<div class="install-guide-title" id="installGuideTitle">📲 加到手機桌面</div>' +
        '<button class="install-guide-close" type="button" aria-label="關閉">×</button>' +
      '</div>' +
      '<div class="install-guide-text" id="installGuideText"></div>' +
    '</div>';

  document.body.appendChild(
    hd888InstallGuideOverlay
  );

  hd888InstallGuideOverlay
    .querySelector(
      ".install-guide-close"
    )
    .addEventListener(
      "click",
      closeHd888InstallGuide
    );

  hd888InstallGuideOverlay.addEventListener(
    "click",
    function(event) {
      if (
        event.target ===
        hd888InstallGuideOverlay
      ) {
        closeHd888InstallGuide();
      }
    }
  );
}

function closeHd888InstallGuide() {
  hd888InstallGuideOverlay
    ?.classList.remove(
      "show"
    );
}

function getHd888InstallBrowserContext() {
  const ua =
    navigator.userAgent || "";

  const isiOS =
    /iPad|iPhone|iPod/i
      .test(ua);

  const isAndroid =
    /Android/i
      .test(ua);

  const isLine =
    /Line\//i
      .test(ua);

  const isFacebook =
    /FBAN|FBAV|FB_IAB/i
      .test(ua);

  const isInstagram =
    /Instagram/i
      .test(ua);

  const isMessenger =
    /MessengerForiOS|FB_IAB/i
      .test(ua);

  const isWeChat =
    /MicroMessenger/i
      .test(ua);

  const isTikTok =
    /TikTok|musical_ly|BytedanceWebview/i
      .test(ua);

  const isGoogleApp =
    /GSA\//i
      .test(ua);

  const isAndroidWebView =
    isAndroid &&
    (
      /;\s*wv\)/i.test(ua) ||
      /\bwv\b/i.test(ua) ||
      (
        /Version\/4\.0/i.test(ua) &&
        /Chrome\//i.test(ua)
      )
    );

  const isInApp =
    isLine ||
    isFacebook ||
    isInstagram ||
    isMessenger ||
    isWeChat ||
    isTikTok ||
    isGoogleApp ||
    isAndroidWebView;

  const isChromeAndroid =
    isAndroid &&
    /Chrome\//i.test(ua) &&
    !/EdgA|OPR|SamsungBrowser/i
      .test(ua) &&
    !isAndroidWebView;

  const isSafariIOS =
    isiOS &&
    /Safari/i.test(ua) &&
    !/CriOS|FxiOS|EdgiOS|OPiOS/i
      .test(ua) &&
    !isInApp;

  return {
    ua,
    isiOS,
    isAndroid,
    isInApp,
    isChromeAndroid,
    isSafariIOS
  };
}

