function requestHd888Install() {
  if (isAdminPage) {
    return;
  }

  /*
    如果 iframe 本身能判斷已經是 standalone，
    直接標示完成。
  */
  if (
    window.matchMedia &&
    window.matchMedia(
      "(display-mode: standalone)"
    ).matches
  ) {
    setHd888InstallButtonInstalled();
    return;
  }

  const browser =
    getHd888InstallBrowserContext();

  /*
    LINE / IG / FB / Google App / Android WebView 等
    內建瀏覽器無法可靠觸發 PWA 安裝。
    先明確請客人改用 Safari / Chrome。
  */
  if (browser.isInApp) {
    showHd888InstallGuide(
      browser.isiOS
        ? "ios-inapp"
        : "android-inapp"
    );

    return;
  }

  try {
    if (
      window.parent !== window
    ) {
      window.parent.postMessage(
        {
          type:
            "hd888-install-request"
        },
        HD888_PARENT_ORIGIN
      );

      return;
    }
  } catch {}

  /*
    若直接開 workers.dev，沒有 Pages 父頁可處理，
    就顯示手動教學。
  */
  showHd888InstallGuide(
    browser.isiOS
      ? "ios"
      : "android"
  );
}

window.addEventListener(
  "message",
  function(event) {
    if (
      event.source !==
        window.parent ||
      event.origin !==
        HD888_PARENT_ORIGIN
    ) {
      return;
    }

    const data =
      event.data || {};

    if (
      data.type !==
        "hd888-install-result"
    ) {
      return;
    }

    if (
      data.status ===
        "installed"
    ) {
      setHd888InstallButtonInstalled();
      return;
    }

    if (
      data.status ===
        "ios-inapp"
    ) {
      showHd888InstallGuide(
        "ios-inapp"
      );
      return;
    }

    if (
      data.status ===
        "android-inapp"
    ) {
      showHd888InstallGuide(
        "android-inapp"
      );
      return;
    }

    if (
      data.status ===
        "ios-guide"
    ) {
      showHd888InstallGuide(
        "ios"
      );
      return;
    }

    if (
      data.status ===
        "android-guide"
    ) {
      showHd888InstallGuide(
        "android"
      );
      return;
    }

    if (
      data.status ===
        "dismissed"
    ) {
      return;
    }

    showHd888InstallGuide(
      "manual"
    );
  }
);

