/* =====================================================
   ㉝ iPhone / Safari 第一方登入狀態橋接

   hd888.pages.dev 是使用者真正開啟的第一方頁面，
   workers.dev 則是在 iframe 裡。
   Safari 可能分割/清除 iframe localStorage，
   因此將訪客 ID、暱稱、joinGrant 鏡像保存到
   hd888.pages.dev 的第一方 localStorage。
===================================================== */

const HD888_PARENT_ORIGIN =
  "https://nezha-chat.pages.dev";

function canUseParentSessionBridge() {
  /*
    不再檢查 document.referrer。
    iPhone Safari / 加到主畫面後，iframe 的 referrer
    有機會是空字串，上一版因此完全沒有把 session
    寫回 hd888.pages.dev。

    這裡直接用指定 targetOrigin postMessage；
    如果父頁不是 hd888.pages.dev，瀏覽器本身就不會送達。
  */
  return (
    !isAdminPage &&
    window.parent !== window
  );
}

function sendParentSessionBridge(
  type,
  payload = {}
) {
  if (
    !canUseParentSessionBridge()
  ) {
    return;
  }

  try {
    window.parent.postMessage(
      {
        type,
        room,
        ...payload
      },
      HD888_PARENT_ORIGIN
    );
  } catch {}
}

function requestParentSessionBridge() {
  return new Promise(
    function(resolve) {
      if (
        !canUseParentSessionBridge()
      ) {
        resolve(null);
        return;
      }

      const requestId =
        "hd888-" +
        Date.now().toString(36) +
        "-" +
        Math.random()
          .toString(36)
          .slice(2);

      let finished =
        false;

      let timer =
        null;

      function finish(value) {
        if (finished) {
          return;
        }

        finished =
          true;

        window.removeEventListener(
          "message",
          onMessage
        );

        if (timer) {
          clearTimeout(timer);
        }

        resolve(
          value || null
        );
      }

      function onMessage(event) {
        if (
          event.source !==
            window.parent ||
          event.origin !==
            HD888_PARENT_ORIGIN
        ) {
          return;
        }

        const data =
          event.data || {};

        if (
          data.type !==
            "hd888-session-state" ||
          data.requestId !==
            requestId
        ) {
          return;
        }

        finish({
          visitorId:
            String(
              data.visitorId ||
              ""
            ).slice(0, 100),

          name:
            String(
              data.name ||
              ""
            )
              .trim()
              .slice(0, 20),

          grant:
            String(
              data.grant ||
              ""
            )
              .trim()
              .slice(0, 4096)
        });
      }

      window.addEventListener(
        "message",
        onMessage
      );

      timer =
        setTimeout(
          function() {
            finish(null);
          },
          500
        );

      try {
        window.parent.postMessage(
          {
            type:
              "hd888-session-get",
            requestId,
            room
          },
          HD888_PARENT_ORIGIN
        );
      } catch {
        finish(null);
      }
    }
  );
}

/* =====================================================
   ㉓ @標記通知音 / 震動
   - 一般訊息完全不提醒
   - @你、@全體可分開控制提示音
   - 震動可獨立開關
   - 預設「畫面正在前景時不吵」
   - 設定只存在這台裝置 / 這個聊天室
===================================================== */

function mentionNotifyStorageKey() {
  return (
    "hd888MentionNotify:" +
    room
  );
}

function loadMentionNotifyPrefs() {
  const raw =
    safeLocalGet(
      mentionNotifyStorageKey()
    );

  if (raw) {
    try {
      const saved =
        JSON.parse(raw);

      if (
        saved &&
        typeof saved ===
          "object"
      ) {
        if (
          typeof saved.mentionSound ===
            "boolean"
        ) {
          mentionNotifyPrefs.mentionSound =
            saved.mentionSound;
        }

        if (
          typeof saved.allSound ===
            "boolean"
        ) {
          mentionNotifyPrefs.allSound =
            saved.allSound;
        }

        if (
          typeof saved.vibration ===
            "boolean"
        ) {
          mentionNotifyPrefs.vibration =
            saved.vibration;
        }

        if (
          typeof saved.foreground ===
            "boolean"
        ) {
          mentionNotifyPrefs.foreground =
            saved.foreground;
        }
      }
    } catch {}
  }

  syncMentionNotifyUI();
}

function saveMentionNotifyPrefs() {
  safeLocalSet(
    mentionNotifyStorageKey(),
    JSON.stringify(
      mentionNotifyPrefs
    )
  );

  syncMentionNotifyUI();
}

function syncMentionNotifyUI() {
  if (mentionSoundToggle) {
    mentionSoundToggle.checked =
      !!mentionNotifyPrefs.mentionSound;
  }

  if (mentionAllSoundToggle) {
    mentionAllSoundToggle.checked =
      !!mentionNotifyPrefs.allSound;
  }

  const vibrationSupported =
    typeof navigator.vibrate ===
      "function";

  if (mentionVibrationRow) {
    mentionVibrationRow.style.display =
      vibrationSupported
        ? "flex"
        : "none";
  }

  if (mentionVibrationToggle) {
    mentionVibrationToggle.checked =
      vibrationSupported &&
      !!mentionNotifyPrefs.vibration;

    mentionVibrationToggle.disabled =
      !vibrationSupported;
  }

  if (mentionForegroundToggle) {
    mentionForegroundToggle.checked =
      !!mentionNotifyPrefs.foreground;
  }

  if (mentionVibrationSupport) {
    if (vibrationSupported) {
      mentionVibrationSupport.style.display =
        "block";

      mentionVibrationSupport.textContent =
        "此裝置支援震動";
    } else {
      mentionVibrationSupport.style.display =
        "none";

      mentionVibrationSupport.textContent =
        "";
    }
  }

  if (mentionNotifyButton) {
    const soundOn =
      !!mentionNotifyPrefs.mentionSound ||
      !!mentionNotifyPrefs.allSound;

    const vibrationOn =
      typeof navigator.vibrate ===
        "function" &&
      !!mentionNotifyPrefs.vibration;

    mentionNotifyButton.classList.toggle(
      "active",
      soundOn ||
      vibrationOn
    );

    mentionNotifyButton.title =
      soundOn ||
      vibrationOn
        ? "標記提醒設定（已開啟）"
        : "標記提醒設定（已關閉）";
  }
}

function updateMentionNotifyPref(
  key,
  checked
) {
  if (
    !Object.prototype.hasOwnProperty.call(
      mentionNotifyPrefs,
      key
    )
  ) {
    return;
  }

  mentionNotifyPrefs[key] =
    !!checked;

  saveMentionNotifyPrefs();

  if (
    (
      key === "mentionSound" ||
      key === "allSound"
    ) &&
    checked
  ) {
    unlockMentionAudio();
  }
}

function openMentionNotifySettings() {
  syncMentionNotifyUI();

  mentionNotifyOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "mention-notify-open"
  );

  unlockMentionAudio();
}

function closeMentionNotifySettings() {
  mentionNotifyOverlay.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "mention-notify-open"
  );
}

function mentionNotifyBackgroundClick(
  event
) {
  if (
    event.target ===
    mentionNotifyOverlay
  ) {
    closeMentionNotifySettings();
  }
}

function getMentionAudioContext() {
  const AudioContextClass =
    window.AudioContext ||
    window.webkitAudioContext;

  if (!AudioContextClass) {
    return null;
  }

  if (!mentionAudioContext) {
    try {
      mentionAudioContext =
        new AudioContextClass();
    } catch {
      mentionAudioContext =
        null;
    }
  }

  return mentionAudioContext;
}

function unlockMentionAudio() {
  if (
    !mentionNotifyPrefs.mentionSound &&
    !mentionNotifyPrefs.allSound
  ) {
    return;
  }

  const context =
    getMentionAudioContext();

  if (
    context &&
    context.state ===
      "suspended"
  ) {
    context.resume().catch(
      function() {}
    );
  }
}

function playMentionTone(
  kind
) {
  const context =
    getMentionAudioContext();

  if (!context) {
    return;
  }

  if (
    context.state ===
      "suspended"
  ) {
    context.resume().catch(
      function() {}
    );

    return;
  }

  const now =
    context.currentTime;

  const frequencies =
    kind === "all"
      ? [660, 820, 660]
      : [760, 980];

  frequencies.forEach(
    function(frequency, index) {
      const oscillator =
        context.createOscillator();

      const gain =
        context.createGain();

      const start =
        now +
        index * 0.105;

      const stop =
        start + 0.085;

      oscillator.type =
        "sine";

      oscillator.frequency.setValueAtTime(
        frequency,
        start
      );

      gain.gain.setValueAtTime(
        0.0001,
        start
      );

      gain.gain.exponentialRampToValueAtTime(
        0.12,
        start + 0.012
      );

      gain.gain.exponentialRampToValueAtTime(
        0.0001,
        stop
      );

      oscillator.connect(gain);
      gain.connect(
        context.destination
      );

      oscillator.start(start);
      oscillator.stop(
        stop + 0.01
      );
    }
  );
}

function vibrateMention(
  kind
) {
  if (
    !mentionNotifyPrefs.vibration ||
    typeof navigator.vibrate !==
      "function"
  ) {
    return;
  }

  try {
    navigator.vibrate(
      kind === "all"
        ? [110, 55, 110]
        : [80, 45, 80]
    );
  } catch {}
}

function shouldNotifyMentionNow() {
  if (
    mentionNotifyPrefs.foreground
  ) {
    return true;
  }

  return (
    document.visibilityState !==
    "visible"
  );
}

function handleLiveMentionNotification(
  data
) {
  if (
    !data ||
    data.type !== "message" ||
    mentionHistoryLoading
  ) {
    return;
  }

  const myName =
    normalizeMentionName(
      currentChatName
    );

  const senderName =
    normalizeMentionName(
      data.name
    );

  if (
    !myName ||
    (
      senderName &&
      senderName === myName
    )
  ) {
    return;
  }

  const isAll =
    !!data.mentionAll;

  const isMine =
    !isAll &&
    doesMessageMentionMe(
      data.text || ""
    );

  if (
    !isAll &&
    !isMine
  ) {
    return;
  }

  if (
    !shouldNotifyMentionNow()
  ) {
    return;
  }

  if (
    isAll
      ? mentionNotifyPrefs.allSound
      : mentionNotifyPrefs.mentionSound
  ) {
    playMentionTone(
      isAll
        ? "all"
        : "me"
    );
  }

  vibrateMention(
    isAll
      ? "all"
      : "me"
  );
}

/*
  Safari / Chrome 的提示音需要至少一次使用者操作才能解鎖。
  只要成員在聊天室點過一次，後續 @提醒就能播放。
*/
document.addEventListener(
  "pointerdown",
  unlockMentionAudio,
  {
    passive: true
  }
);

document.addEventListener(
  "keydown",
  unlockMentionAudio
);

loadMentionNotifyPrefs();

/* =====================================================
   ⑨ 客戶端保留暱稱提示
   最終權限仍由 Worker 伺服器判定。
===================================================== */

function normalizeProtectedNicknameClient(name) {
  return String(name || "")
    .normalize("NFKC")
    .replace(/[\u200B-\u200D\u2060\uFEFF\u00AD]/g, "")
    .trim()
    .toUpperCase()
    .replace(/[\s._\-－—–~～·•:：|｜/\\\[\]【】()（）{}「」『』"'\x60]+/g, "");
}

function isReservedNicknameClient(name) {
  const normalized =
    normalizeProtectedNicknameClient(
      name
    );

  if (!normalized) return false;

  const chineseProtected = [
    "管理員",
    "管理员",
    "官方",
    "客服",
    "系統",
    "系统",
    "哪吒",
    "哪吒👺",
    "芯瑤",
    "芯瑶",
    "芯瑤💕",
    "皇鼎娱乐城",
    "版主",
    "小幫手",
    "小帮手",
    "皇鼎客服",
    "皇鼎官方"
  ];

  if (
    chineseProtected.some(
      function(word) {
        return normalized.includes(word);
      }
    )
  ) {
    return true;
  }

  if (
    normalized.includes("皇鼎")
  ) {
    return true;
  }

  if (
    normalized.includes("HD888")
  ) {
    return true;
  }

  const latinProtected = [
    "ADMIN",
    "ADMINISTRATOR",
    "SUPPORT",
    "MODERATOR"
  ];

  return latinProtected.some(
    function(word) {
      return (
        normalized === word ||
        normalized.startsWith(word)
      );
    }
  );
}

function getOnlineRandomBucket() {
  return Math.floor(
    Date.now() / 30000
  );
}

function getDeterministicOnlineOffset(
  base,
  range
) {
  const cleanRange =
    Math.max(
      0,
      Math.floor(
        Number(range) || 0
      )
    );

  if (!cleanRange) {
    return 0;
  }

  const bucket =
    getOnlineRandomBucket();

  const seedText =
    String(room || "main") +
    "|" +
    String(bucket) +
    "|" +
    String(base) +
    "|" +
    String(cleanRange);

  let hash =
    2166136261;

  for (
    let i = 0;
    i < seedText.length;
    i++
  ) {
    hash ^=
      seedText.charCodeAt(i);

    hash =
      Math.imul(
        hash,
        16777619
      );
  }

  const span =
    cleanRange * 2 + 1;

  return (
    (hash >>> 0) % span
  ) - cleanRange;
}

function getClientDisplayOnlineCount(
  actualCount = latestActualOnlineCount
) {
  const actual =
    Number(actualCount);

  const base =
    (
      customOnlineDisplayCount !== null &&
      Number.isFinite(
        Number(customOnlineDisplayCount)
      )
    )
      ? Math.max(
          0,
          Math.floor(
            Number(customOnlineDisplayCount)
          )
        )
      : (
          Number.isFinite(actual)
            ? Math.max(
                0,
                Math.floor(actual)
              )
            : 0
        );

  if (!onlineRandomEnabled) {
    return base;
  }

  return Math.max(
    0,
    Math.min(
      99999,
      base +
      getDeterministicOnlineOffset(
        base,
        onlineRandomRange
      )
    )
  );
}

function restartOnlineRandomRefreshTimer() {
  if (onlineRandomRefreshTimer) {
    clearInterval(
      onlineRandomRefreshTimer
    );

    onlineRandomRefreshTimer = null;
  }

  if (!onlineRandomEnabled) {
    return;
  }

  /*
    實際顯示值每 30 秒換一個；
    這裡每 5 秒檢查一次只是為了跨過時間分段時立即刷新，
    不會做高頻動畫，也不會增加明顯耗電。
  */
  onlineRandomRefreshTimer =
    setInterval(
      function() {
        if (
          document.visibilityState ===
            "visible"
        ) {
          refreshClientOnlineCountText();
        }
      },
      5000
    );
}

function setOnlineRandomState(
  enabled,
  range = onlineRandomRange
) {
  onlineRandomEnabled =
    enabled === true;

  const number =
    Number(range);

  onlineRandomRange =
    Number.isFinite(number)
      ? Math.max(
          0,
          Math.min(
            1000,
            Math.floor(number)
          )
        )
      : 5;

  if (onlineRandomToggleButton) {
    onlineRandomToggleButton.textContent =
      onlineRandomEnabled
        ? "🎲 自動浮動：開啟中"
        : "🎲 自動浮動：已關閉";

    onlineRandomToggleButton.classList.toggle(
      "is-hidden",
      !onlineRandomEnabled
    );

    onlineRandomToggleButton.setAttribute(
      "aria-pressed",
      onlineRandomEnabled
        ? "true"
        : "false"
    );
  }

  if (onlineRandomRangeInput) {
    onlineRandomRangeInput.value =
      String(onlineRandomRange);
  }

  if (onlineRandomHint) {
    onlineRandomHint.textContent =
      onlineRandomEnabled
        ? "每 30 秒自動於基準值上下 ±" +
          onlineRandomRange +
          " 人浮動"
        : "目前不自動浮動";
  }

  restartOnlineRandomRefreshTimer();
  setCustomOnlineDisplayCountState(
    customOnlineDisplayCount
  );
  refreshClientOnlineCountText();
}

function refreshClientOnlineCountText() {
  if (
    !onlineBox ||
    currentConnectionMode === "reconnecting" ||
    currentConnectionMode === "offline"
  ) {
    return;
  }

  onlineBox.textContent =
    "在線 " +
    getClientDisplayOnlineCount() +
    " 人";
}

function setCustomOnlineDisplayCountState(
  value
) {
  const number =
    Number(value);

  customOnlineDisplayCount =
    (
      value === null ||
      value === undefined ||
      value === "" ||
      !Number.isFinite(number)
    )
      ? null
      : Math.max(
          0,
          Math.min(
            99999,
            Math.floor(number)
          )
        );

  if (onlineDisplayCountInput) {
    onlineDisplayCountInput.value =
      customOnlineDisplayCount === null
        ? ""
        : String(
            customOnlineDisplayCount
          );
  }

  if (onlineDisplayCountHint) {
    onlineDisplayCountHint.textContent =
      customOnlineDisplayCount === null
        ? (
            onlineRandomEnabled
              ? "以真實在線人數為基準自動浮動"
              : "目前跟隨真實在線人數"
          )
        : (
            onlineRandomEnabled
              ? "以 " +
                customOnlineDisplayCount +
                " 人為基準自動浮動"
              : "客戶端固定顯示 " +
                customOnlineDisplayCount +
                " 人"
          );
  }

  if (onlineDisplayCountResetButton) {
    onlineDisplayCountResetButton.disabled =
      customOnlineDisplayCount === null;
  }

  refreshClientOnlineCountText();
}

async function saveOnlineRandomSettings(
  nextEnabled = onlineRandomEnabled
) {
  if (!isAdminLoggedIn()) {
    alert("請先登入管理員");
    return;
  }

  const range =
    Number(
      onlineRandomRangeInput?.value ??
      onlineRandomRange
    );

  if (
    !Number.isFinite(range) ||
    range < 0 ||
    range > 1000
  ) {
    alert("浮動範圍請輸入 0～1000");
    onlineRandomRangeInput?.focus();
    return;
  }

  if (onlineRandomToggleButton) {
    onlineRandomToggleButton.disabled =
      true;
  }

  if (onlineRandomRangeSaveButton) {
    onlineRandomRangeSaveButton.disabled =
      true;
  }

  try {
    const response =
      await fetch(
        "/api/admin/online-random",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              enabled:
                nextEnabled === true,
              range:
                Math.floor(range)
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "在線人數浮動設定失敗"
      );
    }

    setOnlineRandomState(
      data.onlineRandomEnabled === true,
      data.onlineRandomRange
    );

    setAdminRoomStats(
      data.onlineCount,
      data.groupMemberCount
    );

  } catch (error) {
    alert(
      error?.message ||
      "在線人數浮動設定失敗"
    );
  } finally {
    if (onlineRandomToggleButton) {
      onlineRandomToggleButton.disabled =
        false;
    }

    if (onlineRandomRangeSaveButton) {
      onlineRandomRangeSaveButton.disabled =
        false;
    }
  }
}

async function toggleOnlineRandom() {
  await saveOnlineRandomSettings(
    !onlineRandomEnabled
  );
}

async function saveOnlineRandomRange() {
  await saveOnlineRandomSettings(
    onlineRandomEnabled
  );
}

