function setAdminRoomStats(
  onlineCount,
  groupMemberCount
) {
  const online =
    Number(onlineCount);

  const group =
    Number(groupMemberCount);

  if (Number.isFinite(online)) {
    adminOnlineCount =
      Math.max(0, Math.floor(online));
  }

  if (Number.isFinite(group)) {
    adminGroupMemberCount =
      Math.max(0, Math.floor(group));
  }

  if (adminOnlineCountValue) {
    adminOnlineCountValue.textContent =
      String(adminOnlineCount);
  }

  if (adminGroupMemberCountValue) {
    adminGroupMemberCountValue.textContent =
      String(adminGroupMemberCount);
  }
}

