/* =====================================================
   ⑳ 新成員專屬歡迎卡
   只顯示在成員自己的畫面，不寫入聊天室。
===================================================== */

function makeWelcomeVersion(value) {
  const input =
    String(value || "");

  let hash =
    2166136261;

  for (
    let i = 0;
    i < input.length;
    i++
  ) {
    hash ^= input.charCodeAt(i);

    hash = Math.imul(
      hash,
      16777619
    );
  }

  return (
    input.length.toString(36) +
    "-" +
    (hash >>> 0).toString(36)
  );
}

function welcomeAckStorageKey() {
  return (
    "hd888WelcomeAck:" +
    room
  );
}

function maybeShowWelcomeCard() {
  if (
    isAdminPage ||
    !currentChatName ||
    !welcomeText ||
    !welcomeCard
  ) {
    return;
  }

  const chatBox =
    document.getElementById(
      "chat"
    );

  if (
    !chatBox ||
    chatBox.style.display ===
      "none"
  ) {
    return;
  }

  const version =
    makeWelcomeVersion(
      welcomeText
    );

  welcomeCardVersion =
    version;

  const acknowledged =
    safeLocalGet(
      welcomeAckStorageKey()
    );

  if (
    acknowledged === version
  ) {
    return;
  }

  welcomeCardText.textContent =
    welcomeText;

  welcomeCard.classList.add(
    "show"
  );

  document.body.classList.add(
    "welcome-open"
  );
}

function acknowledgeWelcomeCard() {
  if (welcomeCardVersion) {
    safeLocalSet(
      welcomeAckStorageKey(),
      welcomeCardVersion
    );
  }

  if (welcomeCard) {
    welcomeCard.classList.remove(
      "show"
    );
  }

  document.body.classList.remove(
    "welcome-open"
  );
}

function setWelcomeMessageState(text) {
  welcomeText =
    String(text || "")
      .trim()
      .slice(0, 1500);

  if (
    welcomeEditorText &&
    !welcomeEditor.classList.contains(
      "show"
    )
  ) {
    welcomeEditorText.value =
      welcomeText;
  }

  maybeShowWelcomeCard();
}

function openWelcomeEditor() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  welcomeEditorText.value =
    welcomeText;

  welcomeEditor.classList.add(
    "show"
  );

  document.body.classList.add(
    "welcome-open"
  );

  setTimeout(
    function() {
      welcomeEditorText.focus();
    },
    0
  );
}

function closeWelcomeEditor() {
  welcomeEditor.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "welcome-open"
  );
}

async function saveWelcomeEditor() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const cleaned =
    String(
      welcomeEditorText.value ||
      ""
    )
      .trim()
      .slice(0, 1500);

  if (!cleaned) {
    alert(
      "歡迎內容不能是空白"
    );
    return;
  }

  welcomeEditorSaveButton.disabled =
    true;

  welcomeEditorSaveButton.textContent =
    "儲存中…";

  try {
    const response =
      await fetch(
        "/api/admin/welcome-message",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            welcomeText:
              cleaned
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "歡迎內容儲存失敗"
      );
      return;
    }

    setWelcomeMessageState(
      data.welcomeText || ""
    );

    closeWelcomeEditor();

    alert(
      "新成員歡迎內容已更新 ✅"
    );

  } catch {
    alert(
      "歡迎內容儲存失敗，請稍後再試"
    );

  } finally {
    welcomeEditorSaveButton.disabled =
      false;

    welcomeEditorSaveButton.textContent =
      "儲存";
  }
}

async function resetWelcomeEditor() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  if (
    !confirm(
      "確定恢復預設歡迎內容嗎？"
    )
  ) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/welcome-message",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            reset: true
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "恢復預設失敗"
      );
      return;
    }

    setWelcomeMessageState(
      data.welcomeText || ""
    );

    welcomeEditorText.value =
      data.welcomeText || "";

    alert(
      "已恢復預設歡迎內容 ✅"
    );

  } catch {
    alert(
      "恢復預設失敗，請稍後再試"
    );
  }
}

/* =====================================================
   ⑦ 置頂公告顯示
===================================================== */

function readAnnouncementCollapsedState() {
  try {
    const saved =
      localStorage.getItem(
        ANNOUNCEMENT_COLLAPSE_STORAGE_KEY
      );

    /*
      預設收合，避免公告長期霸佔聊天畫面。
      使用者手動展開後會記住目前狀態。
    */
    return saved === null
      ? true
      : saved !== "0";
  } catch {
    return true;
  }
}

function applyAnnouncementCollapsedState() {
  if (!announcementBanner) {
    return;
  }

  announcementBanner.classList.toggle(
    "collapsed",
    !!announcementCollapsed
  );

  const toggleButton =
    document.getElementById(
      "announcementToggleButton"
    );

  const toggleLabel =
    document.getElementById(
      "announcementToggleLabel"
    );

  const toggleIcon =
    document.getElementById(
      "announcementToggleIcon"
    );

  if (toggleButton) {
    toggleButton.setAttribute(
      "aria-expanded",
      announcementCollapsed
        ? "false"
        : "true"
    );
  }

  if (toggleLabel) {
    toggleLabel.textContent =
      announcementCollapsed
        ? "展開"
        : "收合";
  }

  if (toggleIcon) {
    toggleIcon.textContent =
      announcementCollapsed
        ? "⌄"
        : "⌃";
  }
}

function toggleAnnouncementCollapsed() {
  announcementCollapsed =
    !announcementCollapsed;

  try {
    localStorage.setItem(
      ANNOUNCEMENT_COLLAPSE_STORAGE_KEY,
      announcementCollapsed
        ? "1"
        : "0"
    );
  } catch {}

  applyAnnouncementCollapsedState();
}

function updateTopPinnedAnnouncementBar() {
  if (!announcementBanner) {
    return;
  }

  const hasAnnouncement =
    !!String(
      announcementText || ""
    ).trim();

  const hasPinned =
    Array.isArray(
      pinnedMessages
    ) &&
    pinnedMessages.length > 0;

  announcementBanner.classList.toggle(
    "show",
    hasAnnouncement || hasPinned
  );

  announcementBanner.classList.toggle(
    "no-announcement",
    !hasAnnouncement
  );

  if (announcementTitleBox) {
    announcementTitleBox.textContent =
      hasAnnouncement
        ? "📌 置頂公告"
        : "📌 置頂訊息";
  }

  const toggleButton =
    document.getElementById(
      "announcementToggleButton"
    );

  if (toggleButton) {
    toggleButton.style.display =
      hasAnnouncement
        ? "inline-flex"
        : "none";
  }

  if (pinnedMessagesBanner) {
    pinnedMessagesBanner.classList.toggle(
      "show",
      hasPinned
    );
  }
}

function setAnnouncementState(text) {
  announcementText = String(text || "").trim().slice(0, 500);

  if (!announcementBanner || !announcementTextBox) {
    return;
  }

  announcementTextBox.textContent = announcementText;

  updateTopPinnedAnnouncementBar();

  if (announcementText) {
    announcementCollapsed =
      readAnnouncementCollapsedState();

    applyAnnouncementCollapsedState();
  }
}

/* =====================================================
   即時房間狀態同步
   WebSocket 廣播正常時會立即更新；
   每 3 秒再主動同步一次作為保險，不需要重新整理頁面。
===================================================== */

/* =====================================================
   ㉕ 多則置頂訊息
===================================================== */

function normalizePinnedClient(
  value
) {
  const source =
    Array.isArray(value)
      ? value
      : [];

  const seen =
    new Set();

  const result =
    [];

  for (const item of source) {
    if (
      !item ||
      typeof item !== "object"
    ) {
      continue;
    }

    const messageId =
      String(
        item.messageId || ""
      );

    if (
      !messageId ||
      seen.has(messageId)
    ) {
      continue;
    }

    seen.add(messageId);

    result.push({
      messageId,

      kind:
        item.kind === "image"
          ? "image"
          : "message",

      senderName:
        String(
          item.senderName ||
          "匿名"
        ).slice(0, 20),

      preview:
        String(
          item.preview ||
          (
            item.kind === "image"
              ? "📷 圖片"
              : "訊息"
          )
        ).slice(0, 250),

      messageTime:
        Number(
          item.messageTime || 0
        ),

      pinnedAt:
        Number(
          item.pinnedAt || 0
        )
    });

    if (result.length >= 5) {
      break;
    }
  }

  return result;
}

function isMessagePinned(
  messageId
) {
  const id =
    String(messageId || "");

  return pinnedMessages.some(
    item =>
      item.messageId === id
  );
}

function updatePinnedMessageButtons() {
  document
    .querySelectorAll(
      ".pin-message-btn[data-message-id]"
    )
    .forEach(
      function(button) {
        const id =
          button.dataset.messageId ||
          "";

        const pinned =
          isMessagePinned(id);

        button.textContent =
          pinned
            ? "📌 取消置頂"
            : "📌 置頂";

        button.classList.toggle(
          "active",
          pinned
        );
      }
    );
}

function updatePinnedMessagesState(
  value
) {
  pinnedMessages =
    normalizePinnedClient(
      value
    );

  updateTopPinnedAnnouncementBar();

  if (pinnedMessagesCount) {
    pinnedMessagesCount.textContent =
      String(
        pinnedMessages.length
      );
  }

  updatePinnedMessageButtons();

  if (
    pinnedMessagesOverlay &&
    pinnedMessagesOverlay.classList.contains(
      "show"
    )
  ) {
    renderPinnedMessages();
  }
}

function formatPinnedMessageTime(
  time
) {
  const date =
    new Date(
      Number(time || 0)
    );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return "";
  }

  return date.toLocaleString(
    "zh-TW",
    {
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }
  );
}

function renderPinnedMessages() {
  if (!pinnedMessagesList) {
    return;
  }

  pinnedMessagesList.innerHTML =
    "";

  if (!pinnedMessages.length) {
    const empty =
      document.createElement(
        "div"
      );

    empty.className =
      "pinned-messages-empty";

    empty.textContent =
      "目前沒有置頂訊息";

    pinnedMessagesList.appendChild(
      empty
    );

    return;
  }

  pinnedMessages.forEach(
    function(item, index) {
      const card =
        document.createElement(
          "div"
        );

      card.className =
        "pinned-message-item";

      const jump =
        document.createElement(
          "button"
        );

      jump.type =
        "button";

      jump.className =
        "pinned-message-jump";

      jump.onclick =
        function() {
          jumpToPinnedMessage(
            item.messageId
          );
        };

      const top =
        document.createElement(
          "div"
        );

      top.className =
        "pinned-message-item-top";

      const indexLabel =
        document.createElement(
          "span"
        );

      indexLabel.className =
        "pinned-message-index";

      indexLabel.textContent =
        "📌 " +
        String(index + 1);

      const sender =
        document.createElement(
          "span"
        );

      sender.className =
        "pinned-message-sender";

      sender.textContent =
        item.senderName ||
        "匿名";

      const time =
        document.createElement(
          "span"
        );

      time.className =
        "pinned-message-time";

      time.textContent =
        formatPinnedMessageTime(
          item.messageTime
        );

      top.appendChild(
        indexLabel
      );

      top.appendChild(
        sender
      );

      top.appendChild(
        time
      );

      const preview =
        document.createElement(
          "div"
        );

      preview.className =
        "pinned-message-preview";

      preview.textContent =
        item.kind === "image"
          ? "📷 圖片"
          : item.preview;

      jump.appendChild(top);
      jump.appendChild(preview);
      card.appendChild(jump);

      if (
        isAdminPage &&
        isAdminLoggedIn()
      ) {
        const unpin =
          document.createElement(
            "button"
          );

        unpin.type =
          "button";

        unpin.className =
          "pinned-message-unpin";

        unpin.textContent =
          "取消置頂";

        unpin.onclick =
          function(event) {
            event.stopPropagation();

            adminTogglePinMessage(
              item.messageId
            );
          };

        card.appendChild(
          unpin
        );
      }

      pinnedMessagesList.appendChild(
        card
      );
    }
  );
}

function openPinnedMessages() {
  if (
    !pinnedMessagesOverlay
  ) {
    return;
  }

  renderPinnedMessages();

  pinnedMessagesOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "pinned-open"
  );
}

function closePinnedMessages() {
  if (!pinnedMessagesOverlay) {
    return;
  }

  pinnedMessagesOverlay.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "pinned-open"
  );
}

function pinnedMessagesBackgroundClick(
  event
) {
  if (
    event.target ===
    pinnedMessagesOverlay
  ) {
    closePinnedMessages();
  }
}

function jumpToPinnedMessage(
  messageId
) {
  const id =
    String(messageId || "");

  if (!id) {
    return;
  }

  closePinnedMessages();

  if (
    searchPanel &&
    searchPanel.classList.contains(
      "show"
    )
  ) {
    closeMessageSearchPanel();
  } else if (
    messageSearchQuery
  ) {
    clearMessageSearch();
  }

  const box =
    findMessageBoxById(id);

  if (!box) {
    alert(
      "這則訊息可能已被刪除，請重新整理後再試"
    );
    return;
  }

  box.style.display =
    "";

  box.scrollIntoView({
    behavior: "smooth",
    block: "center"
  });

  box.classList.remove(
    "pinned-jump-flash"
  );

  void box.offsetWidth;

  box.classList.add(
    "pinned-jump-flash"
  );

  clearTimeout(
    pinnedJumpTimer
  );

  pinnedJumpTimer =
    setTimeout(
      function() {
        box.classList.remove(
          "pinned-jump-flash"
        );
      },
      2200
    );
}

async function adminTogglePinMessage(
  messageId
) {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const id =
    String(messageId || "");

  if (!id) {
    return;
  }

  const pinned =
    isMessagePinned(id);

  if (
    !pinned &&
    pinnedMessages.length >= 5
  ) {
    alert(
      "最多只能置頂 5 則訊息，請先取消一則置頂"
    );
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/pin-message",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            messageId: id,
            action:
              pinned
                ? "unpin"
                : "pin"
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "置頂設定失敗"
      );
      return;
    }

    updatePinnedMessagesState(
      data.pinnedMessages ||
      []
    );

  } catch {
    alert(
      "置頂設定失敗，請稍後再試"
    );
  }
}


/* =====================================================
   ㉞ 5 人組隊活動 UI
===================================================== */

function teamActivityPhaseLabel(
  phase
) {
  const labels = {
    off: "活動關閉",
    recruiting:
      "開放組隊",
    running:
      "活動進行中・滿員才鎖隊",
    ended:
      "活動已結束"
  };

  return labels[phase] ||
    "活動關閉";
}

function teamActivityRosterEditable(
  settings,
  team
) {
  const phase =
    String(settings?.phase || "off");

  if (phase === "recruiting") {
    return true;
  }

  const maxMembers =
    Math.max(
      2,
      Number(
        team?.maxMembers ||
        settings?.maxMembers ||
        5
      )
    );

  return (
    phase === "running" &&
    team?.locked !== true &&
    Number(
      team?.memberCount || 0
    ) < maxMembers
  );
}

function activityDateTimeLocalValue(
  timestamp
) {
  const value =
    Number(timestamp || 0);

  if (!value) {
    return "";
  }

  const date = new Date(value);
  const offset =
    date.getTimezoneOffset() *
    60000;

  return new Date(
    value - offset
  )
    .toISOString()
    .slice(0, 16);
}

function activityScheduleDisplay(
  timestamp
) {
  const value =
    Number(timestamp || 0);

  if (!value) {
    return "未設定";
  }

  return new Date(value)
    .toLocaleString(
      "zh-TW",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }
    );
}

function setTeamActivityRoomState(
  activity
) {
  const source =
    activity &&
    typeof activity === "object"
      ? activity
      : {};

  teamActivityPhase =
    [
      "off",
      "recruiting",
      "running",
      "ended"
    ].includes(source.phase)
      ? source.phase
      : "off";

  teamActivityTitle =
    String(
      source.title ||
      "⚔️ 組隊活動"
    )
      .trim()
      .slice(0, 50) ||
    "⚔️ 組隊活動";

  if (teamActivityButton) {
    teamActivityButton.style.display =
      !isAdminPage
        ? "inline-flex"
        : "none";

    teamActivityButton.title =
      teamActivityTitle;
  }

  if (teamActivityOverlayTitle) {
    teamActivityOverlayTitle.textContent =
      teamActivityTitle;
  }

  if (teamActivityPhaseBadge) {
    teamActivityPhaseBadge.textContent =
      teamActivityPhaseLabel(
        teamActivityPhase
      );

    teamActivityPhaseBadge.dataset.phase =
      teamActivityPhase;
  }

  if (
    teamActivityPhase === "off" &&
    teamActivityOverlay &&
    teamActivityOverlay.classList.contains(
      "show"
    )
  ) {
    closeTeamActivity();
  }
}

function formatActivityNumber(
  value
) {
  const number =
    Number(value || 0);

  return Number.isFinite(number)
    ? Math.floor(number)
        .toLocaleString(
          "en-US"
        )
    : "0";
}

function formatActivityTime(
  value
) {
  const date =
    new Date(
      Number(value || 0)
    );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return "";
  }

  return date.toLocaleString(
    "zh-TW",
    {
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }
  );
}

function activityEl(
  tag,
  className,
  textValue = ""
) {
  const element =
    document.createElement(tag);

  if (className) {
    element.className =
      className;
  }

  if (
    textValue !== undefined &&
    textValue !== null &&
    String(textValue)
  ) {
    element.textContent =
      String(textValue);
  }

  return element;
}

function activityButton(
  textValue,
  className,
  handler
) {
  const button =
    activityEl(
      "button",
      className,
      textValue
    );

  button.type = "button";
  button.onclick = handler;

  return button;
}

async function teamMemberApi(
  path,
  payload = {}
) {
  if (!currentJoinGrant) {
    throw new Error(
      "登入狀態已過期，請重新進入聊天室"
    );
  }

  const response =
    await fetch(
      path,
      {
        method: "POST",
        headers: {
          "Content-Type":
            "application/json"
        },
        body: JSON.stringify({
          room,
          visitorId,
          joinGrant:
            currentJoinGrant,
          activityId:
            teamActivitySelectedId,

          /*
            組隊系統直接帶目前聊天室本人暱稱，
            不再靠 Durable Object 裡掃 WebSocket 猜是誰。
          */
          nickname:
            String(
              currentChatName ||
              savedMemberName ||
              nickname?.value ||
              ""
            )
              .trim()
              .slice(0, 20),

          ...payload
        })
      }
    );

  let data;

  try {
    data = await response.json();
  } catch {
    data = {
      ok: false,
      message:
        "活動資料讀取失敗"
    };
  }

  if (
    !response.ok ||
    !data.ok
  ) {
    const error =
      new Error(
        data.message ||
        "活動操作失敗"
      );

    error.status =
      response.status;

    throw error;
  }

  return data;
}

async function loadTeamActivity(
  quiet = false
) {
  if (
    teamActivityLoading ||
    isAdminPage
  ) {
    return;
  }

  teamActivityLoading =
    true;

  if (
    teamActivityContent &&
    !quiet
  ) {
    teamActivityContent.innerHTML =
      '<div class="team-activity-empty">活動資料讀取中…</div>';
  }

  try {
    const data =
      await teamMemberApi(
        "/api/team/state"
      );

    teamActivityState =
      data.state || null;

    if (
      teamActivityState &&
      teamActivityState.settings
    ) {
      setTeamActivityRoomState(
        teamActivityState.settings
      );
    }

    renderTeamActivity();

  } catch (error) {
    if (teamActivityContent) {
      teamActivityContent.innerHTML =
        "";

      const box =
        activityEl(
          "div",
          "team-activity-empty",
          error.message ||
          "活動資料讀取失敗"
        );

      teamActivityContent.appendChild(
        box
      );
    }

  } finally {
    teamActivityLoading =
      false;
  }
}

async function loadTeamActivityRegistry() {
  if (
    isAdminPage ||
    !currentJoinGrant
  ) {
    return [];
  }

  try {
    const response =
      await fetch(
        "/api/team/activities",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body:
            JSON.stringify({
              room,
              visitorId,
              joinGrant:
                currentJoinGrant
            }),
          cache:
            "no-store"
        }
      );

    const data =
      await response.json();

    if (
      response.ok &&
      data.ok
    ) {
      teamActivityRegistry =
        Array.isArray(
          data.activities
        )
          ? data.activities
          : [];
    }
  } catch {}

  return teamActivityRegistry;
}

function activeTeamActivities() {
  return teamActivityRegistry
    .filter(
      item =>
        [
          "recruiting",
          "running"
        ].includes(
          item.phase
        )
    );
}

function renderTeamActivityPicker() {
  if (!teamActivityPickerList) {
    return;
  }

  teamActivityPickerList.innerHTML =
    "";

  const list =
    activeTeamActivities();

  if (!list.length) {
    teamActivityPickerList.appendChild(
      activityEl(
        "div",
        "team-activity-empty",
        "目前沒有開放中的組隊活動"
      )
    );
    return;
  }

  list.forEach(
    function(item) {
      const button =
        activityEl(
          "button",
          "team-activity-picker-card"
        );

      button.type =
        "button";

      button.appendChild(
        activityEl(
          "div",
          "team-activity-picker-type",
          item.typeLabel ||
          "組隊活動"
        )
      );

      button.appendChild(
        activityEl(
          "div",
          "team-activity-picker-title",
          item.title ||
          "⚔️ 組隊活動"
        )
      );

      button.appendChild(
        activityEl(
          "div",
          "team-activity-picker-phase",
          teamActivityPhaseLabel(
            item.phase
          )
        )
      );

      button.addEventListener(
        "click",
        function() {
          teamActivitySelectedId =
            item.id;

          teamActivityTitle =
            item.title ||
            "⚔️ 組隊活動";

          teamActivityPhase =
            item.phase;

          closeTeamActivityPicker();
          openSelectedTeamActivity();
        }
      );

      teamActivityPickerList.appendChild(
        button
      );
    }
  );
}

function closeTeamActivityPicker() {
  teamActivityPickerOverlay
    ?.classList.remove(
      "show"
    );
}

function teamActivityPickerBackgroundClick(event) {
  if (
    event.target ===
      teamActivityPickerOverlay
  ) {
    closeTeamActivityPicker();
  }
}

function openSelectedTeamActivity() {
  if (!teamActivityOverlay) {
    return;
  }

  closeTeamActivityForm();

  teamActivityOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "team-activity-open"
  );

  if (teamActivityOverlayTitle) {
    teamActivityOverlayTitle.textContent =
      teamActivityTitle;
  }

  loadTeamActivity();
}

async function openTeamActivity() {
  if (isAdminPage) {
    return;
  }

  await loadTeamActivityRegistry();

  const list =
    activeTeamActivities();

  if (!list.length) {
    alert(
      "目前沒有開放中的組隊活動"
    );
    return;
  }

  if (list.length === 1) {
    teamActivitySelectedId =
      list[0].id;

    teamActivityTitle =
      list[0].title ||
      "⚔️ 組隊活動";

    teamActivityPhase =
      list[0].phase;

    openSelectedTeamActivity();
    return;
  }

  renderTeamActivityPicker();

  teamActivityPickerOverlay
    ?.classList.add(
      "show"
    );
}

function closeTeamActivity() {
  if (!teamActivityOverlay) {
    return;
  }

  closeTeamActivityForm();

  teamActivityOverlay.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "team-activity-open"
  );
}

function teamActivityBackgroundClick(
  event
) {
  if (
    event.target ===
      teamActivityOverlay
  ) {
    closeTeamActivity();
  }
}

function closeTeamActivityForm() {
  teamActivityFormMode = "";
  teamActivityFormTeamId = "";

  if (teamActivityForm) {
    teamActivityForm.style.display =
      "none";
  }

  if (teamActivityTeamNameInput) {
    teamActivityTeamNameInput.value =
      "";
  }

  if (teamActivityAccountInput) {
    teamActivityAccountInput.value =
      "";
  }

  if (teamActivityTurnoverInput) {
    teamActivityTurnoverInput.value =
      "";
  }

  if (teamActivityConfirmInput) {
    teamActivityConfirmInput.checked =
      false;
  }
}

function openTeamCreateForm() {
  if (
    !teamActivityForm ||
    ![
      "recruiting",
      "running"
    ].includes(
      teamActivityPhase
    )
  ) {
    return;
  }

  teamActivityFormMode =
    "create";

  teamActivityFormTeamId =
    "";

  const maxMembers =
    Math.max(
      2,
      Number(
        teamActivityState
          ?.settings
          ?.maxMembers || 5
      )
    );

  teamActivityFormTitle.textContent =
    "建立 " +
    maxMembers +
    " 人隊伍";

  teamActivityTeamNameWrap.style.display =
    "block";

  teamActivityAccountWrap.style.display =
    "block";

  teamActivitySubmitButton.textContent =
    "建立隊伍";

  teamActivityForm.style.display =
    "block";

  teamActivityTeamNameInput.focus();
}

function openTeamApplyForm(
  teamId,
  teamName
) {
  if (
    !teamActivityForm ||
    ![
      "recruiting",
      "running"
    ].includes(
      teamActivityPhase
    )
  ) {
    return;
  }

  teamActivityFormMode =
    "apply";

  teamActivityFormTeamId =
    String(teamId || "");

  teamActivityFormTitle.textContent =
    "申請加入｜" +
    String(teamName || "隊伍") +
    "（最多同時申請 3 隊）";

  teamActivityTeamNameWrap.style.display =
    "none";

  teamActivityAccountWrap.style.display =
    "block";

  teamActivitySubmitButton.textContent =
    "送出入隊申請";

  teamActivityForm.style.display =
    "block";

  teamActivityAccountInput.focus();
}

function openTeamTurnoverForm(
  currentTurnover
) {
  if (!teamActivityForm) {
    return;
  }

  teamActivityFormMode =
    "update";

  teamActivityFormTeamId =
    "";

  teamActivityFormTitle.textContent =
    "更新目前流水";

  teamActivityTeamNameWrap.style.display =
    "none";

  teamActivityAccountWrap.style.display =
    "none";

  teamActivityTurnoverInput.value =
    String(
      Number(currentTurnover || 0)
    );

  teamActivitySubmitButton.textContent =
    "確認更新流水";

  teamActivityConfirmInput.checked =
    false;

  teamActivityForm.style.display =
    "block";

  teamActivityTurnoverInput.focus();
}

async function submitTeamActivityForm() {
  const mode =
    teamActivityFormMode;

  if (!mode) {
    return;
  }

  if (
    !teamActivityConfirmInput ||
    !teamActivityConfirmInput.checked
  ) {
    alert(
      "請先勾選確認：以上流水為本人實際流水，並同意官方核對。"
    );
    return;
  }

  const turnover =
    String(
      teamActivityTurnoverInput.value ||
      ""
    )
      .replace(/,/g, "")
      .trim();

  if (!turnover) {
    alert(
      "請輸入目前流水"
    );
    return;
  }

  let action = "";
  let payload = {};

  if (mode === "create") {
    const teamName =
      String(
        teamActivityTeamNameInput.value ||
        ""
      )
        .trim()
        .slice(0, 24);

    const account =
      String(
        teamActivityAccountInput.value ||
        ""
      )
        .trim()
        .slice(0, 40);

    if (!teamName) {
      alert(
        "請輸入隊伍名稱"
      );
      return;
    }

    if (!account) {
      alert(
        "請輸入皇鼎會員帳號"
      );
      return;
    }

    action = "create-team";
    payload = {
      teamName,
      account,
      turnover
    };
  } else if (mode === "apply") {
    const account =
      String(
        teamActivityAccountInput.value ||
        ""
      )
        .trim()
        .slice(0, 40);

    if (!account) {
      alert(
        "請輸入皇鼎會員帳號"
      );
      return;
    }

    action = "apply";
    payload = {
      teamId:
        teamActivityFormTeamId,
      account,
      turnover
    };
  } else if (mode === "update") {
    action =
      "update-turnover";

    payload = {
      turnover
    };
  }

  if (!action) {
    return;
  }

  teamActivitySubmitButton.disabled =
    true;

  teamActivitySubmitButton.textContent =
    "處理中…";

  try {
    const data =
      await teamMemberApi(
        "/api/team/action",
        {
          action,
          ...payload
        }
      );

    if (data.state) {
      teamActivityState =
        data.state;
    }

    closeTeamActivityForm();
    renderTeamActivity();

    alert(
      data.message ||
      "完成 ✅"
    );

  } catch (error) {
    alert(
      error.message ||
      "操作失敗"
    );

  } finally {
    teamActivitySubmitButton.disabled =
      false;

    if (teamActivityFormMode) {
      teamActivitySubmitButton.textContent =
        teamActivityFormMode === "update"
          ? "確認更新流水"
          : teamActivityFormMode === "apply"
            ? "送出入隊申請"
            : "建立隊伍";
    }
  }
}

async function runTeamMemberAction(
  action,
  payload = {},
  confirmText = ""
) {
  if (
    confirmText &&
    !confirm(confirmText)
  ) {
    return;
  }

  try {
    const data =
      await teamMemberApi(
        "/api/team/action",
        {
          action,
          ...payload
        }
      );

    if (data.state) {
      teamActivityState =
        data.state;
      renderTeamActivity();
    } else {
      await loadTeamActivity(true);
    }

    if (data.message) {
      alert(data.message);
    }
  } catch (error) {
    alert(
      error.message ||
      "操作失敗"
    );
  }
}

function renderMyActivityTeam(
  parent,
  team,
  settings
) {
  const card =
    activityEl(
      "div",
      "team-activity-card team-activity-my-team"
    );

  const head =
    activityEl(
      "div",
      "team-card-head"
    );

  const titleWrap =
    activityEl(
      "div",
      "team-card-title-wrap"
    );

  titleWrap.appendChild(
    activityEl(
      "div",
      "team-card-kicker",
      team.isCaptain
        ? "👑 我的隊伍・我是隊長"
        : "👥 我的隊伍"
    )
  );

  titleWrap.appendChild(
    activityEl(
      "div",
      "team-card-title",
      team.name
    )
  );

  titleWrap.appendChild(
    activityEl(
      "div",
      "team-card-meta",
      "隊伍代碼 " +
      team.code +
      "　｜　" +
      team.memberCount +
      "/" +
      Number(
        team.maxMembers ||
        settings.maxMembers ||
        5
      ) +
      " 人" +
      (
        team.locked
          ? "　｜　🔒 已鎖隊"
          : settings.phase === "running"
            ? "　｜　🟢 未滿員，可繼續組隊"
            : ""
      )
    )
  );

  head.appendChild(
    titleWrap
  );

  card.appendChild(head);

  const memberList =
    activityEl(
      "div",
      "team-member-list"
    );

  (team.members || []).forEach(
    function(member) {
      const row =
        activityEl(
          "div",
          "team-member-row"
        );

      const info =
        activityEl(
          "div",
          "team-member-info"
        );

      const isCaptainMember =
        member.isCaptain === true;

      info.appendChild(
        activityEl(
          "div",
          "team-member-name",
          (
            member.isMe
              ? "👉 "
              : "👤 "
          ) +
          member.nickname +
          (
            isCaptainMember
              ? " 👑"
              : ""
          )
        )
      );

      info.appendChild(
        activityEl(
          "div",
          "team-member-account",
          "帳號：" +
          member.accountMasked
        )
      );

      const numbers =
        activityEl(
          "div",
          "team-member-turnover"
        );

      numbers.appendChild(
        activityEl(
          "span",
          "",
          "入隊 " +
          formatActivityNumber(
            member.initialTurnover
          )
        )
      );

      numbers.appendChild(
        activityEl(
          "span",
          "",
          "目前 " +
          formatActivityNumber(
            member.currentTurnover
          )
        )
      );

      numbers.appendChild(
        activityEl(
          "span",
          "team-contribution",
          "+" +
          formatActivityNumber(
            member.contribution
          )
        )
      );

      info.appendChild(numbers);

      const verify =
        activityEl(
          "div",
          member.verifiedCurrent
            ? "team-verify-status verified"
            : "team-verify-status pending",
          member.verifiedCurrent
            ? "✅ 官方已核對"
            : "🟡 待官方核對"
        );

      info.appendChild(verify);

      row.appendChild(info);

      const actions =
        activityEl(
          "div",
          "team-member-actions"
        );

      if (
        member.isMe &&
        [
          "recruiting",
          "running"
        ].includes(
          settings.phase
        )
      ) {
        actions.appendChild(
          activityButton(
            "✏️ 更新流水",
            "team-small-btn primary",
            function() {
              openTeamTurnoverForm(
                member.currentTurnover
              );
            }
          )
        );
      }

      if (
        team.isCaptain &&
        !member.isMe &&
        teamActivityRosterEditable(
          settings,
          team
        )
      ) {
        actions.appendChild(
          activityButton(
            "踢出",
            "team-small-btn danger",
            function() {
              runTeamMemberAction(
                "kick-member",
                {
                  teamId:
                    team.id,
                  targetVisitorId:
                    member.visitorId
                },
                "確定將「" +
                member.nickname +
                "」踢出隊伍嗎？"
              );
            }
          )
        );
      }

      if (actions.children.length) {
        row.appendChild(actions);
      }

      memberList.appendChild(row);
    }
  );

  card.appendChild(memberList);

  const totalInitialTurnover =
    (team.members || []).reduce(
      function(sum, member) {
        return (
          sum +
          Number(
            member.initialTurnover || 0
          )
        );
      },
      0
    );

  const totalCurrentTurnover =
    (team.members || []).reduce(
      function(sum, member) {
        return (
          sum +
          Number(
            member.currentTurnover || 0
          )
        );
      },
      0
    );

  const totalContribution =
    (team.members || []).reduce(
      function(sum, member) {
        return (
          sum +
          Number(
            member.contribution || 0
          )
        );
      },
      0
    );

  card.appendChild(
    activityEl(
      "div",
      "team-total-turnover",
      "💰 全隊入隊總流水：" +
      formatActivityNumber(
        totalInitialTurnover
      )
    )
  );

  card.appendChild(
    activityEl(
      "div",
      "team-total-turnover",
      "📊 全隊目前總流水：" +
      formatActivityNumber(
        totalCurrentTurnover
      )
    )
  );

  card.appendChild(
    activityEl(
      "div",
      "team-total-turnover",
      "🔥 全隊目前新增流水：" +
      formatActivityNumber(
        totalContribution
      )
    )
  );

  if (
    team.isCaptain &&
    teamActivityRosterEditable(
      settings,
      team
    )
  ) {
    const pendingTitle =
      activityEl(
        "div",
        "team-section-title",
        "待審核申請 " +
        (team.applications || [])
          .length +
        " 筆"
      );

    card.appendChild(
      pendingTitle
    );

    if (
      !(team.applications || [])
        .length
    ) {
      card.appendChild(
        activityEl(
          "div",
          "team-activity-empty compact",
          "目前沒有待審核申請"
        )
      );
    }

    (team.applications || []).forEach(
      function(application) {
        const row =
          activityEl(
            "div",
            "team-application-row"
          );

        const info =
          activityEl(
            "div",
            "team-application-info"
          );

        info.appendChild(
          activityEl(
            "div",
            "team-application-name",
            "👤 " +
            application.nickname
          )
        );

        info.appendChild(
          activityEl(
            "div",
            "team-application-meta",
            "帳號 " +
            application.accountMasked +
            "　｜　申報流水 " +
            formatActivityNumber(
              application.turnover
            )
          )
        );

        info.appendChild(
          activityEl(
            "div",
            "team-application-time",
            "申請時間 " +
            formatActivityTime(
              application.createdAt
            )
          )
        );

        row.appendChild(info);

        const actions =
          activityEl(
            "div",
            "team-application-actions"
          );

        actions.appendChild(
          activityButton(
            "✅ 同意",
            "team-small-btn approve",
            function() {
              runTeamMemberAction(
                "review-application",
                {
                  teamId:
                    team.id,
                  applicationId:
                    application.id,
                  decision:
                    "approve"
                }
              );
            }
          )
        );

        actions.appendChild(
          activityButton(
            "❌ 拒絕",
            "team-small-btn reject",
            function() {
              runTeamMemberAction(
                "review-application",
                {
                  teamId:
                    team.id,
                  applicationId:
                    application.id,
                  decision:
                    "reject"
                }
              );
            }
          )
        );

        row.appendChild(actions);
        card.appendChild(row);
      }
    );
  }

  if (
    teamActivityRosterEditable(
      settings,
      team
    )
  ) {
    const footer =
      activityEl(
        "div",
        "team-card-footer-actions"
      );

    if (team.isCaptain) {
      footer.appendChild(
        activityButton(
          "解散隊伍",
          "team-secondary-danger-btn",
          function() {
            runTeamMemberAction(
              "dissolve-team",
              {},
              "確定解散「" +
              team.name +
              "」嗎？隊內所有成員與待審核申請都會釋放。"
            );
          }
        )
      );
    } else {
      footer.appendChild(
        activityButton(
          "退出隊伍",
          "team-secondary-danger-btn",
          function() {
            runTeamMemberAction(
              "leave-team",
              {},
              "確定退出目前隊伍嗎？"
            );
          }
        )
      );
    }

    card.appendChild(footer);
  }

  parent.appendChild(card);
}

function renderTeamActivity() {
  if (
    !teamActivityContent ||
    !teamActivityState
  ) {
    return;
  }

  const state =
    teamActivityState;

  const settings =
    state.settings || {};

  setTeamActivityRoomState(
    settings
  );

  teamActivityContent.innerHTML =
    "";

  const intro =
    activityEl(
      "div",
      "team-activity-intro"
    );

  intro.appendChild(
    activityEl(
      "div",
      "team-activity-rules",
      settings.rules || ""
    )
  );

  if (settings.scheduleEnabled) {
    intro.appendChild(
      activityEl(
        "div",
        "team-activity-schedule-info",
        "🗓 活動開始：" +
        activityScheduleDisplay(
          settings.startAt
        ) +
        "　｜　結束：" +
        activityScheduleDisplay(
          settings.endAt
        )
      )
    );
  }

  teamActivityContent.appendChild(
    intro
  );

  renderTeamActivityPrizes(
    teamActivityContent,
    state.prizes || []
  );

  const warningBox =
    activityEl(
      "div",
      "team-activity-warning",
      state.warning || ""
    );

  warningBox.style.margin =
    "0 0 12px";

  teamActivityContent.appendChild(
    warningBox
  );

  if (state.blacklisted) {
    const blocked =
      activityEl(
        "div",
        "team-activity-blacklisted"
      );

    blocked.appendChild(
      activityEl(
        "div",
        "team-activity-blacklisted-title",
        "🚫 你目前無法參加流水活動"
      )
    );

    blocked.appendChild(
      activityEl(
        "div",
        "",
        state.blacklistReason ||
        "已列入流水活動黑名單"
      )
    );

    teamActivityContent.appendChild(
      blocked
    );

    return;
  }

  const pendingApplications =
    Array.isArray(
      state.pendingApplications
    )
      ? state.pendingApplications
      : (
          state.pending
            ? [state.pending]
            : []
        );

  if (pendingApplications.length) {
    const pendingSummary =
      activityEl(
        "div",
        "team-activity-card team-pending-card"
      );

    pendingSummary.appendChild(
      activityEl(
        "div",
        "team-card-kicker",
        "⏳ 等待隊長審核・" +
        pendingApplications.length +
        "/3"
      )
    );

    pendingSummary.appendChild(
      activityEl(
        "div",
        "team-card-meta",
        "你可以同時申請最多 3 個隊伍；任一隊長先同意後，其餘待審核申請會自動取消。"
      )
    );

    teamActivityContent.appendChild(
      pendingSummary
    );

    pendingApplications.forEach(
      function(pendingItem) {
        const pending =
          activityEl(
            "div",
            "team-activity-card team-pending-card"
          );

        pending.appendChild(
          activityEl(
            "div",
            "team-card-kicker",
            "📨 入隊申請審核中"
          )
        );

        pending.appendChild(
          activityEl(
            "div",
            "team-card-title",
            pendingItem.teamName
          )
        );

        pending.appendChild(
          activityEl(
            "div",
            "team-card-meta",
            "隊伍代碼 " +
            pendingItem.teamCode +
            "　｜　申報流水 " +
            formatActivityNumber(
              pendingItem.turnover
            )
          )
        );

        if (
          [
            "recruiting",
            "running"
          ].includes(
            settings.phase
          )
        ) {
          pending.appendChild(
            activityButton(
              "取消這筆申請",
              "team-secondary-danger-btn",
              function() {
                runTeamMemberAction(
                  "cancel-application",
                  {
                    teamId:
                      pendingItem.teamId,
                    applicationId:
                      pendingItem.applicationId
                  },
                  "確定取消申請「" +
                  pendingItem.teamName +
                  "」嗎？"
                );
              }
            )
          );
        }

        teamActivityContent.appendChild(
          pending
        );
      }
    );
  }

  if (state.myTeam) {
    renderMyActivityTeam(
      teamActivityContent,
      state.myTeam,
      settings
    );
  } else if (
    !pendingApplications.length &&
    [
      "recruiting",
      "running"
    ].includes(
      settings.phase
    )
  ) {
    const create =
      activityEl(
        "div",
        "team-create-entry"
      );

    create.appendChild(
      activityEl(
        "div",
        "team-create-entry-text",
        "還沒有隊伍？你可以自己當隊長建立一隊，本期每隊 " +
        Number(
          settings.maxMembers || 5
        ) +
        " 人。"
      )
    );

    create.appendChild(
      activityButton(
        "＋ 建立隊伍",
        "team-primary-btn",
        openTeamCreateForm
      )
    );

    teamActivityContent.appendChild(
      create
    );
  }

  const listTitle =
    activityEl(
      "div",
      "team-list-title",
      "目前隊伍"
    );

  teamActivityContent.appendChild(
    listTitle
  );

  const teams =
    Array.isArray(state.teams)
      ? state.teams
      : [];

  if (!teams.length) {
    teamActivityContent.appendChild(
      activityEl(
        "div",
        "team-activity-empty",
        "目前還沒有隊伍"
      )
    );
    return;
  }

  teams.forEach(
    function(team) {
      const row =
        activityEl(
          "div",
          "team-browser-row"
        );

      const info =
        activityEl(
          "div",
          "team-browser-info"
        );

      info.appendChild(
        activityEl(
          "div",
          "team-browser-name",
          team.name
        )
      );

      info.appendChild(
        activityEl(
          "div",
          "team-browser-meta",
          "隊長 " +
          team.captainName +
          "　｜　" +
          team.code +
          "　｜　" +
          team.memberCount +
          "/" +
          Number(
            team.maxMembers ||
            settings.maxMembers ||
            5
          )
        )
      );

      row.appendChild(info);

      const alreadyApplied =
        pendingApplications.some(
          item =>
            item.teamId ===
              team.id
        );

      if (team.full) {
        row.appendChild(
          activityEl(
            "span",
            "team-full-badge",
            "已滿員"
          )
        );
      } else if (alreadyApplied) {
        row.appendChild(
          activityEl(
            "span",
            "team-full-badge",
            "⏳ 審核中"
          )
        );
      } else if (
        !state.myTeam &&
        pendingApplications.length < 3 &&
        [
          "recruiting",
          "running"
        ].includes(
          settings.phase
        ) &&
        team.rosterEditable !== false
      ) {
        row.appendChild(
          activityButton(
            "申請加入",
            "team-small-btn primary",
            function() {
              openTeamApplyForm(
                team.id,
                team.name
              );
            }
          )
        );
      } else if (
        !state.myTeam &&
        pendingApplications.length >= 3
      ) {
        row.appendChild(
          activityEl(
            "span",
            "team-full-badge",
            "已達 3 隊上限"
          )
        );
      }

      teamActivityContent.appendChild(
        row
      );
    }
  );
}

/* ---------------- 管理員活動中心 ---------------- */

async function loadAdminTeamActivityRegistry() {
  if (!isAdminLoggedIn()) {
    return [];
  }

  try {
    const response =
      await fetch(
        "/api/admin/team-activities?room=" +
        encodeURIComponent(room),
        {
          headers:
            authHeaders(),
          cache: "no-store"
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "活動清單讀取失敗"
      );
    }

    teamActivityRegistry =
      Array.isArray(
        data.activities
      )
        ? data.activities
        : [];

    if (
      !teamActivityRegistry.some(
        item =>
          item.id ===
          teamActivityAdminSelectedId
      )
    ) {
      teamActivityAdminSelectedId =
        teamActivityRegistry[0]?.id ||
        "default";
    }

    renderAdminTeamActivityRegistry();

    return teamActivityRegistry;

  } catch (error) {
    alert(
      error.message ||
      "活動清單讀取失敗"
    );

    return [];
  }
}

function renderAdminTeamActivityRegistry() {
  if (!teamActivityAdminRegistryList) {
    return;
  }

  teamActivityAdminRegistryList.innerHTML =
    "";

  teamActivityRegistry.forEach(
    function(item) {
      const button =
        activityEl(
          "button",
          "activity-admin-registry-chip",
          (
            item.typeLabel
              ? item.typeLabel + "｜"
              : ""
          ) +
          (
            item.title ||
            "組隊活動"
          )
        );

      button.type = "button";

      if (
        item.id ===
        teamActivityAdminSelectedId
      ) {
        button.classList.add(
          "selected"
        );
      }

      button.addEventListener(
        "click",
        async function() {
          if (
            item.id ===
            teamActivityAdminSelectedId
          ) {
            return;
          }

          await saveTeamActivityAdminSettings(
            true
          );

          teamActivityAdminSelectedId =
            item.id;

          renderAdminTeamActivityRegistry();
          await loadTeamActivityAdmin();
        }
      );

      teamActivityAdminRegistryList.appendChild(
        button
      );
    }
  );
}

async function createAnotherTeamActivity() {
  if (!isOwnerAdmin()) {
    return;
  }

  const typeLabel =
    prompt(
      "這個組隊活動的類型？\n例如：儲值活動、流水活動、其他活動",
      "儲值活動"
    );

  if (typeLabel === null) {
    return;
  }

  const title =
    prompt(
      "輸入活動名稱：",
      "⚔️ " +
      String(
        typeLabel ||
        "組隊活動"
      )
    );

  if (title === null) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/team-activities/action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              action: "create",
              title:
                String(title || ""),
              typeLabel:
                String(
                  typeLabel ||
                  "組隊活動"
                )
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "新增活動失敗"
      );
    }

    teamActivityRegistry =
      data.activities || [];

    teamActivityAdminSelectedId =
      data.activityId ||
      "default";

    renderAdminTeamActivityRegistry();
    await loadTeamActivityAdmin();

  } catch (error) {
    alert(
      error.message ||
      "新增活動失敗"
    );
  }
}

async function syncSelectedActivityRegistry(settings) {
  if (
    !isOwnerAdmin() ||
    teamActivityAdminSelectedId ===
      "default"
  ) {
    return;
  }

  const current =
    teamActivityRegistry.find(
      item =>
        item.id ===
        teamActivityAdminSelectedId
    );

  try {
    const response =
      await fetch(
        "/api/admin/team-activities/action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              action: "update",
              activityId:
                teamActivityAdminSelectedId,
              title:
                settings?.title ||
                teamActivityAdminTitleInput?.value ||
                current?.title ||
                "⚔️ 組隊活動",
              typeLabel:
                current?.typeLabel ||
                "組隊活動",
              phase:
                settings?.phase ||
                current?.phase ||
                "off"
            })
        }
      );

    const data =
      await response.json();

    if (
      response.ok &&
      data.ok
    ) {
      teamActivityRegistry =
        data.activities || [];

      renderAdminTeamActivityRegistry();
    }
  } catch {}
}

async function deleteCurrentTeamActivity() {
  if (
    !isOwnerAdmin() ||
    teamActivityAdminSelectedId ===
      "default"
  ) {
    alert(
      "預設活動不能刪除"
    );
    return;
  }

  const current =
    teamActivityRegistry.find(
      item =>
        item.id ===
        teamActivityAdminSelectedId
    );

  if (
    !confirm(
      "確定刪除「" +
      (
        current?.title ||
        "這個組隊活動"
      ) +
      "」嗎？"
    )
  ) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/team-activities/action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              action: "delete",
              activityId:
                teamActivityAdminSelectedId
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "刪除活動失敗"
      );
    }

    teamActivityRegistry =
      data.activities || [];

    teamActivityAdminSelectedId =
      "default";

    renderAdminTeamActivityRegistry();
    await loadTeamActivityAdmin();

  } catch (error) {
    alert(
      error.message ||
      "刪除活動失敗"
    );
  }
}

function openTeamActivityAdmin() {
  if (
    !isAdminLoggedIn() ||
    !teamActivityAdminOverlay
  ) {
    alert(
      "請先登入管理員"
    );
    return;
  }

  teamActivityAdminOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "team-activity-open"
  );

  loadAdminTeamActivityRegistry()
    .then(
      function() {
        loadTeamActivityAdmin();
      }
    );
}

function closeTeamActivityAdmin() {
  if (!teamActivityAdminOverlay) {
    return;
  }

  teamActivityAdminOverlay.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "team-activity-open"
  );
}

function teamActivityAdminBackgroundClick(
  event
) {
  if (
    event.target ===
      teamActivityAdminOverlay
  ) {
    closeTeamActivityAdmin();
  }
}

async function loadTeamActivityAdmin() {
  if (!isAdminLoggedIn()) {
    return;
  }

  if (teamActivityAdminTeams) {
    teamActivityAdminTeams.innerHTML =
      '<div class="team-activity-empty">讀取中…</div>';
  }

  try {
    const response =
      await fetch(
        "/api/admin/team-activity?room=" +
        encodeURIComponent(room) +
        "&activityId=" +
        encodeURIComponent(
          teamActivityAdminSelectedId
        ),
        {
          headers:
            authHeaders()
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "讀取活動失敗"
      );
    }

    renderTeamActivityAdmin(
      data.data
    );

  } catch (error) {
    if (teamActivityAdminTeams) {
      teamActivityAdminTeams.innerHTML =
        "";

      teamActivityAdminTeams.appendChild(
        activityEl(
          "div",
          "team-activity-empty",
          error.message ||
          "讀取活動失敗"
        )
      );
    }
  }
}

async function adminTeamActivityAction(
  payload,
  successMessage = ""
) {
  try {
    const response =
      await fetch(
        "/api/admin/team-activity/action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            activityId:
              teamActivityAdminSelectedId,
            ...payload
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "活動操作失敗"
      );
    }

    if (data.data) {
      renderTeamActivityAdmin(
        data.data
      );
    } else {
      await loadTeamActivityAdmin();
    }

    if (successMessage) {
      alert(successMessage);
    }

    return true;

  } catch (error) {
    alert(
      error.message ||
      "活動操作失敗"
    );

    return false;
  }
}

function makeTeamActivityPrizeId() {
  return (
    "prize-" +
    Date.now().toString(36) +
    "-" +
    Math.random()
      .toString(36)
      .slice(2, 7)
  );
}

function addTeamActivityPrizeItem() {
  if (
    teamActivityAdminPrizeItems.length >=
    TEAM_ACTIVITY_MAX_PRIZES
  ) {
    alert(
      "活動獎品最多只能設定 " +
      TEAM_ACTIVITY_MAX_PRIZES +
      " 個"
    );
    return;
  }

  const index =
    teamActivityAdminPrizeItems.length;

  const defaultLabels = [
    "🥇 第一名",
    "🥈 第二名",
    "🥉 第三名"
  ];

  teamActivityAdminPrizeItems.push({
    id:
      makeTeamActivityPrizeId(),
    label:
      defaultLabels[index] || "",
    title:
      "",
    description:
      "",
    imageData:
      ""
  });

  renderTeamActivityPrizeEditor();
}

function removeTeamActivityPrizeItem(
  prizeId
) {
  teamActivityAdminPrizeItems =
    teamActivityAdminPrizeItems
      .filter(
        item =>
          item.id !== prizeId
      );

  renderTeamActivityPrizeEditor();
}

async function changeTeamActivityPrizeImage(
  prizeId,
  file
) {
  if (
    !file ||
    !String(
      file.type || ""
    ).startsWith("image/")
  ) {
    return;
  }

  try {
    const data =
      await compressImage(file);

    if (
      !data ||
      data.length > 500000
    ) {
      alert(
        "圖片壓縮後仍太大，請換一張圖片"
      );
      return;
    }

    const item =
      teamActivityAdminPrizeItems
        .find(
          row =>
            row.id === prizeId
        );

    if (!item) {
      return;
    }

    item.imageData =
      data;

    renderTeamActivityPrizeEditor();

  } catch {
    alert(
      "獎品圖片處理失敗"
    );
  }
}

function renderTeamActivityPrizeEditor() {
  if (!teamActivityAdminPrizeEditor) {
    return;
  }

  teamActivityAdminPrizeEditor.innerHTML =
    "";

  if (
    teamActivityAdminPrizeAddButton
  ) {
    teamActivityAdminPrizeAddButton.disabled =
      teamActivityAdminPrizeItems.length >=
      TEAM_ACTIVITY_MAX_PRIZES;
  }

  if (
    !teamActivityAdminPrizeItems.length
  ) {
    teamActivityAdminPrizeEditor.appendChild(
      activityEl(
        "div",
        "team-activity-empty",
        "目前沒有設定活動獎品"
      )
    );
    return;
  }

  teamActivityAdminPrizeItems.forEach(
    function(item, index) {
      const box =
        activityEl(
          "div",
          "activity-prize-editor-item"
        );

      const grid =
        activityEl(
          "div",
          "activity-prize-editor-grid"
        );

      const labelInput =
        document.createElement(
          "input"
        );

      labelInput.maxLength =
        40;

      labelInput.placeholder =
        "字幕，例如：🥇 第一名";

      labelInput.value =
        item.label || "";

      labelInput.addEventListener(
        "input",
        function() {
          item.label =
            labelInput.value;
        }
      );

      const titleInput =
        document.createElement(
          "input"
        );

      titleInput.maxLength =
        80;

      titleInput.placeholder =
        "獎品名稱，例如：iPhone 17 Pro";

      titleInput.value =
        item.title || "";

      titleInput.addEventListener(
        "input",
        function() {
          item.title =
            titleInput.value;
        }
      );

      grid.appendChild(
        labelInput
      );

      grid.appendChild(
        titleInput
      );

      box.appendChild(
        grid
      );

      const description =
        document.createElement(
          "textarea"
        );

      description.maxLength =
        300;

      description.placeholder =
        "獎品說明／條件（可不填）";

      description.value =
        item.description || "";

      description.addEventListener(
        "input",
        function() {
          item.description =
            description.value;
        }
      );

      box.appendChild(
        description
      );

      if (item.imageData) {
        const preview =
          activityEl(
            "div",
            "activity-prize-editor-preview"
          );

        const image =
          document.createElement(
            "img"
          );

        image.src =
          item.imageData;

        image.alt =
          "獎品圖片";

        image.addEventListener(
          "click",
          function() {
            openImagePreview(
              item.imageData
            );
          }
        );

        preview.appendChild(
          image
        );

        box.appendChild(
          preview
        );
      }

      const actions =
        activityEl(
          "div",
          "activity-prize-editor-actions"
        );

      const fileLabel =
        document.createElement(
          "label"
        );

      fileLabel.className =
        "team-secondary-btn";

      fileLabel.style.cursor =
        "pointer";

      fileLabel.textContent =
        item.imageData
          ? "📷 更換圖片"
          : "📷 上傳圖片";

      const fileInput =
        document.createElement(
          "input"
        );

      fileInput.type =
        "file";

      fileInput.accept =
        "image/*";

      fileInput.style.display =
        "none";

      fileInput.addEventListener(
        "change",
        function() {
          const file =
            fileInput.files?.[0];

          fileInput.value =
            "";

          if (file) {
            changeTeamActivityPrizeImage(
              item.id,
              file
            );
          }
        }
      );

      fileLabel.appendChild(
        fileInput
      );

      actions.appendChild(
        fileLabel
      );

      if (item.imageData) {
        actions.appendChild(
          activityButton(
            "移除圖片",
            "team-secondary-btn",
            function() {
              item.imageData =
                "";
              renderTeamActivityPrizeEditor();
            }
          )
        );
      }

      actions.appendChild(
        activityButton(
          "刪除獎品",
          "team-secondary-danger-btn",
          function() {
            removeTeamActivityPrizeItem(
              item.id
            );
          }
        )
      );

      box.appendChild(
        actions
      );

      teamActivityAdminPrizeEditor.appendChild(
        box
      );
    }
  );
}

function renderTeamActivityPrizes(
  parent,
  prizes
) {
  const list =
    (
      Array.isArray(prizes)
        ? prizes
        : []
    ).filter(
      item =>
        item &&
        (
          item.label ||
          item.title ||
          item.description ||
          item.imageData
        )
    );

  if (!list.length) {
    return;
  }

  const section =
    activityEl(
      "div",
      "team-activity-prize-section"
    );

  section.appendChild(
    activityEl(
      "div",
      "team-activity-prize-heading",
      "🎁 本期活動獎品"
    )
  );

  const grid =
    activityEl(
      "div",
      "team-activity-prize-grid"
    );

  list.forEach(
    function(item) {
      const card =
        activityEl(
          "div",
          "team-activity-prize-card"
        );

      const body =
        activityEl(
          "div",
          "team-activity-prize-body"
        );

      if (item.label) {
        body.appendChild(
          activityEl(
            "div",
            "team-activity-prize-label",
            item.label
          )
        );
      }

      if (item.title) {
        body.appendChild(
          activityEl(
            "div",
            "team-activity-prize-title",
            item.title
          )
        );
      }

      if (item.description) {
        body.appendChild(
          activityEl(
            "div",
            "team-activity-prize-description",
            item.description
          )
        );
      }

      card.appendChild(
        body
      );

      if (item.imageData) {
        const button =
          document.createElement(
            "button"
          );

        button.type =
          "button";

        button.className =
          "team-activity-prize-image-btn";

        button.setAttribute(
          "aria-label",
          "點擊放大查看獎品圖片"
        );

        const image =
          document.createElement(
            "img"
          );

        image.className =
          "team-activity-prize-image";

        image.src =
          item.imageData;

        image.alt =
          item.title ||
          item.label ||
          "活動獎品";

        button.appendChild(
          image
        );

        button.addEventListener(
          "click",
          function() {
            openImagePreview(
              item.imageData
            );
          }
        );

        card.appendChild(
          button
        );
      }

      grid.appendChild(
        card
      );
    }
  );

  section.appendChild(
    grid
  );

  parent.appendChild(
    section
  );
}

function formatActivityHistoryDate(
  value
) {
  const time =
    Number(value || 0);

  if (!time) {
    return "未設定";
  }

  try {
    return new Intl.DateTimeFormat(
      "zh-TW",
      {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }
    ).format(
      new Date(time)
    );
  } catch {
    return "";
  }
}

function openTeamActivityHistory() {
  if (
    !isAdminLoggedIn() ||
    !isOwnerAdmin()
  ) {
    alert(
      "活動紀錄只有主管理員可以查看"
    );
    return;
  }

  if (!teamActivityHistoryOverlay) {
    return;
  }

  teamActivityHistoryOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "team-activity-open"
  );

  loadTeamActivityHistory();
}

function closeTeamActivityHistory() {
  teamActivityHistoryOverlay
    ?.classList.remove(
      "show"
    );

  if (
    !teamActivityAdminOverlay
      ?.classList.contains("show")
  ) {
    document.body.classList.remove(
      "team-activity-open"
    );
  }
}

function teamActivityHistoryBackgroundClick(
  event
) {
  if (
    event.target ===
      teamActivityHistoryOverlay
  ) {
    closeTeamActivityHistory();
  }
}

async function loadTeamActivityHistory() {
  if (!teamActivityHistoryList) {
    return;
  }

  teamActivityHistoryList.innerHTML =
    '<div class="team-activity-empty">讀取活動紀錄中…</div>';

  try {
    const response =
      await fetch(
        "/api/admin/team-activity-history?room=" +
        encodeURIComponent(room) +
        "&activityId=" +
        encodeURIComponent(
          teamActivityAdminSelectedId
        ),
        {
          headers:
            authHeaders(),
          cache:
            "no-store"
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "活動紀錄讀取失敗"
      );
    }

    renderTeamActivityHistory(
      data.histories || []
    );

  } catch (error) {
    teamActivityHistoryList.innerHTML =
      "";

    teamActivityHistoryList.appendChild(
      activityEl(
        "div",
        "team-activity-empty",
        error.message ||
        "活動紀錄讀取失敗"
      )
    );
  }
}

function renderTeamActivityHistory(
  histories
) {
  if (!teamActivityHistoryList) {
    return;
  }

  teamActivityHistoryList.innerHTML =
    "";

  const list =
    Array.isArray(histories)
      ? histories
      : [];

  if (!list.length) {
    teamActivityHistoryList.appendChild(
      activityEl(
        "div",
        "team-activity-empty",
        "目前還沒有歷屆活動紀錄。按「🏁 結束活動」後會自動封存本期資料。"
      )
    );
    return;
  }

  list.forEach(
    function(history) {
      const details =
        document.createElement(
          "details"
        );

      details.className =
        "activity-history-card";

      const summary =
        document.createElement(
          "summary"
        );

      summary.className =
        "activity-history-summary";

      summary.appendChild(
        activityEl(
          "div",
          "activity-history-title",
          history.title ||
          "⚔️ 組隊活動"
        )
      );

      summary.appendChild(
        activityEl(
          "div",
          "activity-history-meta",
          "結束時間：" +
          formatActivityHistoryDate(
            history.endedAt
          ) +
          "｜每隊 " +
          Number(
            history.maxMembers || 5
          ) +
          " 人"
        )
      );

      const stats =
        activityEl(
          "div",
          "activity-history-stats"
        );

      [
        [
          "隊伍",
          formatActivityNumber(
            history.teamCount || 0
          ) + " 隊"
        ],
        [
          "參加人數",
          formatActivityNumber(
            history.memberCount || 0
          ) + " 人"
        ],
        [
          "本期新增流水",
          "+" +
          formatActivityNumber(
            history.totalContribution ||
            0
          )
        ]
      ].forEach(
        function(item) {
          const stat =
            activityEl(
              "div",
              "activity-history-stat"
            );

          stat.appendChild(
            activityEl(
              "span",
              "",
              item[0]
            )
          );

          stat.appendChild(
            activityEl(
              "strong",
              "",
              item[1]
            )
          );

          stats.appendChild(
            stat
          );
        }
      );

      summary.appendChild(
        stats
      );

      details.appendChild(
        summary
      );

      const detail =
        activityEl(
          "div",
          "activity-history-detail"
        );

      if (history.rules) {
        detail.appendChild(
          activityEl(
            "div",
            "activity-history-section-title",
            "📋 活動規則"
          )
        );

        detail.appendChild(
          activityEl(
            "div",
            "team-activity-rules",
            history.rules
          )
        );
      }

      const prizes =
        Array.isArray(
          history.prizes
        )
          ? history.prizes
          : [];

      if (prizes.length) {
        detail.appendChild(
          activityEl(
            "div",
            "activity-history-section-title",
            "🎁 當期獎品"
          )
        );

        const prizeGrid =
          activityEl(
            "div",
            "activity-history-prize-grid"
          );

        prizes.forEach(
          function(prize) {
            const card =
              activityEl(
                "div",
                "activity-history-prize"
              );

            if (prize.imageData) {
              const image =
                document.createElement(
                  "img"
                );

              image.src =
                prize.imageData;

              image.alt =
                prize.title ||
                prize.label ||
                "活動獎品";

              image.addEventListener(
                "click",
                function() {
                  openImagePreview(
                    prize.imageData
                  );
                }
              );

              card.appendChild(
                image
              );
            }

            const body =
              activityEl(
                "div",
                "activity-history-prize-body"
              );

            const lines =
              [
                prize.label,
                prize.title,
                prize.description
              ]
                .filter(Boolean)
                .join("\n");

            body.textContent =
              lines ||
              "未命名獎品";

            card.appendChild(
              body
            );

            prizeGrid.appendChild(
              card
            );
          }
        );

        detail.appendChild(
          prizeGrid
        );
      }

      detail.appendChild(
        activityEl(
          "div",
          "activity-history-section-title",
          "👥 隊伍成績"
        )
      );

      const teams =
        Array.isArray(
          history.teams
        )
          ? history.teams
          : [];

      if (!teams.length) {
        detail.appendChild(
          activityEl(
            "div",
            "team-activity-empty",
            "本期沒有隊伍"
          )
        );
      }

      teams.forEach(
        function(team) {
          const teamBox =
            activityEl(
              "div",
              "activity-history-team"
            );

          teamBox.appendChild(
            activityEl(
              "div",
              "activity-history-team-title",
              team.name +
              "｜" +
              team.memberCount +
              "/" +
              team.maxMembers
            )
          );

          teamBox.appendChild(
            activityEl(
              "div",
              "activity-history-meta",
              "隊長：" +
              team.captainName +
              "｜入隊總流水 " +
              formatActivityNumber(
                team.initialTurnover
              ) +
              "｜最後總流水 " +
              formatActivityNumber(
                team.currentTurnover
              ) +
              "｜新增 +" +
              formatActivityNumber(
                team.contribution
              )
            )
          );

          (
            Array.isArray(
              team.members
            )
              ? team.members
              : []
          ).forEach(
            function(member) {
              teamBox.appendChild(
                activityEl(
                  "div",
                  "activity-history-member",
                  (
                    member.isCaptain
                      ? "👑 "
                      : "👤 "
                  ) +
                  member.nickname +
                  "｜帳號 " +
                  member.account +
                  "｜入隊 " +
                  formatActivityNumber(
                    member.initialTurnover
                  ) +
                  " → 最後 " +
                  formatActivityNumber(
                    member.currentTurnover
                  ) +
                  "｜新增 +" +
                  formatActivityNumber(
                    member.contribution
                  )
                )
              );
            }
          );

          detail.appendChild(
            teamBox
          );
        }
      );

      if (isOwnerAdmin()) {
        const deleteButton =
          activityButton(
            "🗑 刪除這筆活動紀錄",
            "team-secondary-danger-btn activity-history-delete",
            async function() {
              if (
                !confirm(
                  "確定刪除「" +
                  (
                    history.title ||
                    "這筆活動"
                  ) +
                  "」的歷屆紀錄嗎？\n\n此動作無法復原。"
                )
              ) {
                return;
              }

              try {
                const response =
                  await fetch(
                    "/api/admin/team-activity-history/action",
                    {
                      method:
                        "POST",
                      headers: {
                        "Content-Type":
                          "application/json",
                        ...authHeaders()
                      },
                      body:
                        JSON.stringify({
                          action:
                            "delete",
                          historyId:
                            history.id,
                          activityId:
                            teamActivityAdminSelectedId
                        })
                    }
                  );

                const data =
                  await response.json();

                if (
                  !response.ok ||
                  !data.ok
                ) {
                  throw new Error(
                    data.message ||
                    "刪除失敗"
                  );
                }

                renderTeamActivityHistory(
                  data.histories ||
                  []
                );

              } catch (error) {
                alert(
                  error.message ||
                  "刪除失敗"
                );
              }
            }
          );

        detail.appendChild(
          deleteButton
        );
      }

      details.appendChild(
        detail
      );

      teamActivityHistoryList.appendChild(
        details
      );
    }
  );
}

function renderTeamActivityAdmin(
  data
) {
  const source =
    data &&
    typeof data === "object"
      ? data
      : {};

  const settings =
    source.settings || {};

  teamActivityAdminLastNoticeText =
    String(
      source.chatNotice?.text || ""
    );

  teamActivityAdminPrizeItems =
    (
      Array.isArray(source.prizes)
        ? source.prizes
        : []
    ).map(
      item => ({
        id:
          String(
            item.id ||
            makeTeamActivityPrizeId()
          ),
        label:
          String(
            item.label || ""
          ),
        title:
          String(
            item.title || ""
          ),
        description:
          String(
            item.description || ""
          ),
        imageData:
          String(
            item.imageData || ""
          )
      })
    );

  renderTeamActivityPrizeEditor();

  if (teamActivityAdminTitleInput) {
    teamActivityAdminTitleInput.value =
      settings.title ||
      "⚔️ 組隊活動";
  }

  if (teamActivityAdminRulesInput) {
    teamActivityAdminRulesInput.value =
      settings.rules || "";
  }

  if (teamActivityAdminMaxMembersInput) {
    teamActivityAdminMaxMembersInput.value =
      String(
        Math.max(
          2,
          Math.min(
            20,
            Number(
              settings.maxMembers || 5
            )
          )
        )
      );
  }

  if (teamActivityScheduleEnabledInput) {
    teamActivityScheduleEnabledInput.checked =
      settings.scheduleEnabled === true;
  }

  if (teamActivityStartAtInput) {
    teamActivityStartAtInput.value =
      activityDateTimeLocalValue(
        settings.startAt
      );
  }

  if (teamActivityEndAtInput) {
    teamActivityEndAtInput.value =
      activityDateTimeLocalValue(
        settings.endAt
      );
  }

  syncSelectedActivityRegistry(
    settings
  );

  if (teamActivityAdminPhase) {
    teamActivityAdminPhase.textContent =
      teamActivityPhaseLabel(
        settings.phase || "off"
      );

    teamActivityAdminPhase.dataset.phase =
      settings.phase || "off";
  }

  if (teamActivityAdminTeams) {
    teamActivityAdminTeams.innerHTML =
      "";

    const teams =
      Array.isArray(source.teams)
        ? source.teams
        : [];

    if (!teams.length) {
      teamActivityAdminTeams.appendChild(
        activityEl(
          "div",
          "team-activity-empty",
          "目前沒有隊伍"
        )
      );
    }

    teams.forEach(
      function(team) {
        const card =
          activityEl(
            "div",
            "activity-admin-team-card"
          );

        const head =
          activityEl(
            "div",
            "activity-admin-team-head"
          );

        const info =
          activityEl(
            "div",
            ""
          );

        info.appendChild(
          activityEl(
            "div",
            "activity-admin-team-name",
            team.name +
            "　" +
            team.memberCount +
            "/" +
            Number(
              team.maxMembers ||
              settings.maxMembers ||
              5
            )
          )
        );

        info.appendChild(
          activityEl(
            "div",
            "activity-admin-team-meta",
            "代碼 " +
            team.code +
            "｜隊長 " +
            team.captainName +
            (
              team.locked
                ? "｜🔒 已滿員・已鎖隊"
                : settings.phase === "running"
                  ? "｜🟢 未滿員・可繼續組隊"
                  : ""
            )
          )
        );

        head.appendChild(info);

        if (isOwnerAdmin()) {
          head.appendChild(
            activityButton(
              "解散",
              "team-small-btn danger",
              function() {
                if (
                  confirm(
                    "確定由管理員解散「" +
                    team.name +
                    "」嗎？"
                  )
                ) {
                  adminTeamActivityAction(
                    {
                      action:
                        "dissolve-team",
                      teamId:
                        team.id
                    },
                    "隊伍已解散"
                  );
                }
              }
            )
          );
        }

        card.appendChild(head);

        (team.members || []).forEach(
          function(member) {
            const row =
              activityEl(
                "div",
                "activity-admin-member-row"
              );

            const memberInfo =
              activityEl(
                "div",
                "activity-admin-member-info"
              );

            memberInfo.appendChild(
              activityEl(
                "div",
                "activity-admin-member-name",
                member.nickname
              )
            );

            memberInfo.appendChild(
              activityEl(
                "div",
                "activity-admin-member-meta",
                "帳號：" +
                (member.account || "") +
                "｜入隊：" +
                formatActivityNumber(
                  member.initialTurnover
                ) +
                "｜目前：" +
                formatActivityNumber(
                  member.currentTurnover
                ) +
                "｜新增：+" +
                formatActivityNumber(
                  member.contribution
                )
              )
            );

            memberInfo.appendChild(
              activityEl(
                "div",
                member.verifiedCurrent
                  ? "team-verify-status verified"
                  : "team-verify-status pending",
                member.verifiedCurrent
                  ? "✅ 已核對目前流水"
                  : "🟡 目前流水待核對"
              )
            );

            const turnoverHistory =
              Array.isArray(
                member.turnoverHistory
              )
                ? member.turnoverHistory
                : [];

            if (turnoverHistory.length > 1) {
              const details =
                activityEl(
                  "details",
                  "activity-turnover-history"
                );

              const summary =
                activityEl(
                  "summary",
                  "",
                  "查看流水更新紀錄 " +
                  (turnoverHistory.length - 1) +
                  " 筆"
                );

              details.appendChild(summary);

              turnoverHistory.slice(1).forEach(
                function(historyItem) {
                  details.appendChild(
                    activityEl(
                      "div",
                      "activity-turnover-history-row",
                      formatActivityTime(
                        historyItem.time
                      ) +
                      "　" +
                      formatActivityNumber(
                        historyItem.from
                      ) +
                      " → " +
                      formatActivityNumber(
                        historyItem.to
                      )
                    )
                  );
                }
              );

              memberInfo.appendChild(details);
            }

            row.appendChild(
              memberInfo
            );

            const actions =
              activityEl(
                "div",
                "activity-admin-member-actions"
              );

            actions.appendChild(
              activityButton(
                "✅ 核對",
                "team-small-btn approve",
                function() {
                  adminTeamActivityAction(
                    {
                      action:
                        "verify-member",
                      teamId:
                        team.id,
                      visitorId:
                        member.visitorId
                    },
                    "已標記官方核對 ✅"
                  );
                }
              )
            );

            actions.appendChild(
              activityButton(
                "移除",
                "team-small-btn reject",
                function() {
                  if (
                    confirm(
                      "確定將「" +
                      member.nickname +
                      "」移出本期組隊活動嗎？\n\n這個動作不會加入黑名單。"
                    )
                  ) {
                    adminTeamActivityAction(
                      {
                        action:
                          "remove-member",
                        teamId:
                          team.id,
                        visitorId:
                          member.visitorId
                      },
                      "已移除活動成員"
                    );
                  }
                }
              )
            );

            if (isOwnerAdmin()) {
              actions.appendChild(
                activityButton(
                  "🚫 謊報黑名單",
                  "team-small-btn danger",
                  function() {
                    const reason =
                      prompt(
                        "請填寫列入流水活動黑名單的原因：",
                        "謊報流水"
                      );

                    if (reason === null) {
                      return;
                    }

                    if (
                      !confirm(
                        "確定將「" +
                        member.nickname +
                        "」列入流水活動黑名單嗎？\n\n會員帳號：" +
                        (member.account || "")
                      )
                    ) {
                      return;
                    }

                    adminTeamActivityAction(
                      {
                        action:
                          "blacklist-member",
                        teamId:
                          team.id,
                        visitorId:
                          member.visitorId,
                        reason:
                          String(reason || "謊報流水")
                      },
                      "已列入流水活動黑名單 🚫"
                    );
                  }
                )
              );
            }

            row.appendChild(actions);
            card.appendChild(row);
          }
        );

        const totalInitialTurnover =
          (team.members || []).reduce(
            function(sum, member) {
              return sum +
                Number(
                  member.initialTurnover || 0
                );
            },
            0
          );

        const totalCurrentTurnover =
          (team.members || []).reduce(
            function(sum, member) {
              return sum +
                Number(
                  member.currentTurnover || 0
                );
            },
            0
          );

        const totalContribution =
          (team.members || []).reduce(
            function(sum, member) {
              return sum +
                Number(
                  member.contribution || 0
                );
            },
            0
          );

        card.appendChild(
          activityEl(
            "div",
            "team-total-turnover",
            "💰 全隊入隊總流水：" +
            formatActivityNumber(
              totalInitialTurnover
            )
          )
        );

        card.appendChild(
          activityEl(
            "div",
            "team-total-turnover",
            "📊 全隊目前總流水：" +
            formatActivityNumber(
              totalCurrentTurnover
            )
          )
        );

        card.appendChild(
          activityEl(
            "div",
            "team-total-turnover",
            "🔥 全隊目前新增流水：" +
            formatActivityNumber(
              totalContribution
            )
          )
        );

        if (
          (team.applications || [])
            .length
        ) {
          card.appendChild(
            activityEl(
              "div",
              "team-section-title",
              "待隊長審核 " +
              team.applications.length +
              " 筆"
            )
          );

          team.applications.forEach(
            function(application) {
              card.appendChild(
                activityEl(
                  "div",
                  "activity-admin-pending-row",
                  application.nickname +
                  "｜" +
                  (application.account || "") +
                  "｜申報 " +
                  formatActivityNumber(
                    application.turnover
                  )
                )
              );
            }
          );
        }

        teamActivityAdminTeams.appendChild(
          card
        );
      }
    );
  }

  if (teamActivityAdminBlacklist) {
    teamActivityAdminBlacklist.innerHTML =
      "";

    const blacklist =
      Array.isArray(source.blacklist)
        ? source.blacklist
        : [];

    if (!blacklist.length) {
      teamActivityAdminBlacklist.appendChild(
        activityEl(
          "div",
          "team-activity-empty compact",
          "目前沒有流水活動黑名單"
        )
      );
    }

    blacklist.forEach(
      function(item) {
        const row =
          activityEl(
            "div",
            "activity-blacklist-row"
          );

        const info =
          activityEl(
            "div",
            "activity-blacklist-info"
          );

        info.appendChild(
          activityEl(
            "div",
            "activity-blacklist-account",
            "🚫 " +
            (item.account || "")
          )
        );

        info.appendChild(
          activityEl(
            "div",
            "activity-blacklist-reason",
            "原因：" +
            (item.reason || "流水資料異常")
          )
        );

        if (
          Number(item.currentTurnover || 0) > 0 ||
          Number(item.initialTurnover || 0) > 0
        ) {
          info.appendChild(
            activityEl(
              "div",
              "activity-blacklist-reason",
              "留存申報：入隊 " +
              formatActivityNumber(
                item.initialTurnover
              ) +
              " → 最後 " +
              formatActivityNumber(
                item.currentTurnover
              )
            )
          );
        }

        row.appendChild(info);

        if (isOwnerAdmin()) {
          row.appendChild(
            activityButton(
              "解除",
              "team-small-btn reject",
              function() {
                if (
                  confirm(
                    "確定解除帳號「" +
                    item.account +
                    "」的流水活動黑名單嗎？"
                  )
                ) {
                  adminTeamActivityAction(
                    {
                      action:
                        "unblacklist",
                      account:
                        item.account
                    },
                    "流水活動黑名單已解除 ✅"
                  );
                }
              }
            )
          );
        }

        teamActivityAdminBlacklist.appendChild(
          row
        );
      }
    );
  }

  applyAdminRoleUI();
}

async function saveTeamActivityAdminSettings(
  silent = false
) {
  return await adminTeamActivityAction(
    {
      action:
        "save-settings",
      title:
        String(
          teamActivityAdminTitleInput.value ||
          ""
        ),
      rules:
        String(
          teamActivityAdminRulesInput.value ||
          ""
        ),

      maxMembers:
        Math.max(
          2,
          Math.min(
            20,
            Math.floor(
              Number(
                teamActivityAdminMaxMembersInput?.value ||
                5
              )
            )
          )
        ),

      prizes:
        teamActivityAdminPrizeItems
          .slice(
            0,
            TEAM_ACTIVITY_MAX_PRIZES
          )
          .map(
            item => ({
              id:
                item.id,
              label:
                String(
                  item.label || ""
                )
                  .trim()
                  .slice(0, 40),
              title:
                String(
                  item.title || ""
                )
                  .trim()
                  .slice(0, 80),
              description:
                String(
                  item.description || ""
                )
                  .trim()
                  .slice(0, 300),
              imageData:
                String(
                  item.imageData || ""
                )
            })
          )
    },
    silent
      ? ""
      : "活動內容已儲存 ✅"
  );
}

async function saveTeamActivityAdminSchedule() {
  /*
    第58項：
    不再讓 checkbox 決定「是否取消預約」。
    只要開始與結束時間都有填，就直接儲存為預約。
  */
  const startValue =
    String(
      teamActivityStartAtInput?.value ||
      ""
    ).trim();

  const endValue =
    String(
      teamActivityEndAtInput?.value ||
      ""
    ).trim();

  if (
    !startValue &&
    !endValue
  ) {
    alert(
      "請先設定活動開始時間與活動結束時間"
    );
    return;
  }

  if (
    !startValue ||
    !endValue
  ) {
    alert(
      "開始時間與結束時間都要設定完整"
    );
    return;
  }

  const startAt =
    new Date(startValue).getTime();

  const endAt =
    new Date(endValue).getTime();

  if (
    !Number.isFinite(startAt) ||
    !Number.isFinite(endAt) ||
    endAt <= startAt
  ) {
    alert(
      "結束時間必須晚於開始時間"
    );
    return;
  }

  if (endAt <= Date.now()) {
    alert(
      "結束時間不能設定在現在以前"
    );
    return;
  }

  if (
    !confirm(
      "確定儲存這組預約時間嗎？\n\n" +
      "🟢 現在先開放組隊\n" +
      "▶️ 到開始時間自動進入活動中\n" +
      "🔒 只有已滿員的隊伍會鎖定\n" +
      "🟢 未滿員隊伍仍可繼續組隊\n" +
      "🏁 到結束時間自動結束活動"
    )
  ) {
    return;
  }

  if (teamActivityScheduleEnabledInput) {
    teamActivityScheduleEnabledInput.checked =
      true;
  }

  const saved =
    await saveTeamActivityAdminSettings(
      true
    );

  if (!saved) {
    return;
  }

  await adminTeamActivityAction(
    {
      action:
        "save-schedule",
      scheduleEnabled:
        true,
      startAt,
      endAt
    },
    "活動預約時間已設定 ✅"
  );
}

