async function setTeamActivityAdminPhase(
  phase
) {
  /*
    第51項：
    管理員常常填好活動內容 / 獎品後直接按
    「即時開放組隊」或「立即開始活動」。
    以前這些按鈕只切換 phase，沒有先把表單內容存進伺服器，
    所以重新 render 時尚未儲存的獎品會消失。

    現在所有狀態切換前，先自動儲存：
    - 活動名稱
    - 活動規則
    - 每隊人數
    - 獎品字幕 / 名稱 / 說明 / 圖片
  */
  const saved =
    await saveTeamActivityAdminSettings(
      true
    );

  if (!saved) {
    return;
  }

  const prompts = {
    off:
      "確定關閉活動入口嗎？\n\n現有隊伍資料不會刪除。",
    recruiting:
      "確定開放組隊嗎？\n\n會員可以建立隊伍、申請加入，隊長可以審核與踢人。",
    running:
      "確定立即開始活動嗎？\n\n🔒 只有已滿員的隊伍會鎖定。\n🟢 未滿員的隊伍仍可以繼續招募、審核與踢人，補滿本期設定人數後自動鎖隊。",
    ended:
      "確定結束活動嗎？\n\n結束後會員不能再更新流水。\n📚 本期活動、獎品、隊伍與流水成績會自動存入歷屆活動紀錄。\n🧹 封存完成後，活動名稱／規則／人數／獎品會自動恢復初始值，方便下一期直接重新設定。"
  };

  if (
    !confirm(
      prompts[phase] ||
      "確定變更活動狀態嗎？"
    )
  ) {
    return;
  }

  await adminTeamActivityAction(
    {
      action: "set-phase",
      phase
    },
    "活動狀態已更新 ✅"
  );

  await loadAdminTeamActivityRegistry();
}

async function editTeamActivityChatNotice() {
  /*
    第59項：
    不再從目前選中的組隊活動 child DO 找通知。
    直接去主聊天室找真正已發布的 activityNotice。
  */
  try {
    const getResponse =
      await fetch(
        "/api/admin/team-activity-notice?room=" +
        encodeURIComponent(room),
        {
          headers:
            authHeaders(),
          cache: "no-store"
        }
      );

    const getData =
      await getResponse.json();

    if (
      !getResponse.ok ||
      !getData.ok
    ) {
      throw new Error(
        getData.message ||
        "讀取活動通知失敗"
      );
    }

    const current =
      String(
        getData.notice?.text || ""
      );

    if (!current) {
      alert(
        "目前主聊天室裡找不到可編輯的活動通知"
      );
      return;
    }

    const next =
      prompt(
        "編輯聊天室裡已發出的活動通知：",
        current
      );

    if (next === null) {
      return;
    }

    const clean =
      String(next || "")
        .trim();

    if (!clean) {
      alert(
        "活動通知內容不能空白"
      );
      return;
    }

    const response =
      await fetch(
        "/api/admin/team-activity-notice",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              text: clean
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "編輯活動通知失敗"
      );
    }

    teamActivityAdminLastNoticeText =
      clean;

    alert(
      "聊天室活動通知已更新 ✏️"
    );

  } catch (error) {
    alert(
      error.message ||
      "編輯活動通知失敗"
    );
  }
}

