function applyRoomState(data) {
  if (!data || typeof data !== "object") {
    return;
  }

  if (data.globalMute !== undefined) {
    setGlobalMuteState(
      !!data.globalMute
    );
  }

  if (data.showOnlineCount !== undefined) {
    setOnlineVisibilityState(
      data.showOnlineCount !== false
    );
  }

  if (data.customOnlineCount !== undefined) {
    setCustomOnlineDisplayCountState(
      data.customOnlineCount
    );
  }

  if (
    data.onlineRandomEnabled !== undefined ||
    data.onlineRandomRange !== undefined
  ) {
    setOnlineRandomState(
      data.onlineRandomEnabled === true,
      data.onlineRandomRange
    );
  }

  if (data.groupMemberCount !== undefined) {
    const groupCount =
      Number(data.groupMemberCount);

    if (Number.isFinite(groupCount)) {
      latestActualGroupMemberCount =
        Math.max(
          0,
          Math.floor(groupCount)
        );
    }

    refreshClientGroupMemberCountText();

    if (isAdminLoggedIn()) {
      setAdminRoomStats(
        undefined,
        data.groupMemberCount
      );
    }
  }

  if (data.showGroupMemberCount !== undefined) {
    setGroupMemberVisibilityState(
      data.showGroupMemberCount !== false
    );
  }

  if (data.customGroupMemberCount !== undefined) {
    setCustomGroupMemberDisplayCountState(
      data.customGroupMemberCount
    );
  }

  if (data.announcement !== undefined) {
    setAnnouncementState(
      data.announcement || ""
    );
  }

  if (data.roomLocked !== undefined) {
    setRoomLockState(
      !!data.roomLocked
    );
  }

  if (data.roomTitle !== undefined) {
    setRoomTitleState(
      data.roomTitle || ""
    );
  }

  if (data.welcomeText !== undefined) {
    setWelcomeMessageState(
      data.welcomeText || ""
    );
  }

  if (data.pinnedMessages !== undefined) {
    updatePinnedMessagesState(
      data.pinnedMessages || []
    );
  }

  if (data.teamActivity !== undefined) {
    setTeamActivityRoomState(
      data.teamActivity
    );
  }
}

function requestRoomState() {
  if (
    socket &&
    socket.readyState === WebSocket.OPEN
  ) {
    try {
      socket.send(
        JSON.stringify({
          type: "sync-state"
        })
      );
    } catch {}
  }
}

function stopRoomStateSync() {
  if (roomStateSyncTimer) {
    clearTimeout(
      roomStateSyncTimer
    );

    roomStateSyncTimer = null;
  }
}

function scheduleRoomStateSync() {
  stopRoomStateSync();

  /*
    ㉗ 省電模式：
    頁面切到背景後完全停止 fallback 輪詢。
    回到前景時再立即同步一次。
    正常即時狀態仍以 WebSocket push 為主。
  */
  if (
    document.visibilityState !==
      "visible"
  ) {
    return;
  }

  roomStateSyncTimer =
    setTimeout(
      function tickRoomStateSync() {
        roomStateSyncTimer =
          null;

        if (
          document.visibilityState !==
            "visible"
        ) {
          return;
        }

        requestRoomState();

        roomStateSyncTimer =
          setTimeout(
            tickRoomStateSync,
            30000
          );
      },
      30000
    );
}

function startRoomStateSync() {
  stopRoomStateSync();

  if (
    document.visibilityState !==
      "visible"
  ) {
    return;
  }

  requestRoomState();
  scheduleRoomStateSync();
}

function authenticateAdminSocket() {
  if (!isAdminPage) return;

  const token = safeSessionGet("hd888AdminToken");

  if (!token) {
    adminSocketAuthenticated = false;
    updateGlobalMuteUI();
    return;
  }

  if (
    socket &&
    socket.readyState === WebSocket.OPEN
  ) {
    socket.send(JSON.stringify({
      type: "admin-auth",
      adminToken: token
    }));
  }
}

function setTurnstileStatus(text, mode = "") {
  turnstileStatus.textContent = text;
  turnstileStatus.classList.remove("ok", "error");

  if (mode) {
    turnstileStatus.classList.add(mode);
  }
}

/* =====================================================
   Turnstile V6.9
   不再依賴 callback 來解鎖按鈕。

   Cloudflare 官方 Form Integration 會在 form 裡建立：
   <input name="cf-turnstile-response" ...>

   客人按「進入聊天室」時，我們直接從 form 讀 token，
   再送到 Worker 的 Siteverify 驗證。
===================================================== */

function acceptTurnstileToken(token) {
  token = String(token || "").trim();

  if (!token) {
    return "";
  }

  turnstileToken = token;

  setTurnstileStatus(
    "安全驗證完成 ✅",
    "ok"
  );

  return token;
}

function getTurnstileToken() {
  let token = "";

  /* 第一優先：Cloudflare 官方 form hidden field */
  try {
    if (joinForm) {
      const formData =
        new FormData(joinForm);

      token = String(
        formData.get(
          "cf-turnstile-response"
        ) || ""
      ).trim();
    }
  } catch {}

  /* 第二層：直接抓 hidden input */
  if (!token) {
    const field =
      document.querySelector(
        'input[name="cf-turnstile-response"]'
      );

    if (field) {
      token = String(
        field.value || ""
      ).trim();
    }
  }

  /* 第三層：官方 JS API 補抓 */
  if (
    !token &&
    window.turnstile &&
    typeof window.turnstile.getResponse === "function"
  ) {
    try {
      token = String(
        window.turnstile.getResponse() || ""
      ).trim();
    } catch {}
  }

  if (token) {
    acceptTurnstileToken(
      token
    );
  }

  return token;
}

/* callback 只負責改善畫面，不再是加入聊天室的唯一依據。 */
window.hd888TurnstileSuccess =
  function (token) {
    acceptTurnstileToken(
      token
    );

    if (
      isAdminPage &&
      adminJoinStatus
    ) {
      adminJoinStatus.textContent =
        "安全驗證完成，請輸入管理員密碼後進入";
    }
  };

window.hd888TurnstileExpired =
  function () {
    turnstileToken = "";

    setTurnstileStatus(
      "安全驗證已過期，請重新驗證"
    );
  };

window.hd888TurnstileTimeout =
  function () {
    turnstileToken = "";

    setTurnstileStatus(
      "安全驗證逾時，請重新驗證",
      "error"
    );
  };

window.hd888TurnstileError =
  function (errorCode) {
    turnstileToken = "";

    setTurnstileStatus(
      "安全驗證失敗｜錯誤碼：" +
      String(errorCode || "未知"),
      "error"
    );

    return true;
  };

window.hd888TurnstileUnsupported =
  function () {
    turnstileToken = "";

    setTurnstileStatus(
      "目前瀏覽器不支援安全驗證，請改用 Chrome / Safari / Edge",
      "error"
    );
  };

function resetTurnstile() {
  turnstileToken = "";

  setTurnstileStatus(
    "請重新完成安全驗證"
  );

  try {
    if (
      window.turnstile &&
      typeof window.turnstile.reset === "function"
    ) {
      window.turnstile.reset(
        "#turnstileBox"
      );
    }
  } catch {}
}

/* 成功動畫出現後，順便定期讀 token 更新文字；就算這段沒觸發，
   按「進入聊天室」時仍會再讀一次，所以不會卡死。 */
const turnstileTokenWatcher =
  setInterval(function () {
    if (
      document.getElementById("join")
        .style.display === "none"
    ) {
      clearInterval(
        turnstileTokenWatcher
      );
      return;
    }

    const token =
      getTurnstileToken();

    if (
      isAdminPage &&
      token &&
      adminJoinStatus
    ) {
      adminJoinStatus.textContent =
        "安全驗證完成，請輸入管理員密碼後進入";
    }
  }, 1000);

setTimeout(function () {
  if (
    !window.turnstile &&
    !turnstileToken &&
    document.getElementById("join")
      .style.display !== "none"
  ) {
    setTurnstileStatus(
      "安全驗證 API 無法載入｜請關閉廣告阻擋外掛或換瀏覽器重試",
      "error"
    );
  }
}, 15000);

function makeClientId() {
  try {
    if (
      window.crypto &&
      typeof window.crypto.randomUUID === "function"
    ) {
      return window.crypto.randomUUID();
    }
  } catch {}

  try {
    if (
      window.crypto &&
      typeof window.crypto.getRandomValues === "function"
    ) {
      const bytes = new Uint8Array(16);
      window.crypto.getRandomValues(bytes);

      return Array.from(bytes)
        .map(function (value) {
          return value.toString(16).padStart(2, "0");
        })
        .join("");
    }
  } catch {}

  return (
    Date.now().toString(36) +
    "-" +
    Math.random().toString(36).slice(2) +
    "-" +
    Math.random().toString(36).slice(2)
  );
}

/*
  第57項：
  管理員與一般會員不能共用同一個 visitorId。
  舊版兩邊都讀 hd888VisitorId，同一支手機先登入管理員、
  再開客戶端時，組隊系統可能抓到管理員 WebSocket，
  於是把客戶暱稱誤判成「哪吒👺」。
*/
const visitorIdStorageKey =
  isAdminPage
    ? "hd888AdminVisitorId"
    : "hd888VisitorId";

let visitorId =
  (
    !isAdminPage
      ? firstPartyResumeState.visitorId
      : ""
  ) ||
  safeLocalGet(
    visitorIdStorageKey
  );

if (!visitorId) {
  visitorId =
    makeClientId();
}

safeLocalSet(
  visitorIdStorageKey,
  visitorId
);

const fallbackVisitor = params.get("visitor") || "";
const fallbackGrant = params.get("grant") || "";
const fallbackName = params.get("name") || "";
const fallbackAutoJoin =
  location.pathname === "/fallback-chat" &&
  fallbackVisitor &&
  fallbackGrant &&
  fallbackName;

if (fallbackVisitor) {
  visitorId = fallbackVisitor;
  safeLocalSet(
    visitorIdStorageKey,
    visitorId
  );
}

/* =====================================================
   重新打開頁面時記住原本成員身分
   - 暱稱：長期記住
   - joinGrant：依伺服器有效期使用（目前 24 小時）
   - 每個 room 分開保存，避免不同群組互相蓋掉
===================================================== */

const memberNameStorageKey =
  (
    isAdminPage
      ? "hd888AdminMemberName:"
      : "hd888MemberName:"
  ) + room;

const memberGrantStorageKey =
  (
    isAdminPage
      ? "hd888AdminMemberGrant:"
      : "hd888MemberGrant:"
  ) + room;

function savePersistentMemberSession(
  name,
  grant
) {
  const cleanName =
    String(name || "")
      .trim()
      .slice(0, 20);

  const cleanGrant =
    String(grant || "")
      .trim()
      .slice(0, 4096);

  if (cleanName) {
    safeLocalSet(
      memberNameStorageKey,
      cleanName
    );

    /* 一般成員保留舊版 key 相容；
       管理員固定名稱不寫入一般成員暱稱。 */
    if (!isAdminPage) {
      safeLocalSet(
        "hd888Nickname",
        cleanName
      );
    }
  }

  if (cleanGrant) {
    safeLocalSet(
      memberGrantStorageKey,
      cleanGrant
    );
  }

  if (!isAdminPage) {
    sendParentSessionBridge(
      "hd888-session-save",
      {
        visitorId:
          String(
            visitorId || ""
          ).slice(0, 100),

        name:
          cleanName,

        grant:
          cleanGrant
      }
    );
  }
}

function clearPersistentMemberGrant() {
  safeLocalRemove(
    memberGrantStorageKey
  );

  if (!isAdminPage) {
    sendParentSessionBridge(
      "hd888-session-clear-grant"
    );
  }
}

function clearPersistentMemberSession() {
  safeLocalRemove(
    memberNameStorageKey
  );

  safeLocalRemove(
    memberGrantStorageKey
  );

  if (!isAdminPage) {
    safeLocalRemove(
      "hd888Nickname"
    );

    sendParentSessionBridge(
      "hd888-session-clear"
    );
  }
}

if (isAdminPage) {
  try {
    const savedAdminIdentityRaw =
      safeSessionGet(
        "hd888AdminIdentity:" +
        room
      );

    if (savedAdminIdentityRaw) {
      const savedAdminIdentity =
        JSON.parse(
          savedAdminIdentityRaw
        );

      if (
        savedAdminIdentity &&
        ["owner", "staff"].includes(
          savedAdminIdentity.role
        )
      ) {
        ADMIN_FIXED_CHAT_NAME =
          formatClientAdminChatName(
            savedAdminIdentity
          );
      }
    }
  } catch {}
}

let savedMemberName =
  isAdminPage
    ? ADMIN_FIXED_CHAT_NAME
    : (
        firstPartyResumeState.name ||
        safeLocalGet(
          memberNameStorageKey
        ) ||
        safeLocalGet(
          "hd888Nickname"
        ) ||
        ""
      );

let savedMemberGrant =
  isAdminPage
    ? (
        safeLocalGet(
          memberGrantStorageKey
        ) ||
        ""
      )
    : (
        firstPartyResumeState.grant ||
        safeLocalGet(
          memberGrantStorageKey
        ) ||
        ""
      );

/*
  fragment 取回成功後，也補回 iframe localStorage，
  讓後續重連維持原本流程。
*/
if (
  !isAdminPage &&
  savedMemberName
) {
  safeLocalSet(
    memberNameStorageKey,
    savedMemberName
  );

  safeLocalSet(
    "hd888Nickname",
    savedMemberName
  );
}

if (
  !isAdminPage &&
  savedMemberGrant
) {
  safeLocalSet(
    memberGrantStorageKey,
    savedMemberGrant
  );
}

const clientFp = JSON.stringify({
  tz: Intl.DateTimeFormat().resolvedOptions().timeZone || "",
  sw: screen.width || 0,
  sh: screen.height || 0,
  cd: screen.colorDepth || 0,
  hc: navigator.hardwareConcurrency || 0,
  dm: navigator.deviceMemory || 0,
  p: navigator.platform || "",
  l: navigator.language || ""
});

function startReply(name, kind, text) {
  currentReply = {
    name: String(name || "匿名").slice(0, 20),
    kind: kind === "image" ? "image" : "text",
    text: kind === "image" ? "📷 圖片" : String(text || "").slice(0, 100)
  };

  document.getElementById("replyBar").classList.add("show");
  document.getElementById("replyBarName").textContent = "正在回覆 " + currentReply.name;
  document.getElementById("replyBarText").textContent = currentReply.text;
  messageInput.focus();
}

function clearReply() {
  currentReply = null;
  document.getElementById("replyBar").classList.remove("show");
}

const imagePreview = document.getElementById("imagePreview");
const imagePreviewImg = document.getElementById("imagePreviewImg");

function openImagePreview(src) {
  imagePreviewImg.src = src;
  imagePreview.classList.add("show");
  document.body.classList.add("preview-open");
}

function closeImagePreview() {
  imagePreview.classList.remove("show");
  imagePreviewImg.src = "";
  document.body.classList.remove("preview-open");
}

function previewBackgroundClick(event) {
  if (event.target === imagePreview) closeImagePreview();
}

function getLotteryHistoryOverlay() {
  return document.getElementById(
    "lotteryHistoryOverlay"
  );
}

function openLotteryHistory() {
  if (!isAdminLoggedIn()) {
    alert("請先登入管理員帳號");
    return;
  }

  const overlay =
    getLotteryHistoryOverlay();

  if (!overlay) {
    return;
  }

  overlay.classList.add("show");
  document.body.classList.add(
    "lottery-center-open"
  );

  loadLotteryHistory();
}

function closeLotteryHistory() {
  const overlay =
    getLotteryHistoryOverlay();

  if (!overlay) {
    return;
  }

  overlay.classList.remove("show");

  if (
    !getLotteryAdminOverlay()
      ?.classList.contains("show") &&
    !document.getElementById(
      "lotteryCenterOverlay"
    )?.classList.contains("show")
  ) {
    document.body.classList.remove(
      "lottery-center-open"
    );
  }
}

function lotteryHistoryBackgroundClick(
  event
) {
  if (
    event &&
    event.target &&
    event.target.id ===
      "lotteryHistoryOverlay"
  ) {
    closeLotteryHistory();
  }
}

function lotteryHistoryDateText(value) {
  const time =
    Number(value || 0);

  if (!time) {
    return "—";
  }

  return new Date(time)
    .toLocaleString(
      "zh-TW",
      {
        hour12: false
      }
    );
}

function renderLotteryHistory(payload) {
  lotteryHistoryItems =
    Array.isArray(payload?.histories)
      ? payload.histories
      : [];

  lotteryHistorySelected =
    payload?.selected || null;

  if (lotteryHistorySelected?.id) {
    lotteryHistorySelectedId =
      String(
        lotteryHistorySelected.id
      );
  } else if (
    lotteryHistorySelectedId &&
    !lotteryHistoryItems.some(
      item =>
        String(item?.id || "") ===
        lotteryHistorySelectedId
    )
  ) {
    lotteryHistorySelectedId = "";
  }

  const listBox =
    document.getElementById(
      "lotteryHistoryList"
    );

  const detailBox =
    document.getElementById(
      "lotteryHistoryDetail"
    );

  if (listBox) {
    if (!lotteryHistoryItems.length) {
      listBox.innerHTML =
        '<div class="lottery-history-empty">目前還沒有歷屆抽獎紀錄。</div>';
    } else {
      listBox.innerHTML =
        '<div class="lottery-history-count">📚 共 ' +
          lotteryHistoryItems.length +
          ' 筆紀錄</div>' +
        '<div class="lottery-history-list">' +
          lotteryHistoryItems.map(
            item => {
              const selected =
                String(item.id || "") ===
                lotteryHistorySelectedId;

              const mainTime =
                item.drawnAt ||
                item.archivedAt ||
                item.clearedAt ||
                item.createdAt;

              const claimedCount =
                (
                  Array.isArray(
                    item.currentWinners
                  )
                    ? item.currentWinners
                    : []
                ).filter(
                  winner =>
                    winner?.claimed === true
                ).length;

              return (
                '<button type="button" class="lottery-history-card ' +
                  (selected ? 'selected' : '') +
                  '" onclick="selectLotteryHistory(\'' +
                  String(item.id || "") +
                  '\')">' +
                  '<div class="lottery-history-card-top">' +
                    '<strong>' +
                      lotteryEscapeText(
                        item.title || "抽獎活動"
                      ) +
                    '</strong>' +
                    '<span>' +
                      (
                        item.archiveStatus === "drawn"
                          ? '🎉 已抽獎'
                          : '🗃 已封存'
                      ) +
                    '</span>' +
                  '</div>' +
                  '<div class="lottery-history-card-meta">' +
                    '<span>🎁 ' +
                      lotteryEscapeText(
                        item.prize || ""
                      ) +
                    '</span>' +
                    '<span>👥 ' +
                      Number(
                        item.registrationCount || 0
                      ) +
                      ' 人</span>' +
                    '<span>🏆 ' +
                      Number(
                        item.currentWinners?.length || 0
                      ) +
                      ' 人</span>' +
                    (
                      item.currentWinners?.length
                        ? '<span>✅ ' +
                          claimedCount +
                          '/' +
                          item.currentWinners.length +
                          ' 已領</span>'
                        : ''
                    ) +
                  '</div>' +
                  '<small>' +
                    lotteryEscapeText(
                      lotteryHistoryDateText(
                        mainTime
                      )
                    ) +
                  '</small>' +
                '</button>'
              );
            }
          ).join('') +
        '</div>';
    }
  }

  if (!detailBox) {
    return;
  }

  const history =
    lotteryHistorySelected;

  if (!history?.id) {
    detailBox.innerHTML =
      '<div class="lottery-history-empty">選擇一筆紀錄查看完整內容。</div>';
    return;
  }

  const registrations =
    Array.isArray(
      history.registrations
    )
      ? history.registrations
      : [];

  const winners =
    Array.isArray(
      history.currentWinners
    )
      ? history.currentWinners
      : [];

  const redrawEvents =
    (
      Array.isArray(history.drawHistory)
        ? history.drawHistory
        : []
    ).filter(
      item =>
        item?.type === "redraw"
    );

  const rulesHtml =
    history.rules
      ? '<div class="lottery-history-rules"><strong>📋 活動規則</strong><div>' +
        lotteryEscapeText(
          history.rules
        ).replace(/\n/g, '<br>') +
        '</div></div>'
      : '';

  const winnerHtml =
    winners.length
      ? (
          '<section class="lottery-history-section">' +
            '<div class="lottery-history-section-title">🏆 最終中獎名單</div>' +
            '<div class="lottery-history-winner-list">' +
              winners.map(
                (item, index) => {
                  const claimed =
                    item?.claimed === true;

                  return (
                    '<div class="lottery-history-winner-row">' +
                      '<span class="lottery-history-rank">' +
                        (index + 1) +
                      '</span>' +
                      '<div class="lottery-history-winner-main">' +
                        '<strong>' +
                          lotteryEscapeText(
                            item.nickname || "成員"
                          ) +
                        '</strong>' +
                        '<span>帳號：' +
                          lotteryEscapeText(
                            item.account || ""
                          ) +
                        '</span>' +
                        '<small>第 ' +
                          Number(item.number || 1) +
                          ' 位登記' +
                          (
                            item.drawRound > 1
                              ? '｜第 ' +
                                Number(item.drawRound) +
                                ' 輪中獎'
                              : ''
                          ) +
                        '</small>' +
                      '</div>' +
                      '<div class="lottery-history-winner-actions">' +
                        '<button type="button" class="lottery-history-claim-btn ' +
                          (claimed ? 'claimed' : '') +
                          '" onclick="setLotteryWinnerClaimed(\'' +
                          String(item.winnerId || "") +
                          '\',' +
                          (claimed ? 'false' : 'true') +
                          ')">' +
                          (claimed ? '✅ 已領獎' : '📦 標記已領') +
                        '</button>' +
                        '<button type="button" class="lottery-history-redraw-btn" ' +
                          (claimed ? 'disabled title="已領獎者不可直接重抽"' : '') +
                          ' onclick="redrawLotteryWinner(\'' +
                          String(item.winnerId || "") +
                          '\')">🔄 重抽</button>' +
                      '</div>' +
                    '</div>'
                  );
                }
              ).join('') +
            '</div>' +
          '</section>'
        )
      : (
          '<section class="lottery-history-section">' +
            '<div class="lottery-history-section-title">🏆 中獎結果</div>' +
            '<div class="lottery-history-empty">這場活動沒有完成抽獎。</div>' +
          '</section>'
        );

  const redrawHtml =
    redrawEvents.length
      ? (
          '<section class="lottery-history-section">' +
            '<div class="lottery-history-section-title">🔄 重抽紀錄（' +
              redrawEvents.length +
              '）</div>' +
            '<div class="lottery-history-redraw-list">' +
              redrawEvents.map(
                (event, index) =>
                  '<div class="lottery-history-redraw-row">' +
                    '<strong>第 ' +
                      (index + 1) +
                      ' 次重抽</strong>' +
                    '<span>' +
                      lotteryEscapeText(
                        event?.replacedWinner?.nickname || "成員"
                      ) +
                      ' → ' +
                      lotteryEscapeText(
                        event?.winner?.nickname || "成員"
                      ) +
                    '</span>' +
                    '<small>' +
                      lotteryEscapeText(
                        lotteryHistoryDateText(
                          event?.time
                        )
                      ) +
                    '</small>' +
                  '</div>'
              ).join('') +
            '</div>' +
          '</section>'
        )
      : '';

  const registrationHtml =
    '<section class="lottery-history-section">' +
      '<div class="lottery-history-section-title">👥 完整報名名單（' +
        registrations.length +
        '）</div>' +
      (
        registrations.length
          ? '<div class="lottery-history-registration-list">' +
            registrations.map(
              item => {
                const time =
                  lotteryHistoryDateText(
                    item.registeredAt
                  );

                return (
                  '<div class="lottery-history-registration-row">' +
                    '<b>#' +
                      Number(item.number || 0) +
                    '</b>' +
                    '<div>' +
                      '<strong>' +
                        lotteryEscapeText(
                          item.nickname || "成員"
                        ) +
                      '</strong>' +
                      '<span>帳號：' +
                        lotteryEscapeText(
                          item.account || ""
                        ) +
                      '</span>' +
                      '<small>' +
                        lotteryEscapeText(time) +
                      '</small>' +
                    '</div>' +
                    (
                      item.suspectedDuplicateDevice
                        ? '<em>⚠️ 疑似同裝置</em>'
                        : ''
                    ) +
                  '</div>'
                );
              }
            ).join('') +
            '</div>'
          : '<div class="lottery-history-empty">這場沒有報名成員。</div>'
      ) +
    '</section>';

  detailBox.innerHTML =
    '<div class="lottery-history-detail-head">' +
      '<div>' +
        '<span class="lottery-history-status">' +
          (
            history.archiveStatus === "drawn"
              ? '🎉 已完成抽獎'
              : '🗃 已封存未抽獎'
          ) +
        '</span>' +
        '<h3>' +
          lotteryEscapeText(
            history.title || "抽獎活動"
          ) +
        '</h3>' +
        '<p>🎁 ' +
          lotteryEscapeText(
            history.prize || ""
          ) +
        '</p>' +
      '</div>' +
      '<div class="lottery-history-detail-stats">' +
        '<span>👥 ' +
          Number(
            history.registrationCount ||
            registrations.length
          ) +
          ' 人</span>' +
        '<span>🏆 ' +
          winners.length +
          ' 人</span>' +
      '</div>' +
    '</div>' +
    '<div class="lottery-history-times">' +
      '<span>建立：' +
        lotteryEscapeText(
          lotteryHistoryDateText(
            history.createdAt
          )
        ) +
      '</span>' +
      (
        history.drawnAt
          ? '<span>抽獎：' +
            lotteryEscapeText(
              lotteryHistoryDateText(
                history.drawnAt
              )
            ) +
            '</span>'
          : ''
      ) +
      (
        history.clearedAt
          ? '<span>清除：' +
            lotteryEscapeText(
              lotteryHistoryDateText(
                history.clearedAt
              )
            ) +
            '</span>'
          : ''
      ) +
    '</div>' +
    rulesHtml +
    winnerHtml +
    redrawHtml +
    registrationHtml;
}

async function selectLotteryHistory(
  activityId
) {
  lotteryHistorySelectedId =
    String(activityId || "");

  await loadLotteryHistory();
}

async function loadLotteryHistory() {
  if (lotteryHistoryLoading) {
    return;
  }

  lotteryHistoryLoading = true;

  const detailBox =
    document.getElementById(
      "lotteryHistoryDetail"
    );

  if (detailBox) {
    detailBox.innerHTML =
      '<div class="lottery-history-empty">紀錄讀取中…</div>';
  }

  try {
    let endpoint =
      "/api/admin/lottery-history?room=" +
      encodeURIComponent(room);

    if (lotteryHistorySelectedId) {
      endpoint +=
        "&activityId=" +
        encodeURIComponent(
          lotteryHistorySelectedId
        );
    }

    const response =
      await fetch(
        endpoint,
        {
          headers:
            authHeaders(),
          cache: "no-store"
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "讀取抽獎紀錄失敗"
      );
    }

    renderLotteryHistory(data);

  } catch (error) {
    if (detailBox) {
      detailBox.innerHTML =
        '<div class="lottery-history-empty">' +
          lotteryEscapeText(
            error.message ||
            "讀取失敗"
          ) +
        '</div>';
    }
  } finally {
    lotteryHistoryLoading = false;
  }
}

async function lotteryHistoryAction(
  payload,
  successMessage = ""
) {
  try {
    const response =
      await fetch(
        "/api/admin/lottery-history/action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              activityId:
                lotteryHistorySelectedId,
              ...payload
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "抽獎紀錄操作失敗"
      );
    }

    renderLotteryHistory(data);

    if (successMessage) {
      alert(successMessage);
    }

    return true;

  } catch (error) {
    alert(
      error.message ||
      "抽獎紀錄操作失敗"
    );

    return false;
  }
}

async function setLotteryWinnerClaimed(
  winnerId,
  claimed
) {
  const ok =
    await lotteryHistoryAction(
      {
        action: "set-claimed",
        winnerId,
        claimed: claimed === true
      },
      claimed
        ? "已標記為已領獎 ✅"
        : "已取消領獎標記"
    );

  if (ok) {
    await loadLotteryAdmin();
  }
}

async function redrawLotteryWinner(
  winnerId
) {
  const winner =
    (
      Array.isArray(
        lotteryHistorySelected
          ?.currentWinners
      )
        ? lotteryHistorySelected
            .currentWinners
        : []
    ).find(
      item =>
        String(item?.winnerId || "") ===
        String(winnerId || "")
    );

  if (!winner) {
    alert("找不到這位中獎者");
    return;
  }

  if (winner.claimed) {
    alert("已領獎者不能直接重抽，請先取消領獎標記");
    return;
  }

  if (
    !confirm(
      "確定要取消「" +
      String(
        winner.nickname || "這位中獎者"
      ) +
      "」的中獎資格並重新抽一位嗎？\n\n原中獎者不會再次被抽中，重抽結果會保留在紀錄並公布到聊天室。"
    )
  ) {
    return;
  }

  const ok =
    await lotteryHistoryAction(
      {
        action: "redraw",
        winnerId
      },
      "重抽完成，結果已保存並公布到聊天室 🔄"
    );

  if (ok) {
    lotterySelectedActivityId =
      lotteryHistorySelectedId;

    lotteryAdminSelectedId =
      lotteryHistorySelectedId;

    await loadLotteryAdmin();
    await loadLotteryState(true);
  }
}

