/*
  首次加入聊天室完全交給原生 HTML form：
  Turnstile token 直接 POST 到 /join-fallback，由 Worker 伺服器驗證。
  不再用 JavaScript 攔截加入按鈕，避免按鈕無反應。
*/

messageInput.addEventListener(
  "input",
  handleMentionInput
);

messageInput.addEventListener(
  "click",
  handleMentionInput
);

messageInput.addEventListener(
  "keyup",
  function(event) {
    if (
      event.key !== "ArrowDown" &&
      event.key !== "ArrowUp" &&
      event.key !== "Enter" &&
      event.key !== "Tab" &&
      event.key !== "Escape"
    ) {
      handleMentionInput();
    }
  }
);

/* =====================================================
   ENTER 送出訊息：穩定版
   - 用 capture 階段攔截，避免管理員介面其他事件吃掉 Enter
   - 中文輸入法組字中不送出
   - @ 提及選單開啟時，Enter 只負責選擇提及對象
===================================================== */
document.addEventListener(
  "keydown",
  function(event) {
    if (
      event.target !== messageInput ||
      event.key !== "Enter"
    ) {
      return;
    }

    if (
      event.isComposing ||
      event.keyCode === 229
    ) {
      return;
    }

    if (
      event.shiftKey ||
      event.ctrlKey ||
      event.altKey ||
      event.metaKey
    ) {
      return;
    }

    if (handleMentionKeydown(event)) {
      event.stopImmediatePropagation();
      return;
    }

    event.preventDefault();
    event.stopImmediatePropagation();

    sendMessage();
  },
  true
);

