function addMessage(
  name,
  text,
  time,
  replyTo,
  messageId,
  isAdmin = false,
  mentionAll = false,
  reactions = null,
  myReactions = null,
  linkPreview = null
) {
  rememberMentionName(name);
  ensureDateSeparator(time);

  const mentionedMe =
    !!mentionAll ||
    doesMessageMentionMe(
      text
    );

  const box = document.createElement("div");

  const isMine =
    normalizeMentionName(name) ===
    normalizeMentionName(
      currentChatName
    );

  box.className =
    [
      "message",
      isMine
        ? "my-message"
        : "",
      isAdmin
        ? "admin-message"
        : "",
      mentionAll
        ? "mention-all-message"
        : (
            mentionedMe
              ? "mention-me-message"
              : ""
          )
    ]
      .filter(Boolean)
      .join(" ");

  if (messageId) box.dataset.messageId = messageId;

  box.dataset.searchText =
    buildMessageSearchText(
      name,
      text,
      replyTo,
      "text"
    );

  box.appendChild(
    createMessageHead(
      name,
      time,
      isAdmin,
      mentionedMe,
      mentionAll
    )
  );

  const reply = createReplyQuote(replyTo);
  if (reply) box.appendChild(reply);

  const body =
    document.createElement(
      "div"
    );

  body.className =
    "message-text";

  if (isAdmin) {
    makeClickableAdminMessage(
      body,
      text
    );
  } else {
    body.textContent =
      text;
  }

  box.appendChild(body);

  if (
    isAdmin &&
    linkPreview
  ) {
    const previewCard =
      createAdminLinkPreviewCard(
        linkPreview
      );

    if (previewCard) {
      box.appendChild(
        previewCard
      );
    }
  }

  box.appendChild(
    createReactionBar(
      messageId,
      reactions,
      myReactions
    )
  );

  box.appendChild(
    createMessageActions(
      name,
      "text",
      text,
      messageId,
      isAdmin
    )
  );

  bindMessageLongPress(box);
  document.getElementById("messages").appendChild(box);

  registerMentionRecord({
    name,
    text,
    time,
    messageId,
    mentionAll
  });

  if (messageSearchQuery) {
    applyMessageSearch();
  }
}

