function updateMessageTextById(
  messageId,
  text
) {
  if (!messageId) {
    return;
  }

  const boxes =
    document.querySelectorAll(
      ".message[data-message-id]"
    );

  boxes.forEach(
    function(box) {
      if (
        box.dataset.messageId !==
          messageId
      ) {
        return;
      }

      const body =
        box.querySelector(
          ".message-text"
        );

      if (!body) {
        return;
      }

      if (
        box.classList.contains(
          "admin-message"
        )
      ) {
        makeClickableAdminMessage(
          body,
          String(text || "")
        );
      } else {
        body.textContent =
          String(text || "");
      }

      box.dataset.searchText =
        (
          box.dataset.searchText ||
          ""
        ) +
        " " +
        String(text || "");
    }
  );

  if (messageSearchQuery) {
    applyMessageSearch();
  }
}

function removeMessageById(messageId) {
  if (!messageId) return;

  removeMentionRecord(
    messageId
  );

  if (
    isMessagePinned(
      messageId
    )
  ) {
    updatePinnedMessagesState(
      pinnedMessages.filter(
        item =>
          item.messageId !==
          messageId
      )
    );
  }

  const messages =
    document.querySelectorAll(
      ".message[data-message-id]"
    );

  messages.forEach(
    function(box) {
      if (
        box.dataset.messageId ===
        messageId
      ) {
        box.remove();
      }
    }
  );

  cleanupDateSeparators();
}

function addSystem(text) {
  const box = document.createElement("div");
  box.className = "system";
  box.textContent = text;
  document.getElementById("messages").appendChild(box);
}

function isMessagesNearBottom() {
  const box =
    document.getElementById("messages");

  if (!box) {
    return true;
  }

  const distance =
    box.scrollHeight -
    box.scrollTop -
    box.clientHeight;

  return distance <= 90;
}

function updateNewMessageButton() {
  if (!newMessageButton) {
    return;
  }

  if (
    unreadMessageCount > 0 &&
    !userIsNearBottom &&
    !messageSearchQuery
  ) {
    newMessageButton.textContent =
      "↓ " +
      unreadMessageCount +
      " 則新訊息";

    newMessageButton.classList.add(
      "show"
    );
  } else {
    newMessageButton.classList.remove(
      "show"
    );
  }
}

function markMessagesRead() {
  unreadMessageCount = 0;
  updateNewMessageButton();
}

function handleMessagesScroll() {
  userIsNearBottom =
    isMessagesNearBottom();

  if (userIsNearBottom) {
    markMessagesRead();
  } else {
    updateNewMessageButton();
  }
}

function jumpToNewestMessages() {
  const box =
    document.getElementById("messages");

  if (!box) {
    return;
  }

  box.scrollTo({
    top: box.scrollHeight,
    behavior: "smooth"
  });

  userIsNearBottom = true;
  markMessagesRead();
}

function handleIncomingMessageForUnread() {
  if (messageSearchQuery) {
    return;
  }

  if (userIsNearBottom) {
    scrollBottom();
    return;
  }

  unreadMessageCount++;
  updateNewMessageButton();
}

function scrollBottom() {
  const box = document.getElementById("messages");
  box.scrollTop = box.scrollHeight;
  userIsNearBottom = true;
  markMessagesRead();
}

function normalizeLinkCheckTextClient(
  value
) {
  return String(value || "")
    .normalize("NFKC")
    .replace(
      /[\u200B-\u200D\u2060\uFEFF\u00AD]/g,
      ""
    )
    .replace(
      /[。．｡]/g,
      "."
    )
    .trim();
}

function containsBlockedLinkClient(
  value
) {
  const text =
    normalizeLinkCheckTextClient(
      value
    );

  if (!text) {
    return false;
  }

  if (
    /(?:https?|ftp)\s*:\s*\/\s*\//i.test(
      text
    )
  ) {
    return true;
  }

  if (
    /(?:^|[^a-z0-9@])www\s*\.\s*[a-z0-9-]+/i.test(
      text
    )
  ) {
    return true;
  }

  if (
    /(?:^|[^a-z0-9@])(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}(?=$|[^a-z0-9])/i.test(
      text
    )
  ) {
    return true;
  }

  if (
    /(?:^|[^0-9])(?:\d{1,3}\.){3}\d{1,3}(?=$|[\s/:?#])/i.test(
      text
    )
  ) {
    return true;
  }

  return false;
}

function makeClientMessageNonce() {
  try {
    if (
      crypto &&
      typeof crypto.randomUUID ===
        "function"
    ) {
      return (
        "m_" +
        crypto.randomUUID()
      );
    }
  } catch {}

  return (
    "m_" +
    Date.now().toString(36) +
    "_" +
    Math.random()
      .toString(36)
      .slice(2, 10)
  );
}

function sendMessage() {
  const text =
    messageInput.value.trim();

  if (!text) return;

  if (
    !isAdminLoggedIn() &&
    containsBlockedLinkClient(
      text
    )
  ) {
    alert(
      "一般成員禁止傳送連結，只有管理員可以傳送 🔒"
    );

    messageInput.focus();
    return;
  }

  if (
    globalMuteEnabled &&
    !canCurrentUserSpeak()
  ) {
    alert(
      "目前為全體禁言模式，只有管理員可以發言"
    );
    return;
  }

  if (
    !socket ||
    socket.readyState !==
      WebSocket.OPEN
  ) {
    alert(
      "正在重新連線，等一下再傳"
    );
    scheduleReconnect(true);
    return;
  }

  const clientNonce =
    makeClientMessageNonce();

  const replySnapshot =
    currentReply
      ? {
          ...currentReply
        }
      : null;

  const optimisticId =
    "pending:" +
    clientNonce;

  /*
    一般文字仍可先顯示 pending 訊息；
    但「管理員傳網址」會由 Worker 建立連結預覽後再回傳一次正式訊息。
    如果網址也先畫 pending，就會出現：
      1. 純網址
      2. 正式網址 + 預覽卡
    看起來像重複兩次。

    所以管理員網址訊息改成「只等 Worker 正式回傳」。
  */
  /*
    網址訊息一律不先畫 pending。
    原因：管理員網址會由 Worker 做完預覽後回傳正式訊息，
    若前端此時尚未完成 admin-auth，舊版會誤判成一般文字，
    先畫一份純網址，之後又收到一份「網址 + 預覽卡」。
  */
  const isLinkMessage =
    containsBlockedLinkClient(
      text
    );

  let pendingBox =
    null;

  /*
    只顯示 Worker 正式回傳的訊息。
    客戶端 / 管理端都不再先本機畫一份，
    避免同一句訊息出現兩遍。
  */
  if (false) {
    addMessage(
      currentChatName || "管理員",
      text,
      Date.now(),
      replySnapshot,
      optimisticId,
      !!(
        adminSocketAuthenticated ||
        isAdminLoggedIn()
      ),
      false,
      {
        "😍": 0,
        "❤️": 0,
        "😂": 0
      },
      [],
      null
    );

    pendingBox =
      document.querySelector(
        '[data-message-id="' +
        optimisticId +
        '"]'
      );

    if (pendingBox) {
      pendingBox.classList.add(
        "pending-message"
      );
    }

    scrollBottom();
  }

  try {
    socket.send(
      JSON.stringify({
        type: "message",
        text,
        replyTo:
          replySnapshot,
        clientNonce
      })
    );
  } catch {
    if (pendingBox) {
      pendingBox.remove();
    }

    alert(
      "訊息傳送失敗，請再試一次"
    );

    scheduleReconnect(true);
    return;
  }

  messageInput.value = "";
  closeMentionSuggestions();
  clearReply();
  messageInput.focus();
}

async function adminLoginBeforeLockedJoin() {
  const usernameInput =
    prompt(
      "房間目前已鎖定。\n\n一般管理員請輸入「管理員帳號」：\n主管理員可直接留空。"
    );

  if (usernameInput === null) {
    return false;
  }

  const password =
    prompt(
      "請輸入管理員密碼："
    );

  if (!password) {
    return false;
  }

  try {
    const response =
      await fetch(
        "/api/admin/login",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body:
            JSON.stringify({
              room,
              username:
                String(
                  usernameInput || ""
                ).trim(),
              password
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.token
    ) {
      alert(
        data.message ||
        "管理員登入失敗"
      );

      return false;
    }

    safeSessionSet(
      "hd888AdminToken",
      data.token
    );

    setCurrentAdminIdentity(
      data.admin || null
    );

    return true;

  } catch {
    alert(
      "管理員登入失敗，請稍後再試"
    );

    return false;
  }
}

function adminIdentityStorageKey() {
  return (
    "hd888AdminIdentity:" +
    room
  );
}

function setCurrentAdminIdentity(
  identity
) {
  if (
    !identity ||
    !["owner", "staff"].includes(
      identity.role
    )
  ) {
    currentAdminIdentity =
      null;

    safeSessionRemove(
      adminIdentityStorageKey()
    );

    applyAdminRoleUI();
    return;
  }

  const adminChatName =
    formatClientAdminChatName(
      identity
    );

  currentAdminIdentity = {
    name:
      adminChatName,

    role:
      identity.role,

    room:
      String(
        identity.room ||
        room
      )
  };

  ADMIN_FIXED_CHAT_NAME =
    adminChatName;

  currentChatName =
    adminChatName;

  savedMemberName =
    adminChatName;

  if (nickname) {
    nickname.value =
      adminChatName;
  }

  const fixedNameValue =
    document.getElementById(
      "adminFixedNicknameValue"
    ) ||
    document.querySelector(
      "#adminFixedNicknameDisplay strong"
    );

  if (fixedNameValue) {
    fixedNameValue.textContent =
      adminChatName;
  }

  updateMessageInputPlaceholder();

  safeSessionSet(
    adminIdentityStorageKey(),
    JSON.stringify(
      currentAdminIdentity
    )
  );

  applyAdminRoleUI();
}

function restoreCurrentAdminIdentity() {
  const raw =
    safeSessionGet(
      adminIdentityStorageKey()
    );

  if (!raw) {
    return null;
  }

  try {
    const parsed =
      JSON.parse(raw);

    if (
      parsed &&
      ["owner", "staff"].includes(
        parsed.role
      )
    ) {
      setCurrentAdminIdentity(
        parsed
      );

      return currentAdminIdentity;
    }
  } catch {}

  return null;
}

function isOwnerAdmin() {
  return !!(
    currentAdminIdentity &&
    currentAdminIdentity.role ===
      "owner"
  );
}

function applyAdminRoleUI() {
  const owner =
    isOwnerAdmin();

  document.body.classList.toggle(
    "admin-owner",
    owner
  );

  document
    .querySelectorAll(
      "[data-owner-only='1']"
    )
    .forEach(
      function(element) {
        element.style.display =
          owner
            ? ""
            : "none";
      }
    );

  if (adminIdentityInfo) {
    if (
      !currentAdminIdentity
    ) {
      adminIdentityInfo.textContent =
        "";
    } else {
      adminIdentityInfo.textContent =
        "登入：" +
        currentAdminIdentity.name +
        (
          owner
            ? "（主管理員）"
            : "（一般管理員）"
        );
    }
  }

  const badge =
    document.getElementById(
      "adminBadge"
    );

  if (badge) {
    badge.textContent =
      "👑 官方管理員";
  }

  if (
    !owner &&
    (
      adminPanelMode === "logs" ||
      adminPanelMode === "admins"
    )
  ) {
    showMembersPanel();
  }

  applyOnlineCountVisibility();
  applyGroupMemberCountVisibility();
}

function clearAdminLoginState() {
  safeSessionRemove(
    "hd888AdminToken"
  );

  safeSessionRemove(
    adminIdentityStorageKey()
  );

  currentAdminIdentity =
    null;

  adminSocketAuthenticated =
    false;

  if (memberTimer) {
    clearInterval(
      memberTimer
    );

    memberTimer =
      null;
  }

  document.body.classList.remove(
    "admin-mode",
    "admin-owner"
  );

  const loginButton =
    document.getElementById(
      "adminLogin"
    );

  const badge =
    document.getElementById(
      "adminBadge"
    );

  const panel =
    document.getElementById(
      "adminPanel"
    );

  if (loginButton) {
    loginButton.style.display =
      "";
  }

  if (badge) {
    badge.style.display =
      "none";
  }

  if (panel) {
    panel.style.setProperty(
      "display",
      "none",
      "important"
    );
  }

  closeAdminPanelDrawer();

  updateGlobalMuteUI();
  applyOnlineCountVisibility();
  applyGroupMemberCountVisibility();
}

function adminLogin() {
  if (!adminLoginOverlay) {
    alert(
      "管理員登入視窗載入失敗，請重新整理頁面後再試"
    );
    return;
  }

  adminLoginAccount.value =
    "";

  adminLoginPassword.value =
    "";

  adminLoginOverlay.classList.add(
    "show"
  );

  document.body.classList.add(
    "admin-login-open"
  );

  setTimeout(
    function() {
      adminLoginAccount.focus();
    },
    0
  );
}

function closeAdminLoginModal() {
  if (!adminLoginOverlay) {
    return;
  }

  /*
    使用者若手動關閉登入視窗，
    下次按「進入聊天室」再重新觸發登入即可。
  */
  if (
    isAdminPage &&
    !getAdminToken()
  ) {
    adminJoinPending =
      false;

    adminAutoEntryRunning =
      false;
  }

  adminLoginOverlay.classList.remove(
    "show"
  );

  document.body.classList.remove(
    "admin-login-open"
  );

  adminLoginPassword.value =
    "";
}

function adminLoginBackgroundClick(
  event
) {
  if (
    event.target ===
    adminLoginOverlay
  ) {
    closeAdminLoginModal();
  }
}

async function submitAdminLogin(
  event
) {
  if (event) {
    event.preventDefault();
  }

  const username =
    String(
      adminLoginAccount.value ||
      ""
    )
      .trim()
      .slice(0, 20);

  const password =
    String(
      adminLoginPassword.value ||
      ""
    );

  if (!password) {
    alert(
      "請輸入管理員密碼"
    );

    adminLoginPassword.focus();
    return;
  }

  adminLoginSubmitButton.disabled =
    true;

  adminLoginSubmitButton.textContent =
    "登入中…";

  try {
    const response =
      await fetch(
        "/api/admin/login",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json"
          },
          body:
            JSON.stringify({
              room,
              username,
              persona:
                (
                  currentAdminIdentity &&
                  String(
                    currentAdminIdentity.name ||
                    ""
                  ).includes("芯瑤")
                )
                  ? "xinyao"
                  : (
                      currentAdminIdentity &&
                      String(
                        currentAdminIdentity.name ||
                        ""
                      ).includes("哪吒")
                    )
                      ? "nezha"
                      : "",
              password
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.token
    ) {
      alert(
        data.message ||
        "登入失敗"
      );
      return;
    }

    safeSessionSet(
      "hd888AdminToken",
      data.token
    );

    setCurrentAdminIdentity(
      data.admin || null
    );

    const continueAdminJoin =
      adminJoinPending &&
      isAdminPage &&
      document
        .getElementById(
          "join"
        )
        .style.display !==
          "none";

    adminJoinPending =
      false;

    closeAdminLoginModal();

    showAdmin(
      data.admin || null
    );

    if (continueAdminJoin) {
      currentChatName =
        ADMIN_FIXED_CHAT_NAME;

      nickname.value =
        ADMIN_FIXED_CHAT_NAME;

      updateMessageInputPlaceholder();

      /*
        登入已完成，允許這一次真正加入聊天室。
      */
      adminAutoEntryRunning =
        false;

      await startAdminAutoEntry();
    }

  } catch {
    alert(
      "管理員登入失敗，請稍後再試"
    );

  } finally {
    adminLoginSubmitButton.disabled =
      false;

    adminLoginSubmitButton.textContent =
      "登入";
  }
}

async function checkAdminLogin() {
  const token =
    safeSessionGet(
      "hd888AdminToken"
    );

  if (!token) {
    return;
  }

  restoreCurrentAdminIdentity();

  try {
    const response =
      await fetch(
        "/api/admin/check",
        {
          method: "POST",
          headers: {
            "Authorization":
              "Bearer " +
              token,
            "Content-Type":
              "application/json"
          },
          body:
            JSON.stringify({
              room
            })
        }
      );

    const data =
      await response.json();

    if (
      data.ok &&
      data.admin
    ) {
      setCurrentAdminIdentity(
        data.admin
      );

      showAdmin(
        data.admin
      );
    } else {
      clearAdminLoginState();
    }

  } catch {}
}

function isAdminLoggedIn() {
  return !!safeSessionGet(
    "hd888AdminToken"
  );
}

function authHeaders() {
  return {
    "Authorization":
      "Bearer " +
      safeSessionGet(
        "hd888AdminToken"
      )
  };
}

/* =====================================================
   管理後台 Drawer｜Worker 內建版
   -----------------------------------------------------
   不再依賴 GitHub ui.js。
   平常 adminPanel 完全 display:none，不佔聊天室高度。
   點右上「👑 官方管理員」才以固定彈窗開啟。
===================================================== */
let adminDrawerInstalled =
  false;

function forceAdminPanelHidden() {
  const panel =
    document.getElementById(
      "adminPanel"
    );

  if (!panel) return;

  panel.style.setProperty(
    "display",
    "none",
    "important"
  );

  panel.style.removeProperty(
    "position"
  );

  document.body.classList.remove(
    "admin-drawer-open"
  );

  const overlay =
    document.getElementById(
      "adminDrawerOverlay"
    );

  if (overlay) {
    overlay.style.setProperty(
      "display",
      "none",
      "important"
    );
  }

  const badge =
    document.getElementById(
      "adminBadge"
    );

  if (badge) {
    badge.setAttribute(
      "aria-expanded",
      "false"
    );
  }
}

function openAdminPanelDrawer() {
  const panel =
    document.getElementById(
      "adminPanel"
    );

  if (!panel) return;

  installAdminPanelDrawer();

  panel.style.setProperty(
    "display",
    "block",
    "important"
  );

  panel.style.setProperty(
    "position",
    "fixed",
    "important"
  );

  panel.style.setProperty(
    "z-index",
    "2147482500",
    "important"
  );

  panel.style.setProperty(
    "top",
    "64px",
    "important"
  );

  panel.style.setProperty(
    "left",
    "50%",
    "important"
  );

  panel.style.setProperty(
    "right",
    "auto",
    "important"
  );

  panel.style.setProperty(
    "bottom",
    "auto",
    "important"
  );

  panel.style.setProperty(
    "transform",
    "translateX(-50%)",
    "important"
  );

  panel.style.setProperty(
    "width",
    "min(720px, calc(100vw - 14px))",
    "important"
  );

  panel.style.setProperty(
    "max-width",
    "720px",
    "important"
  );

  panel.style.setProperty(
    "height",
    "auto",
    "important"
  );

  panel.style.setProperty(
    "max-height",
    "calc(100dvh - 76px)",
    "important"
  );

  panel.style.setProperty(
    "margin",
    "0",
    "important"
  );

  panel.style.setProperty(
    "padding",
    "12px",
    "important"
  );

  panel.style.setProperty(
    "overflow-y",
    "auto",
    "important"
  );

  panel.style.setProperty(
    "overflow-x",
    "hidden",
    "important"
  );

  panel.style.setProperty(
    "-webkit-overflow-scrolling",
    "touch",
    "important"
  );

  panel.style.setProperty(
    "overscroll-behavior",
    "contain",
    "important"
  );

  panel.style.setProperty(
    "touch-action",
    "pan-y",
    "important"
  );

  panel.style.setProperty(
    "border-radius",
    "16px",
    "important"
  );

  panel.style.setProperty(
    "box-shadow",
    "0 24px 60px rgba(0,0,0,.32)",
    "important"
  );

  const overlay =
    document.getElementById(
      "adminDrawerOverlay"
    );

  if (overlay) {
    overlay.style.setProperty(
      "display",
      "block",
      "important"
    );
  }

  document.body.classList.add(
    "admin-drawer-open"
  );

  const badge =
    document.getElementById(
      "adminBadge"
    );

  if (badge) {
    badge.setAttribute(
      "aria-expanded",
      "true"
    );
  }

  panel.scrollTop = 0;
}

function closeAdminPanelDrawer() {
  forceAdminPanelHidden();
}

function toggleAdminPanelDrawer(
  event
) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }

  const panel =
    document.getElementById(
      "adminPanel"
    );

  if (!panel) return;

  const open =
    panel.style.getPropertyValue(
      "display"
    ) === "block";

  if (open) {
    closeAdminPanelDrawer();
  } else {
    openAdminPanelDrawer();
  }
}

function installAdminPanelDrawer() {
  if (adminDrawerInstalled) {
    return;
  }

  const panel =
    document.getElementById(
      "adminPanel"
    );

  const badge =
    document.getElementById(
      "adminBadge"
    );

  if (
    !panel ||
    !badge
  ) {
    return;
  }

  adminDrawerInstalled =
    true;

  /* 背景遮罩 */
  let overlay =
    document.getElementById(
      "adminDrawerOverlay"
    );

  if (!overlay) {
    overlay =
      document.createElement(
        "div"
      );

    overlay.id =
      "adminDrawerOverlay";

    overlay.style.cssText =
      "display:none;" +
      "position:fixed;" +
      "inset:0;" +
      "z-index:2147482400;" +
      "background:rgba(22,18,15,.45);" +
      "backdrop-filter:blur(3px);" +
      "-webkit-backdrop-filter:blur(3px);";

    document.body.appendChild(
      overlay
    );

    overlay.addEventListener(
      "click",
      closeAdminPanelDrawer
    );
  }

  /* 關閉按鈕 */
  const head =
    panel.querySelector(
      ".admin-dashboard-head"
    );

  if (
    head &&
    !head.querySelector(
      ".worker-admin-drawer-close"
    )
  ) {
    const closeButton =
      document.createElement(
        "button"
      );

    closeButton.type =
      "button";

    closeButton.className =
      "worker-admin-drawer-close";

    closeButton.textContent =
      "× 關閉";

    closeButton.style.cssText =
      "min-height:38px;" +
      "padding:0 12px;" +
      "border-radius:10px;" +
      "font-weight:900;";

    const refreshButton =
      head.querySelector(
        ".admin-refresh-btn"
      );

    if (refreshButton) {
      refreshButton.insertAdjacentElement(
        "beforebegin",
        closeButton
      );
    } else {
      head.appendChild(
        closeButton
      );
    }

    closeButton.addEventListener(
      "click",
      closeAdminPanelDrawer
    );
  }

  badge.style.cursor =
    "pointer";

  badge.setAttribute(
    "role",
    "button"
  );

  badge.setAttribute(
    "tabindex",
    "0"
  );

  badge.setAttribute(
    "aria-expanded",
    "false"
  );

  badge.title =
    "開啟管理後台";

  badge.addEventListener(
    "click",
    toggleAdminPanelDrawer
  );

  badge.addEventListener(
    "keydown",
    function(event) {
      if (
        event.key ===
          "Enter" ||
        event.key ===
          " "
      ) {
        toggleAdminPanelDrawer(
          event
        );
      }
    }
  );

  document.addEventListener(
    "keydown",
    function(event) {
      if (
        event.key ===
          "Escape"
      ) {
        closeAdminPanelDrawer();
      }
    }
  );

  /*
    最重要：安裝完立刻隱藏。
    這樣它不會再佔聊天室半個畫面。
  */
  forceAdminPanelHidden();
}

function showAdmin(
  identity = null
) {
  if (identity) {
    setCurrentAdminIdentity(
      identity
    );
  } else if (
    !currentAdminIdentity
  ) {
    restoreCurrentAdminIdentity();
  }

  document.body.classList.add(
    "admin-mode"
  );

  document
    .getElementById(
      "adminLogin"
    )
    .style.display =
      "none";

  document
    .getElementById(
      "adminBadge"
    )
    .style.display =
      "block";

  installAdminPanelDrawer();
  forceAdminPanelHidden();

  applyAdminRoleUI();

  authenticateAdminSocket();
  loadRoomSettings();
  updateGlobalMuteUI();
  showMembersPanel();

  if (memberTimer) {
    clearInterval(
      memberTimer
    );
  }

  memberTimer =
    setInterval(
      function() {
        if (
          document.visibilityState ===
            "visible" &&
          adminPanelMode ===
            "members" &&
          isAdminContentPanelOpen()
        ) {
          loadMembers();
        }
      },
      15000
    );
}


async function loadRoomSettings() {
  if (!isAdminLoggedIn()) return;

  try {
    const response = await fetch(
      "/api/admin/room-settings?room=" +
      encodeURIComponent(room),
      {
        headers: authHeaders()
      }
    );

    if (response.status === 401) {
      clearAdminLoginState();
      return;
    }

    const data = await response.json();

    if (response.ok && data.ok) {
      setGlobalMuteState(
        !!data.globalMute
      );

      setOnlineVisibilityState(
        data.showOnlineCount !== false
      );

      setCustomOnlineDisplayCountState(
        data.customOnlineCount
      );

      setOnlineRandomState(
        data.onlineRandomEnabled === true,
        data.onlineRandomRange
      );

      setGroupMemberVisibilityState(
        data.showGroupMemberCount !== false
      );

      latestActualGroupMemberCount =
        Number.isFinite(
          Number(data.groupMemberCount)
        )
          ? Math.max(
              0,
              Math.floor(
                Number(data.groupMemberCount)
              )
            )
          : latestActualGroupMemberCount;

      setCustomGroupMemberDisplayCountState(
        data.customGroupMemberCount
      );

      setAdminRoomStats(
        data.onlineCount,
        data.groupMemberCount
      );

      setAnnouncementState(
        data.announcement || ""
      );

      setRoomLockState(
        !!data.roomLocked
      );

      setRoomTitleState(
        data.roomTitle || ""
      );

      setWelcomeMessageState(
        data.welcomeText || ""
      );

      updatePinnedMessagesState(
        data.pinnedMessages || []
      );
    }
  } catch {}
}

/* =====================================================
   ⑦ 管理員編輯 / 清除置頂公告
===================================================== */

async function sendPushTest() {
  if (
    !isAdminLoggedIn() ||
    !isOwnerAdmin()
  ) {
    alert(
      "只有主管理員可以測試推播"
    );
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/push-test",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room
            })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      throw new Error(
        data.message ||
        "推播測試失敗"
      );
    }

    const errorLines =
      Array.isArray(data.errors)
        ? data.errors
            .map(
              function(item, index) {
                const parts = [];

                if (item.endpointHost) {
                  parts.push(
                    item.endpointHost
                  );
                }

                if (item.status) {
                  parts.push(
                    "HTTP " +
                    item.status
                  );
                }

                if (item.error) {
                  parts.push(
                    item.error
                  );
                }

                if (item.responseText) {
                  parts.push(
                    item.responseText
                  );
                }

                return (
                  "#" +
                  (index + 1) +
                  " " +
                  (
                    parts.join("｜") ||
                    "未知錯誤"
                  )
                );
              }
            )
            .join("\n")
        : "";

    alert(
      "推播測試結果\n成功：" +
      Number(
        data.sent || 0
      ) +
      "｜失敗：" +
      Number(
        data.failed || 0
      ) +
      (
        errorLines
          ? "\n\n失敗原因：\n" +
            errorLines
          : ""
      )
    );

  } catch (error) {
    alert(
      error.message ||
      "推播測試失敗"
    );
  }
}

async function editRoomTitle() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const current =
    roomTitleText ||
    "👺哪吒全能娛樂基地🚩";

  const nextTitle =
    prompt(
      "輸入聊天室名稱（最多 40 字）\n\n留空並確認 = 恢復預設名稱",
      current
    );

  if (nextTitle === null) {
    return;
  }

  let cleaned =
    String(nextTitle || "")
      .trim()
      .slice(0, 40);

  if (
    cleaned ===
    "👺哪吒全能娛樂基地🚩"
  ) {
    cleaned = "";
  }

  try {
    const response =
      await fetch(
        "/api/admin/room-title",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            title: cleaned
          })
        }
      );

    let data;

    try {
      data =
        await response.json();
    } catch {
      data = {};
    }

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "聊天室名稱設定失敗"
      );
      return;
    }

    setRoomTitleState(
      data.roomTitle || ""
    );

    alert(
      data.roomTitle
        ? "聊天室名稱已更新 ✅"
        : "已恢復預設聊天室名稱 ✅"
    );

  } catch {
    alert(
      "聊天室名稱設定失敗，請稍後再試"
    );
  }
}

async function editAnnouncement() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const nextText = prompt(
    "輸入置頂公告內容（最多 500 字）：",
    announcementText
  );

  if (nextText === null) {
    return;
  }

  const cleaned = String(nextText || "").trim().slice(0, 500);

  if (!cleaned) {
    alert("公告不能是空白。若要移除公告，請按「清除公告」。");
    return;
  }

  await saveAnnouncement(cleaned);
}

async function clearAnnouncement() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  if (!announcementText) {
    alert("目前沒有置頂公告");
    return;
  }

  if (!confirm("確定清除目前的置頂公告嗎？")) {
    return;
  }

  await saveAnnouncement("");
}

async function saveAnnouncement(text) {
  try {
    const response = await fetch(
      "/api/admin/announcement",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders()
        },
        body: JSON.stringify({
          room,
          text: String(text || "").slice(0, 500)
        })
      }
    );

    let data;

    try {
      data = await response.json();
    } catch {
      data = { ok: false };
    }

    if (!response.ok || !data.ok) {
      alert(data.message || "公告設定失敗");
      return;
    }

    setAnnouncementState(data.announcement || "");

    alert(
      data.announcement
        ? "置頂公告已更新 📌"
        : "置頂公告已清除 ✅"
    );
  } catch {
    alert("公告設定失敗，請稍後再試");
  }
}

async function toggleGlobalMute() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const nextEnabled = !globalMuteEnabled;

  const message = nextEnabled
    ? "確定開啟全體禁言嗎？\n\n開啟後只有管理員可以傳文字或圖片。"
    : "確定關閉全體禁言嗎？\n\n關閉後所有未被個別禁言的會員都可以正常發言。";

  if (!confirm(message)) return;

  try {
    const response = await fetch(
      "/api/admin/global-mute",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders()
        },
        body: JSON.stringify({
          room,
          enabled: nextEnabled
        })
      }
    );

    const data = await response.json();

    if (!response.ok || !data.ok) {
      alert(data.message || "設定失敗");
      return;
    }

    setGlobalMuteState(!!data.globalMute);

    alert(
      data.globalMute
        ? "全體禁言已開啟 🔇\n目前只有管理員可以發言"
        : "全體禁言已關閉 🔊"
    );
  } catch {
    alert("設定失敗，請稍後再試");
  }
}

async function toggleRoomLock() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  const nextEnabled =
    !roomLocked;

  const message =
    nextEnabled
      ? "確定鎖定房間嗎？\n\n🔒 鎖定後新成員暫時無法加入。\n✅ 目前已在線的成員仍可繼續聊天。\n✅ 原本成員斷線自動重連不受影響。"
      : "確定重新開放房間嗎？\n\n開放後新成員就可以再次加入。";

  if (!confirm(message)) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/room-lock",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            enabled:
              nextEnabled
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "房間設定失敗"
      );
      return;
    }

    setRoomLockState(
      !!data.roomLocked
    );

    alert(
      data.roomLocked
        ? "房間已鎖定 🔒\n目前暫停新成員加入"
        : "房間已重新開放 🔓"
    );

  } catch {
    alert(
      "房間設定失敗，請稍後再試"
    );
  }
}

async function clearOldImages() {
  if (!isAdminLoggedIn()) {
    alert("沒有管理員權限");
    return;
  }

  if (!confirm(
    "確定刪除 7 天前的所有圖片嗎？\\n\\n✅ 文字訊息不會刪除\\n✅ 最近 7 天圖片會保留\\n⚠️ 刪除後無法復原"
  )) {
    return;
  }

  try {
    const response = await fetch("/api/admin/clear-old-images", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({ room })
    });

    let data;
    try {
      data = await response.json();
    } catch {
      data = { ok: false };
    }

    if (!response.ok || !data.ok) {
      alert(data.message || "清理失敗");
      return;
    }

    if (data.deleted === 0) {
      alert("目前沒有超過 7 天的圖片 ✅");
    } else {
      alert("清理完成 ✅\\n已刪除 " + data.deleted + " 張舊圖片");
    }
  } catch {
    alert("清理失敗，請稍後再試");
  }
}

async function adminDeleteMessage(messageId, kind) {
  if (!isAdminLoggedIn()) return;

  const label = kind === "image" ? "這張圖片" : "這則訊息";

  if (!confirm("確定刪除" + label + "嗎？")) return;

  try {
    const response = await fetch("/api/admin/delete-message", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...authHeaders()
      },
      body: JSON.stringify({
        room,
        messageId
      })
    });

    const data = await response.json();

    if (!response.ok || !data.ok) {
      alert(data.message || "刪除失敗");
    }
  } catch {
    alert("刪除失敗");
  }
}

function setAdminNavActive(
  mode
) {
  document
    .querySelectorAll(
      ".admin-nav-btn"
    )
    .forEach(
      function(button) {
        button.classList.toggle(
          "active",
          button.dataset.mode ===
            mode
        );
      }
    );
}

function closeAdminTools() {
  const panel =
    document.getElementById(
      "adminToolsPanel"
    );

  const button =
    document.getElementById(
      "adminToolsToggle"
    );

  if (panel) {
    panel.classList.remove(
      "show"
    );
  }

  if (button) {
    button.classList.remove(
      "active"
    );

    button.setAttribute(
      "aria-expanded",
      "false"
    );
  }
}

function toggleAdminTools() {
  const panel =
    document.getElementById(
      "adminToolsPanel"
    );

  const button =
    document.getElementById(
      "adminToolsToggle"
    );

  if (
    !panel ||
    !button
  ) {
    return;
  }

  const willOpen =
    !panel.classList.contains(
      "show"
    );

  panel.classList.toggle(
    "show",
    willOpen
  );

  button.classList.toggle(
    "active",
    willOpen
  );

  button.setAttribute(
    "aria-expanded",
    willOpen
      ? "true"
      : "false"
  );
}


function toggleAdminCountSettings() {
  const button =
    document.getElementById(
      "adminCountSettingsToggle"
    );

  const panel =
    document.getElementById(
      "adminCountSettingsPanel"
    );

  const arrow =
    document.getElementById(
      "adminCountSettingsArrow"
    );

  if (!button || !panel) {
    return;
  }

  const opening =
    !panel.classList.contains(
      "show"
    );

  panel.classList.toggle(
    "show",
    opening
  );

  button.classList.toggle(
    "active",
    opening
  );

  button.setAttribute(
    "aria-expanded",
    opening ? "true" : "false"
  );

  if (arrow) {
    arrow.textContent =
      opening ? "▴" : "▾";
  }
}


function isAdminContentPanelOpen() {
  const card =
    document.getElementById(
      "adminPanelContentCard"
    );

  return !!(
    card &&
    card.style.display !==
      "none"
  );
}

function openAdminContentPanel() {
  const card =
    document.getElementById(
      "adminPanelContentCard"
    );

  if (card) {
    card.style.display =
      "block";
  }
}

function collapseAdminContentPanel() {
  const card =
    document.getElementById(
      "adminPanelContentCard"
    );

  if (card) {
    card.style.display =
      "none";
  }

  setAdminMemberSearchVisible(
    false
  );

  setAdminNavActive(
    ""
  );
}

function toggleAdminPanelMode(
  mode
) {
  if (
    adminPanelMode === mode &&
    isAdminContentPanelOpen()
  ) {
    collapseAdminContentPanel();
    return;
  }

  if (mode === "members") {
    showMembersPanel();
    return;
  }

  if (mode === "reports") {
    showReportsPanel();
    return;
  }

  if (mode === "blocked") {
    showBlockedPanel();
    return;
  }

  if (mode === "logs") {
    showAdminLogPanel();
    return;
  }

  if (mode === "admins") {
    showAdminsPanel();
  }
}

