async function loadAdminAccounts() {
  if (
    !isAdminLoggedIn() ||
    !isOwnerAdmin()
  ) {
    return;
  }

  const list =
    adminAccountList;

  list.innerHTML =
    '<div class="empty">讀取中...</div>';

  try {
    const response =
      await fetch(
        "/api/admin/admins?room=" +
          encodeURIComponent(room),
        {
          headers:
            authHeaders()
        }
      );

    if (response.status === 401) {
      clearAdminLoginState();
      return;
    }

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      list.innerHTML =
        '<div class="empty">' +
        (
          data.message ||
          "讀取失敗"
        ) +
        "</div>";

      return;
    }

    renderAdminAccounts(
      data.admins || []
    );

  } catch {
    list.innerHTML =
      '<div class="empty">讀取失敗</div>';
  }
}

function renderAdminAccounts(
  admins
) {
  adminAccountList.innerHTML =
    "";

  const createBox =
    document.createElement(
      "div"
    );

  createBox.className =
    "admin-account-create";

  const createTitle =
    document.createElement(
      "div"
    );

  createTitle.className =
    "admin-account-create-title";

  createTitle.textContent =
    "＋ 新增管理員";

  const createNote =
    document.createElement(
      "div"
    );

  createNote.className =
    "admin-account-create-note";

  createNote.textContent =
    "主管理員擁有完整管理權限；一般管理員可處理成員、檢舉、禁言、踢出、封鎖、刪訊息與置頂。";

  const createButtons =
    document.createElement(
      "div"
    );

  createButtons.className =
    "admin-account-create-buttons";

  const createOwnerButton =
    document.createElement(
      "button"
    );

  createOwnerButton.type =
    "button";

  createOwnerButton.className =
    "admin-account-add-btn admin-account-add-owner-btn";

  createOwnerButton.textContent =
    "👑 新增主管理員";

  createOwnerButton.onclick =
    function() {
      createAdminAccount(
        "owner"
      );
    };

  const createStaffButton =
    document.createElement(
      "button"
    );

  createStaffButton.type =
    "button";

  createStaffButton.className =
    "admin-account-add-btn";

  createStaffButton.textContent =
    "🛡️ 新增一般管理員";

  createStaffButton.onclick =
    function() {
      createAdminAccount(
        "staff"
      );
    };

  createButtons.appendChild(
    createOwnerButton
  );

  createButtons.appendChild(
    createStaffButton
  );

  createBox.appendChild(
    createTitle
  );

  createBox.appendChild(
    createNote
  );

  createBox.appendChild(
    createButtons
  );

  adminAccountList.appendChild(
    createBox
  );

  if (!admins.length) {
    const empty =
      document.createElement(
        "div"
      );

    empty.className =
      "empty";

    empty.textContent =
      "目前還沒有額外管理員帳號";

    adminAccountList.appendChild(
      empty
    );

    return;
  }

  admins.forEach(
    function(admin) {
      const card =
        document.createElement(
          "div"
        );

      card.className =
        "admin-account-card";

      const top =
        document.createElement(
          "div"
        );

      top.className =
        "admin-account-top";

      const name =
        document.createElement(
          "div"
        );

      name.className =
        "admin-account-name";

      name.textContent =
        (
          admin.role === "owner"
            ? "👑 "
            : "🛡️ "
        ) +
        (
          admin.username ||
          (
            admin.role === "owner"
              ? "主管理員"
              : "一般管理員"
          )
        );

      const status =
        document.createElement(
          "span"
        );

      status.className =
        "admin-account-status " +
        (
          admin.active
            ? "active"
            : "disabled"
        );

      status.textContent =
        admin.active
          ? "啟用中"
          : "已停用";

      top.appendChild(name);
      top.appendChild(status);
      card.appendChild(top);

      const meta =
        document.createElement(
          "div"
        );

      meta.className =
        "admin-account-meta";

      meta.textContent =
        (
          admin.role === "owner"
            ? "主管理員"
            : "一般管理員"
        ) +
        "｜建立 " +
        formatAdminLogTime(
          admin.createdAt
        );

      card.appendChild(meta);

      const actions =
        document.createElement(
          "div"
        );

      actions.className =
        "admin-account-actions";

      const toggle =
        document.createElement(
          "button"
        );

      toggle.type =
        "button";

      toggle.textContent =
        admin.active
          ? "停用"
          : "重新啟用";

      toggle.className =
        admin.active
          ? "admin-account-disable-btn"
          : "admin-account-enable-btn";

      toggle.onclick =
        function() {
          toggleAdminAccount(
            admin
          );
        };

      const password =
        document.createElement(
          "button"
        );

      password.type =
        "button";

      password.className =
        "admin-account-password-btn";

      password.textContent =
        "重設密碼";

      password.onclick =
        function() {
          resetAdminAccountPassword(
            admin
          );
        };

      const remove =
        document.createElement(
          "button"
        );

      remove.type =
        "button";

      remove.className =
        "admin-account-delete-btn";

      remove.textContent =
        "刪除";

      remove.onclick =
        function() {
          deleteAdminAccount(
            admin
          );
        };

      actions.appendChild(toggle);
      actions.appendChild(password);
      actions.appendChild(remove);
      card.appendChild(actions);

      adminAccountList.appendChild(
        card
      );
    }
  );
}

async function adminAccountAction(
  payload
) {
  try {
    const response =
      await fetch(
        "/api/admin/admin-account",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body:
            JSON.stringify({
              room,
              ...payload
            })
        }
      );

    const data =
      await response.json();

    if (response.status === 401) {
      clearAdminLoginState();
      return {
        ok: false
      };
    }

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "管理員帳號操作失敗"
      );

      return {
        ok: false
      };
    }

    loadAdminAccounts();

    return data;

  } catch {
    alert(
      "管理員帳號操作失敗，請稍後再試"
    );

    return {
      ok: false
    };
  }
}

async function createAdminAccount(
  role = "staff"
) {
  const isOwner =
    role === "owner";

  const roleLabel =
    isOwner
      ? "主管理員"
      : "一般管理員";

  const username =
    prompt(
      "輸入" +
      roleLabel +
      "帳號／名稱（2～20字）："
    );

  if (username === null) {
    return;
  }

  const cleaned =
    String(username || "")
      .trim()
      .slice(0, 20);

  if (cleaned.length < 2) {
    alert(
      "管理員帳號至少 2 個字"
    );
    return;
  }

  const password =
    prompt(
      "設定這位管理員的登入密碼（至少 6 個字元）："
    );

  if (password === null) {
    return;
  }

  if (
    String(password).length < 6
  ) {
    alert(
      "管理員密碼至少 6 個字元"
    );
    return;
  }

  const result =
    await adminAccountAction({
      action:
        "create",
      username:
        cleaned,
      password:
        String(password),
      role:
        isOwner
          ? "owner"
          : "staff"
    });

  if (result.ok) {
    alert(
      roleLabel +
      "已新增 ✅\n\n帳號：" +
      cleaned
    );
  }
}

async function toggleAdminAccount(
  admin
) {
  const nextActive =
    !admin.active;

  const roleLabel =
    admin.role === "owner"
      ? "主管理員"
      : "一般管理員";

  if (
    !confirm(
      nextActive
        ? "確定重新啟用" +
          roleLabel +
          "「" +
          admin.username +
          "」嗎？"
        : "確定停用" +
          roleLabel +
          "「" +
          admin.username +
          "」嗎？\n\n停用後，該管理員目前的權限會立即失效。"
    )
  ) {
    return;
  }

  const result =
    await adminAccountAction({
      action:
        "toggle",
      accountId:
        admin.id,
      active:
        nextActive
    });

  if (result.ok) {
    alert(
      nextActive
        ? "管理員已重新啟用 ✅"
        : "管理員已停用 ✅"
    );
  }
}

async function resetAdminAccountPassword(
  admin
) {
  const password =
    prompt(
      "輸入「" +
      admin.username +
      "」的新密碼（至少 6 個字元）："
    );

  if (password === null) {
    return;
  }

  if (
    String(password).length < 6
  ) {
    alert(
      "新密碼至少 6 個字元"
    );
    return;
  }

  const result =
    await adminAccountAction({
      action:
        "password",
      accountId:
        admin.id,
      password:
        String(password)
    });

  if (result.ok) {
    alert(
      "密碼已更新 ✅\n該管理員需要重新登入"
    );
  }
}

async function deleteAdminAccount(
  admin
) {
  const roleLabel =
    admin.role === "owner"
      ? "主管理員"
      : "一般管理員";

  if (
    !confirm(
      "確定刪除" +
      roleLabel +
      "「" +
      admin.username +
      "」嗎？\n\n刪除後無法復原。"
    )
  ) {
    return;
  }

  const result =
    await adminAccountAction({
      action:
        "delete",
      accountId:
        admin.id
    });

  if (result.ok) {
    alert(
      "管理員帳號已刪除 ✅"
    );
  }
}

function refreshAdminPanel() {
  loadRoomSettings();

  if (
    adminPanelMode === "blocked"
  ) {
    loadBlocked();
  } else if (
    adminPanelMode === "logs"
  ) {
    loadAdminActionLog();
  } else if (
    adminPanelMode === "reports"
  ) {
    loadReports();
  } else if (
    adminPanelMode === "admins"
  ) {
    loadAdminAccounts();
  } else {
    loadMembers();
  }
}

async function loadReports() {
  if (!isAdminLoggedIn()) {
    return;
  }

  const list =
    document.getElementById(
      "reportList"
    );

  list.innerHTML =
    '<div class="empty">讀取中...</div>';

  try {
    const response =
      await fetch(
        "/api/admin/reports?room=" +
          encodeURIComponent(room),
        {
          headers:
            authHeaders()
        }
      );

    if (response.status === 401) {
      safeSessionRemove(
        "hd888AdminToken"
      );

      location.reload();
      return;
    }

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      list.innerHTML =
        '<div class="empty">讀取失敗</div>';
      return;
    }

    renderReports(
      data.reports || []
    );

  } catch {
    list.innerHTML =
      '<div class="empty">讀取失敗</div>';
  }
}

function renderReports(reports) {
  const list =
    document.getElementById(
      "reportList"
    );

  list.innerHTML = "";

  if (!reports.length) {
    list.innerHTML =
      '<div class="empty">目前沒有待審核的檢舉 ✅</div>';
    return;
  }

  reports.forEach(
    function(report) {
      const card =
        document.createElement(
          "div"
        );

      card.className =
        "report-admin-card";

      const top =
        document.createElement(
          "div"
        );

      top.className =
        "report-admin-top";

      const name =
        document.createElement(
          "div"
        );

      name.className =
        "report-admin-name";

      name.textContent =
        "👤 " +
        (
          report.senderName ||
          "匿名"
        );

      const count =
        document.createElement(
          "div"
        );

      count.className =
        "report-admin-count";

      count.textContent =
        "⚠️ " +
        Number(
          report.count || 1
        ) +
        " 人檢舉";

      top.appendChild(name);
      top.appendChild(count);
      card.appendChild(top);

      const preview =
        document.createElement(
          "div"
        );

      preview.className =
        "report-admin-preview";

      preview.textContent =
        report.kind === "image"
          ? "📷 被檢舉圖片"
          : (
              report.preview ||
              "訊息"
            );

      card.appendChild(
        preview
      );

      const meta =
        document.createElement(
          "div"
        );

      meta.className =
        "report-admin-meta";

      meta.textContent =
        "訊息時間：" +
        formatAdminLogTime(
          report.messageTime
        );

      card.appendChild(meta);

      const reasons =
        Array.isArray(
          report.reasons
        )
          ? report.reasons
          : [];

      if (reasons.length) {
        const reasonBox =
          document.createElement(
            "div"
          );

        reasonBox.className =
          "report-admin-reasons";

        reasons.forEach(
          function(item) {
            const line =
              document.createElement(
                "div"
              );

            line.textContent =
              "• " +
              (
                item.reason ||
                "其他"
              );

            reasonBox.appendChild(
              line
            );
          }
        );

        card.appendChild(
          reasonBox
        );
      }

      const controls =
        document.createElement(
          "div"
        );

      controls.className =
        "report-admin-controls";

      const muteSelect =
        document.createElement(
          "select"
        );

      muteSelect.className =
        "mute-select";

      muteSelect.innerHTML =
        '<option value="10m">禁言 10 分鐘</option>' +
        '<option value="30m">禁言 30 分鐘</option>' +
        '<option value="1h">禁言 1 小時</option>' +
        '<option value="24h">禁言 24 小時</option>' +
        '<option value="permanent">永久禁言</option>';

      controls.appendChild(
        muteSelect
      );

      controls.appendChild(
        makeButton(
          "禁言",
          "mute-btn",
          function() {
            handleReportAction(
              report,
              "mute",
              muteSelect.value
            );
          }
        )
      );

      controls.appendChild(
        makeButton(
          "刪除訊息",
          "report-delete-btn",
          function() {
            handleReportAction(
              report,
              "delete"
            );
          }
        )
      );

      controls.appendChild(
        makeButton(
          "踢出",
          "kick-btn",
          function() {
            handleReportAction(
              report,
              "kick"
            );
          }
        )
      );

      controls.appendChild(
        makeButton(
          "封鎖",
          "block-btn",
          function() {
            handleReportAction(
              report,
              "block"
            );
          }
        )
      );

      controls.appendChild(
        makeButton(
          "忽略",
          "report-ignore-btn",
          function() {
            handleReportAction(
              report,
              "ignore"
            );
          }
        )
      );

      card.appendChild(
        controls
      );

      list.appendChild(card);
    }
  );
}

async function handleReportAction(
  report,
  action,
  muteDuration = "10m"
) {
  const actionLabels = {
    ignore:
      "忽略這筆檢舉",
    delete:
      "刪除被檢舉訊息",
    mute:
      "禁言「" +
      (
        report.senderName ||
        "匿名"
      ) +
      "」",
    kick:
      "踢出「" +
      (
        report.senderName ||
        "匿名"
      ) +
      "」",
    block:
      "封鎖「" +
      (
        report.senderName ||
        "匿名"
      ) +
      "」"
  };

  if (
    !confirm(
      "確定要" +
      (
        actionLabels[action] ||
        "處理這筆檢舉"
      ) +
      "嗎？"
    )
  ) {
    return;
  }

  try {
    const response =
      await fetch(
        "/api/admin/report-action",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            ...authHeaders()
          },
          body: JSON.stringify({
            room,
            reportKey:
              report.reportKey,
            action,
            muteDuration
          })
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      !data.ok
    ) {
      alert(
        data.message ||
        "處理失敗"
      );
      return;
    }

    alert(
      data.message ||
      "處理完成 ✅"
    );

    loadReports();

  } catch {
    alert(
      "處理失敗，請稍後再試"
    );
  }
}

