function makeButton(text, className, callback) {
  const button = document.createElement("button");
  button.textContent = text;
  button.className = className;
  button.onclick = callback;
  return button;
}

function muteDurationLabel(value) {
  const labels = {
    "10m": "10 分鐘",
    "30m": "30 分鐘",
    "1h": "1 小時",
    "24h": "24 小時",
    "permanent": "永久"
  };

  return labels[value] || "10 分鐘";
}

async function adminMuteMember(member, muteDuration) {
  const label = muteDurationLabel(muteDuration);

  if (!confirm("確定將「" + member.name + "」禁言 " + label + "？")) {
    return;
  }

  const response = await fetch("/api/admin/mute", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...authHeaders()
    },
    body: JSON.stringify({
      room,
      memberId: member.id,
      muteDuration
    })
  });

  const data = await response.json();

  if (!response.ok || !data.ok) {
    alert(data.message || "禁言失敗");
    return;
  }

  alert("已禁言 " + (data.label || label) + " ✅");
  loadMembers();
}

async function adminUnmuteMember(member) {
  if (!confirm("確定解除「" + member.name + "」的禁言？")) {
    return;
  }

  const response = await fetch("/api/admin/unmute", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...authHeaders()
    },
    body: JSON.stringify({
      room,
      memberId: member.id
    })
  });

  const data = await response.json();

  if (!response.ok || !data.ok) {
    alert(data.message || "解除禁言失敗");
    return;
  }

  alert("已解除禁言 ✅");
  loadMembers();
}

async function adminAction(action, member) {
  let text = "";

  if (action === "kick") text = "確定踢出「" + member.name + "」？";
  if (action === "block") text = "確定封鎖「" + member.name + "」？";

  if (!text || !confirm(text)) return;

  const response = await fetch("/api/admin/" + action, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...authHeaders()
    },
    body: JSON.stringify({
      room,
      memberId: member.id
    })
  });

  const data = await response.json();

  if (!response.ok) {
    alert(data.message || "操作失敗");
    return;
  }

  alert(action === "kick" ? "已踢出" : "已封鎖 🔒");

  loadMembers();
}

async function unblockMember(row) {
  if (!confirm("確定解除「" + (row.name || "匿名") + "」的封鎖？")) return;

  const response = await fetch("/api/admin/unblock", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...authHeaders()
    },
    body: JSON.stringify({
      room,
      blockId: row.id
    })
  });

  const data = await response.json();

  if (!response.ok) {
    alert(data.message || "解除失敗");
    return;
  }

  alert("已解除封鎖 ✅");
  loadBlocked();
}

async function clearChatHistory() {
  if (!confirm(
    "確定清除全部聊天紀錄嗎？\\n\\n⚠️ 文字和圖片都會刪除\\n此動作無法復原。"
  )) {
    return;
  }

  const response = await fetch("/api/admin/clear-history", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...authHeaders()
    },
    body: JSON.stringify({ room })
  });

  const data = await response.json();

  if (!response.ok) {
    alert(data.message || "清除失敗");
    return;
  }

  alert("聊天紀錄已清除");
}


/* =========================================================
   ㊷ 管理員共享記事本
   ---------------------------------------------------------
   - 一般會員：唯讀，可把記事文字 / 圖片分享到聊天輸入區
   - 管理員：新增、編輯、刪除、上傳圖片
   - 資料存在聊天室 Durable Object，不是存在單一手機
   - 最多 50 則記事，每則最多 5 張圖片
========================================================= */

