function sharedNotepadEscape(
  value
) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function formatSharedNotepadTime(
  timestamp
) {
  const value =
    Number(timestamp || 0);

  if (!value) {
    return "";
  }

  try {
    return new Intl.DateTimeFormat(
      "zh-TW",
      {
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }
    ).format(
      new Date(value)
    );
  } catch {
    return "";
  }
}

